-- ============================================
-- 从 insect.json 同步昆虫物种到自然观察数据层
-- ============================================

WITH source AS (
  SELECT *
  FROM jsonb_to_recordset($insects$[{"slug":"neallogaster-pekinensis","common_name":"北京角臀大蜓","scientific_name":"Neallogaster pekinensis","aliases":["北京大蜓"],"taxon_group":"蜻蜓目 大蜓科","identification_notes":"体长 71–80 mm。腹部背面有成对的黄斑，且成对大斑与成对小斑相间分布。腹部纤细、收狭且体斑细碎。","habitat_notes":"出没于北京中、高海拔的深山溪流环境。如松山、玉渡山、小龙门、百花山、龙门洞、雾灵山、云蒙山等地的山间小溪。","seasonality_notes":"成虫 6–7 月最盛，至 8 月已难觅。","cover_image_url":"/insects/images/neallogaster-pekinensis-1.jpg","is_active":true},{"slug":"anotogaster-kuchenbeiseri","common_name":"双斑圆臀大蜓","scientific_name":"Anotogaster kuchenbeiseri","aliases":[],"taxon_group":"蜻蜓目 大蜓科","identification_notes":"体长 80–95 mm。北京地区最大型的蜻蜓。复眼翠绿色，足纯黑色，身体余部具黑黄相间的条纹，腹部的黄色条纹形成环状。","habitat_notes":"清澈、海拔较低的山间小溪，或开阔敞亮的低海拔水面（如拒马河、密云水库）。有时亦出没于高海拔山地溪流的开阔环境。","seasonality_notes":"成虫 6–9 月均为盛发期，部分低海拔流域 10 月初仍可见。","cover_image_url":"/insects/images/anotogaster-kuchenbeiseri-1.jpg","is_active":true},{"slug":"anax-parthenope-julius","common_name":"碧伟蜓","scientific_name":"Anax parthenope julius","aliases":["老刚儿(♂)","老紫儿(♀)","单杆儿","捞滋儿","老琉璃"],"taxon_group":"蜻蜓目 蜓科","identification_notes":"体长 68–76 mm。大型蜻蜓，复眼与合胸翠绿色。雄性腹部第 2–3 节为蓝色，第 4–10 节黑色带淡黄绿色纵纹；老熟雌性腹部常呈纯粹的紫红色。","habitat_notes":"多见于除郁闭林荫小溪外的任何水域，如河、湖、池塘、沟渠、鱼坑等地遍布，甚至在一些臭水河中其幼虫都可生存。","seasonality_notes":"成虫 5–9 月多见，在城市热岛效应下北京城区 4 月初即可见到。","cover_image_url":"/insects/images/anax-parthenope-julius-1.jpg","is_active":true},{"slug":"anax-nigrofasciatus","common_name":"黑纹伟蜓","scientific_name":"Anax nigrofasciatus","aliases":[],"taxon_group":"蜻蜓目 蜓科","identification_notes":"体长 75–80 mm。与碧伟蜓相似，但复眼呈蓝色。合胸翠绿色、侧面具有 2 条黑纹。雄性腹部具天蓝色点状斑纹；足纯黑色。","habitat_notes":"山区、近山地带特色物种。多见于较洁净的低山溪流流域，以及近山的河流、水库、池塘。不出现于平原城区。","seasonality_notes":"雄成虫 5–8 月多见，少数成虫可存活至 9 月上半月。","cover_image_url":"/insects/images/anax-nigrofasciatus-1.jpg","is_active":true},{"slug":"planaeschna-shanxiensis","common_name":"山西黑额蜓","scientific_name":"Planaeschna shanxiensis","aliases":[],"taxon_group":"蜻蜓目 蜓科","identification_notes":"体长 68–70 mm。中大型蜻蜓，体多黄绿色与黑色相间斑纹。腹部背面具有一系列成对的黄绿色三角形碎斑，形成‘一排正向、一排逆向’反复交替的独特序列。","habitat_notes":"北京山区大范围广布的极常见的固有种。多见于较洁净的中、低山溪流流域，于山区的水库、池塘也可见。","seasonality_notes":"成虫 7–9 月多见。9 月上半月可见大量雌性成虫在苔藓多的水岸交界处弯腹产卵。","cover_image_url":"/insects/images/planaeschna-shanxiensis-1.jpg","is_active":true},{"slug":"cephalaeschna-patrorum","common_name":"长者头蜓","scientific_name":"Cephalaeschna patrorum","aliases":[],"taxon_group":"蜻蜓目 蜓科","identification_notes":"体长 69–71 mm。中大型蜻蜓。腹部背面成对的黄绿色碎斑在腹部中部形成‘一排黄色、一排绿色’反复交替颜色的独特序列。远观斑纹向两侧延伸更像‘环纹’。","habitat_notes":"好生境为中、高海拔林荫下的溪流，为荫蔽环境下中、高海拔的优势蜓种。近山的较开阔水面也有，但从不下到海拔极低处。","seasonality_notes":"成虫 8–9 月多见于深山区中、高海拔的清澈小溪流域。","cover_image_url":"/insects/images/cephalaeschna-patrorum-1.jpg","is_active":true},{"slug":"aeshna-mixta","common_name":"混合蜓","scientific_name":"Aeshna mixta","aliases":[],"taxon_group":"蜻蜓目 蜓科","identification_notes":"体长 56–64 mm。中大型。雄性复眼蓝色，腹部具一系列天蓝色碎斑；雌性多型（绿色、黄绿色或蓝色）。合胸侧面具绿色与褐色相间的宽条纹，密被绒毛。","habitat_notes":"在北京分布广泛却不易见到。喜高飞，大部分时间在高空或深山中，仅在短暂时间内下到低海拔水域边巡飞、繁殖。","seasonality_notes":"成虫 6–9 月出现，但仅 8、9 月之交才来到低海拔的水域巡飞、繁殖，为观察最佳时机。","cover_image_url":"/insects/images/aeshna-mixta-1.jpg","is_active":true},{"slug":"aeshna-subarctica","common_name":"极北蜓","scientific_name":"Aeshna subarctica","aliases":[],"taxon_group":"蜻蜓目 蜓科","identification_notes":"体长 70–76 mm。大型且绚丽。雄性复眼蓝绿色，腹部具许多大小相间的天蓝色斑纹；雌性多型。合胸侧面具有‘黄—绿’过渡色的宽条纹。曾被误定为峻蜓。","habitat_notes":"北京分布极为狭窄，数量非常稀少。已知在北京的产地仅有喇叭沟门、小龙门、雾灵山三处，常在 8、9 月之交来到中、高海拔山区的溪流边。","seasonality_notes":"仅有的数次发现记录大多在 8 月下半月至 9 月上半月。推测成虫在 7 月即羽化但隐匿于深山或高空。","cover_image_url":"/insects/images/aeshna-subarctica-1.jpg","is_active":true},{"slug":"aeschnophlebia-longistigma","common_name":"长痣绿蜓","scientific_name":"Aeschnophlebia longistigma","aliases":[],"taxon_group":"蜻蜓目 蜓科","identification_notes":"体长 67–69 mm。中大型蜻蜓。复眼、合胸与腹部大部分区域均为绿色，腹部有黑色纵纹。雄性足黑色，雌性各足腿节大部分为明显的红色。对环境破坏敏感。","habitat_notes":"芦苇丛的特色物种。见于有大面积芦苇丛且多年未改造、破坏环境的地方，在水边的其他茂密植物缝隙间缓慢巡飞。","seasonality_notes":"成虫 5–7 月出现在芦苇丛中，6 月为发生期高峰，到 7 月多仅剩老残个体。","cover_image_url":"/insects/images/aeschnophlebia-longistigma-1.jpg","is_active":true},{"slug":"gomphidia-confluens","common_name":"联纹小叶春蜓","scientific_name":"Gomphidia confluens","aliases":["膏药","铁铳子"],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 73–75 mm。粗壮的大型蜻蜓。具有黑黄相间条纹，复眼绿色偏晦暗。腹末膨大呈梭状使整个腹部似箭状。其腹末 4 节（第 7–10 节）形态独特。","habitat_notes":"最见于近山或山区中、低海拔的开阔水域，如河流、大溪流、水库、池塘。甚常见停落于水岸相接处的突兀枝头、草杆顶端。","seasonality_notes":"5–8 月皆常见，初羽化个体多栖息于距离水域较远的山上，约 6 月中旬开始在水边数量极多。","cover_image_url":"/insects/images/gomphidia-confluens-1.jpg","is_active":true},{"slug":"sinictinogomphus-clavatus","common_name":"大团扇春蜓","scientific_name":"Sinictinogomphus clavatus","aliases":["膏药","片儿膏药","铜钱儿"],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 69–71 mm。极具特色，腹部第 8 节两侧具有极度扩展的近半圆形片状结构。颜色为黑黄相间。北京少有的能在平原见到的大型、靓丽的蜻蜓。","habitat_notes":"喜静水，在北京的平原大湖（如颐和园、圆明园）常见，于山区流速缓慢的宽阔水域也有分布。","seasonality_notes":"5–9 月可见成虫，山区种群的发生期为 6–8 月。","cover_image_url":"/insects/images/sinictinogomphus-clavatus-1.jpg","is_active":true},{"slug":"sieboldius-albardae","common_name":"艾氏施春蜓","scientific_name":"Sieboldius albardae","aliases":[],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 78–81 mm。后足极长，头部显得很小。复眼绿色稍显晦暗，合胸与腹部具有黑黄相间的斑纹。","habitat_notes":"北京山区溪流间最常见的春蜓。常见于各大山区景点中暴露的、不被林荫遮蔽的溪流。可沿溪谷在水中和水边的石头上寻找。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/sieboldius-albardae-1.jpg","is_active":true},{"slug":"ophiogomphus-spinicornis","common_name":"棘角蛇纹春蜓","scientific_name":"Ophiogomphus spinicornis","aliases":["二国"],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 57–63 mm。中型蜻蜓，头、合胸与腹部前端以极鲜艳的近乎荧光绿的绿色为主色调。属于国家二级保护动物。","habitat_notes":"分布较广，但仅有限的一些地方易见。松山、雾灵山、碓臼峪等地为最适合观察本种的地点。","seasonality_notes":"7–9 月可见成虫。","cover_image_url":"/insects/images/ophiogomphus-spinicornis-1.jpg","is_active":true},{"slug":"gastrogomphus-abdominalis","common_name":"长腹春蜓","scientific_name":"Gastrogomphus abdominalis","aliases":[],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 62–66 mm。头、合胸、腹部均以绿色为主色调，新羽化为亮眼鲜绿色，成熟变黄绿色。腹部显长且直。中国特有种，属独种属。","habitat_notes":"成虫喜开阔静水，急流河段不会有。如今仅在白河流域、怀沙河流域、碓臼峪等地残存不多的种群。城区种群或已趋灭绝。","seasonality_notes":"出现较早，于 5–7 月可见。在山区其出现的高峰期推迟到 5 月底前后始见。","cover_image_url":"/insects/images/gastrogomphus-abdominalis-1.jpg","is_active":true},{"slug":"dubitogomphus-bicornutus","common_name":"双角戴春蜓","scientific_name":"Dubitogomphus bicornutus","aliases":[],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 56–62 mm。复眼绿色显晦暗，体具黑黄相间斑纹。腹部第 3–9 节前端具一对黄色斑点。雌性头顶具有一对尖角状凸起。原归属于戴春蜓属。","habitat_notes":"在北京山区分布较广，但数量不多。可在碓臼峪、云蒙山等地沿溪流寻找。","seasonality_notes":"6–8 月间可见成虫。","cover_image_url":"/insects/images/dubitogomphus-bicornutus-1.jpg","is_active":true},{"slug":"burmagomphus-collaris","common_name":"领纹缅春蜓","scientific_name":"Burmagomphus collaris","aliases":[],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 42–46 mm。北京最小型的一种春蜓。复眼翠绿色，体具黑黄相间条纹，腹部第 9 节的黄斑俯视时为近三角形。常紧贴水面飞行。","habitat_notes":"喜开阔的低海拔急流，仅出没在流速湍急区域。白河流域、拒马河流域均有分布，十渡一带具有较多数量。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/burmagomphus-collaris-1.jpg","is_active":true},{"slug":"lamelligomphus-ringens","common_name":"环纹环尾春蜓","scientific_name":"Lamelligomphus ringens","aliases":[],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 61–63 mm。复眼呈现纯净、迷人的湖蓝色，在北京所有蜻蜓中独一无二。雄性腹部末端具有两对拔钉钳般的肛附器；腹部第 3–7 节具粗大黄色环纹。","habitat_notes":"急流流域特有物种。强烈‘眷恋’着有许多石头露出水面的山区河流和宽阔溪流，雄性常停落于石块上休息。","seasonality_notes":"可于 6–9 月在山区多石急流环境中寻找本种。","cover_image_url":"/insects/images/lamelligomphus-ringens-1.jpg","is_active":true},{"slug":"anisogomphus-maacki","common_name":"马奇异春蜓","scientific_name":"Anisogomphus maacki","aliases":[],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 49–54 mm。雄性腹部末端强烈膨阔，停歇时常高举腹部甚至垂直指向天空。无论雌雄，腹部背面第 2–7 节正中央均具有纵贯的黄色极细直线。","habitat_notes":"见于山区水质较好的开阔河流，从低海拔到中海拔皆有。拒马河流域具有较大数量，常见雄虫长时间停落于河流间和岸边的大石头上。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/anisogomphus-maacki-1.jpg","is_active":true},{"slug":"asiagomphus-hesperius","common_name":"西南亚春蜓","scientific_name":"Asiagomphus hesperius","aliases":[],"taxon_group":"蜻蜓目 春蜓科","identification_notes":"体长 63–69 mm。复眼绿色，体具黑黄相间斑纹。腹部第 3–6 节背面正中央具黄色细纵纹；第 7 节前半部为黄色；第 8 节背板两侧为黄色；第 9 节背板末端黄色。","habitat_notes":"2020 年 6 月新发现种。固有分布范围至少覆盖了密云、怀柔山区清澈、开阔的大型河流（如怀沙河流域、白河流域、水长城）。","seasonality_notes":"目前确凿能观察到成虫的月份是 6–7 月，推测 5 月即出现。","cover_image_url":"/insects/images/asiagomphus-hesperius-1.jpg","is_active":true},{"slug":"epophthalmia-elegans","common_name":"闪蓝丽大伪蜻","scientific_name":"Epophthalmia elegans","aliases":["膏药"],"taxon_group":"蜻蜓目 大伪蜻科","identification_notes":"体长 76–82 mm。大型蜻蜓。复眼翠绿色，合胸暗色区域带强烈的墨绿色金属光泽；腹部末端具有 1 个黄色大斑与 1 条横状黄线。","habitat_notes":"可见于市区各大公园的湖泊、池塘，于低海拔水库、平原河流的平静流域也多见。占据平原水系环境。","seasonality_notes":"5–9 月可见成虫。","cover_image_url":"/insects/images/epophthalmia-elegans-1.jpg","is_active":true},{"slug":"macromia-beijingensis","common_name":"北京大伪蜻","scientific_name":"Macromia beijingensis","aliases":["北京弓蜻"],"taxon_group":"蜻蜓目 大伪蜻科","identification_notes":"体长 71–75 mm。唯二以‘北京’命名的蜻蜓之一。复眼翠绿色，合胸暗色区域带墨绿色金属光泽。腹部末端具有 2 个黄色大斑。与闪蓝丽大伪蜻生境几乎无交集。","habitat_notes":"仅见于山区有较好森林环境下的溪流中。虎峪、碓臼峪、雾灵山、云蒙山、玉渡山等景区的溪流流域都有栖息。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/macromia-beijingensis-1.jpg","is_active":true},{"slug":"macromia-manchurica","common_name":"东北大伪蜻","scientific_name":"Macromia manchurica","aliases":["东北弓蜻"],"taxon_group":"蜻蜓目 大伪蜻科","identification_notes":"体长 70–73 mm。复眼翠绿色，合胸暗色区域带强烈墨绿色金属光泽。腹部末端具有 1 个黄色大斑，无横线。比北京大伪蜻更具环境适应性。","habitat_notes":"分布广泛，见于山区河流、溪流，或近山的河流。不见于平原静水湖泊、池塘。拒马河流域、永定河流域、小龙门、百花山、玉渡山等有分布。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/macromia-manchurica-1.jpg","is_active":true},{"slug":"somatochlora-exuberata","common_name":"日本金光伪蜻","scientific_name":"Somatochlora exuberata","aliases":[],"taxon_group":"蜻蜓目 伪蜻科","identification_notes":"体长 51–55 mm。中等大小。复眼翠绿色，合胸暗绿色具强烈金属光泽。雄性上肛附器呈夹形（基部远端部并拢）；雌性下生殖板极长。曾长期被鉴定为 S. japonica。","habitat_notes":"在北京山区中等海拔的池塘和溪流广泛分布，在流速缓慢处可有较大数量。水域周边需要有茂密的森林。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/somatochlora-exuberata-1.jpg","is_active":true},{"slug":"somatochlora-shanxiensis","common_name":"山西金光伪蜻","scientific_name":"Somatochlora shanxiensis","aliases":[],"taxon_group":"蜻蜓目 伪蜻科","identification_notes":"体长 52–55 mm。复眼翠绿色，合胸暗绿色具强烈金属光泽。雄性上肛附器呈叉形（基部并拢端部相距渐远）；雌性下生殖板短小。北京原记载的‘格氏金光伪蜻’实际多为此种。","habitat_notes":"见于北京山区中等海拔的一些池塘和溪流，如云蒙山、松山、碓臼峪、虎峪。需要水域周边有茂密的森林。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/somatochlora-shanxiensis-1.jpg","is_active":true},{"slug":"epitheca-marginata","common_name":"缘斑毛伪蜻","scientific_name":"Epitheca marginata","aliases":[],"taxon_group":"蜻蜓目 伪蜻科","identification_notes":"体长 52–54 mm。少有的早春蜻蜓。复眼翠绿色，合胸、腹部均具黑黄相间斑纹。体具绒毛（合胸与头部苍灰色直立毛明显）。有些雌性翅前缘带黑条状斑纹。","habitat_notes":"见于北京平原湿地和近山河流、水库的静静水面上。在河流环境中仅出没于流速缓慢的地方。多见于接近死水、伴随一定富营养化的水域。","seasonality_notes":"4–7 月可见成虫。","cover_image_url":"/insects/images/epitheca-marginata-1.jpg","is_active":true},{"slug":"libellula-angelina","common_name":"低斑蜻","scientific_name":"Libellula angelina","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 38–43 mm。雄性黑褐色，雌性黄褐色。翅基部、中部、端部各具有黑斑（共 12 个斑，远观似 8 个）。在‘世界红色物种名录’中被评为‘极危’物种。","habitat_notes":"原广布于北京的平原湖泊、池塘、静水河流，现今仅在少数经生态修复工程而恢复或人工新建的湿地可见。通常安静地落在挺水植物间。","seasonality_notes":"3–5 月可见成虫。曾是北京最早出现的差翅亚目蜻蜓。","cover_image_url":"/insects/images/libellula-angelina-1.jpg","is_active":true},{"slug":"libellula-quadrimaculata","common_name":"小斑蜻","scientific_name":"Libellula quadrimaculata","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 42–47 mm。2017 年新记录物种。以黄褐色为主，腹部背面中央的黑色斑纹仅存在于腹末；前翅基部无黑斑仅发黄，后翅基部有黑斑。色彩比低斑蜻明朗清晰。","habitat_notes":"在北京数量极少。目前仅密云区石城镇、延庆区妫水河流域等极少数地点有记录。比低斑蜻更喜稍具海拔的生境，有时混在低斑蜻出没的地方。","seasonality_notes":"4–5 月可见成虫。","cover_image_url":"/insects/images/libellula-quadrimaculata-1.jpg","is_active":true},{"slug":"pantala-flavescens","common_name":"黄蜻","scientific_name":"Pantala flavescens","aliases":["小黄儿(♀)","红辣椒儿(♂)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 49–50 mm。北京最常见的蜻蜓。体黄褐色，雄性腹部背面红色，雌性腹部具斑驳花纹且中央黑纹明显。雌性翅痣黄色，雄性翅痣红色。复眼上暗红下蓝灰。","habitat_notes":"可繁殖于北京一切静水环境。多见于北京平原任何水域（湖泊、池塘、沟渠、河流甚至雨后水洼），在山区也遍布各地但不如平原密集。","seasonality_notes":"4–10 月可见成虫。过去曾常见成千上万黄蜻于雨前成群低飞。","cover_image_url":"/insects/images/pantala-flavescens-1.jpg","is_active":true},{"slug":"crocothemis-servilia","common_name":"红蜻","scientific_name":"Crocothemis servilia","aliases":["小黄儿(黄色型♀)","红辣椒儿(♂、红色型♀)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 44–47 mm。雄性通体红色；雌性常见黄色型，亦有红色型。翅透明，基部具有橙色斑，翅前缘也显橙黄色。常‘翘尾立于荷花上’。","habitat_notes":"相当常见且分布广泛。多见于北京平原地区水草茂盛的湿地、池塘与缓速河流边，喜停落在草尖上。于山区仅低山常见，中高海拔没有。","seasonality_notes":"4–10 月均可见成虫。","cover_image_url":"/insects/images/crocothemis-servilia-1.jpg","is_active":true},{"slug":"orthetrum-albistylum","common_name":"白尾灰蜻","scientific_name":"Orthetrum albistylum","aliases":["灰儿","老灰儿","小灰儿"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 50–56 mm。数量最多。雄性体被灰白色略发蓝色的粉霜（腹部第 7–10 节露出黑色）；雌性常见无粉霜显黄白黑三色条纹者。无论雌雄腹部最末端均为白色。","habitat_notes":"多见于北京低海拔静水水系，湖泊、池塘、沟渠、水流不急的河流均有大量。在中等海拔山区也能见到。常见其停歇在岸边石头或地面上。","seasonality_notes":"4–10 月均可见成虫。","cover_image_url":"/insects/images/orthetrum-albistylum-1.jpg","is_active":true},{"slug":"orthetrum-lineostigma","common_name":"线痣灰蜻","scientific_name":"Orthetrum lineostigma","aliases":["灰儿","老灰儿","小灰儿"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 41–45 mm。体形明显小于白尾灰蜻。雄性体被灰白略发蓝粉霜；雌性体色淡黄具发达黑纹。无论雌雄翅尖端略褐色，翅痣半黑半黄（像画了一条线）。","habitat_notes":"几乎仅见于山区，北京第二常见的灰蜻。多见于北京低海拔到中海拔山区水草丰茂的水域。永定河流域、拒马河流域尤其多，也易见于山地溪流。","seasonality_notes":"5–9 月可见成虫。","cover_image_url":"/insects/images/orthetrum-lineostigma-1.jpg","is_active":true},{"slug":"orthetrum-melania","common_name":"异色灰蜻","scientific_name":"Orthetrum melania","aliases":["灰儿(♂)","老灰儿(♂)","小灰儿(♂)","铁灰儿(♂)","小老虎儿(♀)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 51–55 mm。体长与白尾灰蜻相仿但更粗壮。雄性合胸和腹部前 7 节被灰中发蓝的粉霜覆盖，腹末完全黑色，后翅基部具明显黑斑；雌性黄黑相间条纹，尾毛白色。","habitat_notes":"北京第三常见的灰蜻，仅近山和低山地带较易见。大多栖息于北京低海拔山区和山脚下的池塘、湖泊、水库、沟渠。最容易观察到的地点首推北京植物园。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/orthetrum-melania-1.jpg","is_active":true},{"slug":"orthetrum-brunneum","common_name":"天蓝灰蜻","scientific_name":"Orthetrum brunneum","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 41–50 mm。2017 年新记录种。雄性合胸和腹部被灰白色略发蓝粉霜，易与线痣灰蜻混淆但体稍大、翅尖不为褐色。无论雌雄翅均透明无斑，翅痣均为黑黄二色。","habitat_notes":"见于溪流、沟渠环境，目前仅发现于喇叭沟门、碓臼峪等极少数地点。","seasonality_notes":"7–8 月可见成虫。","cover_image_url":"/insects/images/orthetrum-brunneum-1.jpg","is_active":true},{"slug":"orthetrum-cancellatum","common_name":"粗灰蜻","scientific_name":"Orthetrum cancellatum","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 44–52 mm。2006 年新记录种。多数个体的合胸生有大量灰白色的直立绒毛。雄性腹末三节黑色，复眼颜色晦暗；雌性黄色具黑纹，尾毛黑色。翅无任何黑斑。","habitat_notes":"在北京山区数量稀少，不易见到。喜山间水库和池塘。目前仅知密云白道峪、延庆松山至兰角沟一带可见。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/orthetrum-cancellatum-1.jpg","is_active":true},{"slug":"deielia-phaon","common_name":"异色多纹蜻","scientific_name":"Deielia phaon","aliases":["灰儿(♂/灰色型♀)","小灰儿(♂/灰色型♀)","小老虎儿(橙色型♀)","小黄金(橙色型♀)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 40–42 mm。小巧玲珑。雄性合胸与腹部被灰白色粉霜覆盖（易与白尾灰蜻混淆）；雌性多型：灰色型具浅粉霜；橙色型无粉霜露出鲜艳黄黑相间条纹，翅或多或少为红色。","habitat_notes":"常见种。在北京平原地区水草丰茂的池塘与湖泊甚常见（如龙潭湖、圆明园、北京植物园），在低海拔山区的河流、溪流、水库、池塘也有分布。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/deielia-phaon-1.jpg","is_active":true},{"slug":"pseudothemis-zonata","common_name":"玉带蜻","scientific_name":"Pseudothemis zonata","aliases":["三半截儿","白圈儿","黄圈儿","白腰儿","黄腰儿"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 44–46 mm。配色独特，‘腰部’有白色或黄色的一段斑纹，其余大部为黑色。成熟雄性腹部第 2–4 节为白色；无论雌雄，后翅基部都有黑斑，各翅翅尖也染黑褐色。","habitat_notes":"甚常见。多见于北京平原地区水草丰茂的、年代久远的池塘、湖泊、静水河流，如龙潭湖、转河、圆明园、颐和园、北京植物园等地。","seasonality_notes":"6–10 月可见成虫。雄性在水面低空巡飞，雌性喜在高空捕食。","cover_image_url":"/insects/images/pseudothemis-zonata-1.jpg","is_active":true},{"slug":"rhyothemis-fuliginosa","common_name":"黑丽翅蜻","scientific_name":"Rhyothemis fuliginosa","aliases":["黑锅底","黑老婆儿"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 31–36 mm。外观独特。身体短小但翅面异常宽大，全身大部分为黑色（部分个体具雾霾蓝色粉霜）。在特定角度下近观，翅面具有非常绚丽的七彩干涉虹彩。","habitat_notes":"分布于北京平原地区水草丰茂的、年代久远的池塘、湖泊、湿地，但数量不多。飞行缓慢而摇曳，以不断转向的飘飞为主且较喜高飞，有时被误认为是蝴蝶。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/rhyothemis-fuliginosa-1.jpg","is_active":true},{"slug":"selysiothemis-nigra","common_name":"黑赛丽蜻","scientific_name":"Selysiothemis nigra","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 30–38 mm。2016 年新记录物种。在兼顾的蜻科中属于小型种类，颜色晦暗。雄性体黑色具深褐色斑纹与白色长毛；雌性暗黄声带黑纹与白长毛。该属为一独种属。","habitat_notes":"难得一见的稀少种类，行踪不定，出现有一定随机性。北京地区的固定产地目前仅圆明园，玉渊潭公园也曾有过记录。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/selysiothemis-nigra-1.jpg","is_active":true},{"slug":"sympetrum-eroticum","common_name":"竖眉赤蜻","scientific_name":"Sympetrum eroticum","aliases":["小辣椒儿(♂)","小老虎儿(♀)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 33–40 mm。北京最常见的赤蜻之一。体形小巧。雄性成熟个体腹部鲜艳红色，未熟个体橙色，上肛附器向上强烈弯翘（独一无二）；雌性黄色偏橙有显著黑纹。","habitat_notes":"几乎可见于除高海拔以外的任何地点，在水边和山林中均不时见到。常停落在草叶或枯枝上，受到惊扰常仅略飞出不远又落回。","seasonality_notes":"6–10 月可见成虫。","cover_image_url":"/insects/images/sympetrum-eroticum-1.jpg","is_active":true},{"slug":"sympetrum-fonscolombei","common_name":"方氏赤蜻","scientific_name":"Sympetrum fonscolombei","aliases":["红辣椒儿(♂)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 35–41 mm。中型。最常见的赤蜻之一。雄性合胸具有黄色、黑色、雾霾色等混搭条纹（最斑斓）；无论雌雄，腹部背面中央的条纹均仅见于第 8、9 节。","habitat_notes":"更常见于山区，如碓臼峪、虎峪、小龙门等地均常见；城区部分水草丰茂的湖泊与湿地也有分布（如圆明园）。","seasonality_notes":"6–10 月可见成虫。","cover_image_url":"/insects/images/sympetrum-fonscolombei-1.jpg","is_active":true},{"slug":"sympetrum-striolatum","common_name":"条斑赤蜻","scientific_name":"Sympetrum striolatum","aliases":["红辣椒儿(♂、红色型♀)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 36–45 mm。中型。数量巨大，密集分布。雄性腹部鲜红；雌性分红色型和黄色型。与普赤蜻极易混淆。无论雌雄，四翅前缘的一些翅脉都为金黄色到橙红色。","habitat_notes":"在城区的河流、池塘、湖泊均常见（如凉水河、永定河），在中、低海拔山区的溪流、水库、池塘也遍布，且数量极大、部分地点相当密集。","seasonality_notes":"6–10 月可见成虫，城区中的种群可存活至 11 月中旬。","cover_image_url":"/insects/images/sympetrum-striolatum-1.jpg","is_active":true},{"slug":"sympetrum-vulgatum","common_name":"普赤蜻","scientific_name":"Sympetrum vulgatum","aliases":["红辣椒儿(♂)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 35–40 mm。2018 年新记录种。与条斑赤蜻极相似。显著差异是：雄性下肛附器比条斑赤蜻短而弯；雌性下生殖板尖长，好像腹下方凸出一个尖锥。","habitat_notes":"在郊区和山区广泛分布，或混于大量条斑赤蜻中。目前在永定河河畔、碓臼峪、雾灵山等远、近郊区均有发现。","seasonality_notes":"确凿记录在 6–9 月见过成虫，由于与条斑赤蜻相似，可能 10 月仍能见到。","cover_image_url":"/insects/images/sympetrum-vulgatum-1.jpg","is_active":true},{"slug":"sympetrum-depressiusculum","common_name":"扁腹赤蜻","scientific_name":"Sympetrum depressiusculum","aliases":["大陆秋赤蜻","红辣椒儿(♂、红色型♀)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 27–40 mm。中型偏小。腹部黑斑常较浅、若隐若现，但第 8、9 节背面中央黑斑较浓重。额侧面与复眼相接处或多或少具有黑斑。与普赤蜻较难区分。","habitat_notes":"在北京郊区和山区分布广泛，但数量较少，不易见。妫水河流域、雾灵山低海拔沙河流域、上庄水库、汉石桥湿地、北京植物园均有记录。","seasonality_notes":"6–10 月可见成虫。","cover_image_url":"/insects/images/sympetrum-depressiusculum-1.jpg","is_active":true},{"slug":"sympetrum-speciosum","common_name":"黄基赤蜻","scientific_name":"Sympetrum speciosum","aliases":["红辣椒儿(♂)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 40–45 mm。粗壮的赤蜻。无论雌雄后翅基部均具一块较大橙黄色区域，合胸侧面具 2 条很宽黑纹，腹部腹面具大量黑纹，足与翅痣也为黑色。雄性非常艳红。","habitat_notes":"在北京山区或近山的静水水域栖息，如北京植物园、松山、虎峪、黑龙潭等地的池塘和水库；平原地区也有记录，但数量稀少。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/sympetrum-speciosum-1.jpg","is_active":true},{"slug":"sympetrum-kunckeli","common_name":"小黄赤蜻","scientific_name":"Sympetrum kunckeli","aliases":["小辣椒儿(♂)","小老虎儿(♀)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 29–40 mm。北京最小的蜻之一。合胸花纹丰富清晰，腹末端白色。翅痣很有特色（两端白色中间黑色，独一无二）。成熟雄性的额为水青色（独一无二）。","habitat_notes":"栖息于北京低海拔地区挺水植物生长茂盛的静水水域，如上庄水库、圆明园、颐和园、奥林匹克森林公园、海淀公园等。","seasonality_notes":"6–10 月可见成虫，但本种出现较晚，8 月末才开始多见。","cover_image_url":"/insects/images/sympetrum-kunckeli-1.jpg","is_active":true},{"slug":"sympetrum-croceolum","common_name":"半黄赤蜻","scientific_name":"Sympetrum croceolum","aliases":["红辣椒儿(♂)"],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 37–48 mm。各翅基部、端部和前缘均为橙黄色到橙红色（约占翅面积一半）。无论雌雄，合胸上均无任何明显的深色条纹。在山区晚秋常为优势种，显得最红。","habitat_notes":"在北京山区溪流、河流流域的开阔、缓流水域常见。多见于碓臼峪、拒马河流域、永定河山区段、密云清水河流域、门头沟清水涧、松山等地。","seasonality_notes":"7–10 月可见成虫，8 月以后较多，出现较晚且存活到较晚月份。","cover_image_url":"/insects/images/sympetrum-croceolum-1.jpg","is_active":true},{"slug":"sympetrum-uniforme","common_name":"大黄赤蜻","scientific_name":"Sympetrum uniforme","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 42–47 mm。北京最少见的固有物种之一。雌雄相似且通体黄色（着色均匀），四翅完全黄色。雄性无论多么年老也不显红色。红蜻雌性腹更宽且有黑纵线，可作区分。","habitat_notes":"在北京没有任何数量可观的稳定发现地点，最理想生境或是平原大水泡。目前仅怀柔水库、北京植物园、密云水库、沙河水库等极少数地点有零星或一次记录。","seasonality_notes":"暂无明确记载（仅记录偶见）。","cover_image_url":"/insects/images/sympetrum-uniforme-1.jpg","is_active":true},{"slug":"sympetrum-pedemontanum","common_name":"褐带赤蜻","scientific_name":"Sympetrum pedemontanum","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 36–42 mm。非常美丽的种类。无论雌雄翅近端部均具有一条褐色的宽大条纹，腹部第 8、9 节背面中央均具有黑斑。雄性体红、翅痣红；雌性体黄褐、翅痣白。","habitat_notes":"在北京数量不多。目前在北京植物园、喇叭沟门、野鸭湖有记录。","seasonality_notes":"7–10 月可见成虫，本种赤蜻出现较晚，一般在 8 月数量才多起来。","cover_image_url":"/insects/images/sympetrum-pedemontanum-1.jpg","is_active":true},{"slug":"sympetrum-danae","common_name":"黑赤蜻","scientific_name":"Sympetrum danae","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 29–34 mm。北京最小的蜻之一。2018 年新记录物种。雄性以黑色为主（随成熟趋于全部变黑）；雌性以黄色为主具粗大黑纹。无论雌雄合胸、腹基部均生有白色直立长毛。","habitat_notes":"北京固有少见种或已稳定生存。目前仅西六环附近的永定河流域有稳定种群记录，在其他地点都为零星偶见。","seasonality_notes":"目前成虫发现于 8–9 月，实际生存期可能更长。","cover_image_url":"/insects/images/sympetrum-danae-1.jpg","is_active":true},{"slug":"tramea-virginia","common_name":"华斜痣蜻","scientific_name":"Tramea virginia","aliases":[],"taxon_group":"蜻蜓目 蜻科","identification_notes":"体长 53–56 mm。无论雌雄后翅基部具大面积血红色斑纹，腹部最后 3 节（第 8–10 节）以黑色为主（远观腹末全黑）。多为迁徙中途经北京，高空飞行。","habitat_notes":"在北京未发现繁殖地。大群的黄蜻中寻找本种是公认有效的方式。北京植物园里曾有多次目击事件。","seasonality_notes":"目击记录均在 9 月（中途经京的个体）。","cover_image_url":"/insects/images/tramea-virginia-1.jpg","is_active":true},{"slug":"matrona-basilaris","common_name":"透顶单脉色蟌","scientific_name":"Matrona basilaris","aliases":["黑老婆儿","黑鍋底"],"taxon_group":"蜻蜓目 色蟌科","identification_notes":"体长 63–70 mm。体形较大但纤细。雄性躯体深绿色（具强金属光泽），翅黑色但正面大部分及反面基部区域翅脉为闪蓝色；雌性合胸黄绿色，翅黑褐色具白色伪翅痣。","habitat_notes":"在北京低山地带和近山地带的溪流、河流中常见，永定河流域、拒马河流域、雾灵山、碓臼峪、北京植物园等地均容易看到。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/matrona-basilaris-1.jpg","is_active":true},{"slug":"atrocalopteryx-atrata","common_name":"黑暗色蟌","scientific_name":"Atrocalopteryx atrata","aliases":["黑色蟌","黑老婆儿","黑锅底"],"taxon_group":"蜻蜓目 色蟌科","identification_notes":"体长 55–62 mm。体形较大但纤细。前长期被称为黑色蟌。无论雌雄翅皆黑色或黑褐色，无蓝色也无伪翅痣。雄性腹部深绿色（具强金属光泽）；雌性通体黑褐色。","habitat_notes":"在许多地方与透顶单脉色蟌混生。常见于北京低山地带和近山地带的溪流、河流中，永定河流域、青龙峡景区、虎峪、北京植物园等地均容易看到。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/atrocalopteryx-atrata-1.jpg","is_active":true},{"slug":"mnais-sp","common_name":"绿色蟌","scientific_name":"Mnais sp.","aliases":[],"taxon_group":"蜻蜓目 色蟌科","identification_notes":"体长 47–54 mm。中等体形。分类地位至今仍是悬而未决的谜题。雄性多型：橙翅型成熟个体全身体表密被白色粉霜，翅橙红色；透翅型翅烟褐色较透明，粉霜仅覆腹末。","habitat_notes":"在北京中、低海拔的山区溪流环境栖息，见于虎峪、碓臼峪、北京植物园、玉渡山等地的溪流流域。分布区域比另外两种色蟌窄，但数量并不少。","seasonality_notes":"5–7 月可见成虫。","cover_image_url":"/insects/images/mnais-sp-1.jpg","is_active":true},{"slug":"platycnemis-foliacea","common_name":"白扇蟌","scientific_name":"Platycnemis foliacea","aliases":[],"taxon_group":"蜻蜓目 扇蟌科","identification_notes":"体长 33–35 mm。常见小型。雄性中、后足胫节具白色叶片状扩展且前半部密被白色粉霜（飞翔时显雪白）；雌性足无扩展，合胸淡黄或黄白具黑纹，腹足为肉粉色至淡橙色。","habitat_notes":"见于北京中、低海拔山区溪流、河流、池塘。拒马河流域、永定河流域、神堂峪、虎峪、碓臼峪、小龙门、北京植物园等地数量都很多。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/platycnemis-foliacea-1.jpg","is_active":true},{"slug":"platycnemis-phyllopoda","common_name":"叶足扇蟌","scientific_name":"Platycnemis phyllopoda","aliases":[],"taxon_group":"蜻蜓目 扇蟌科","identification_notes":"体长 33–34 mm。常见小型。雄性中、后足胫节具白色叶片状扩展但体表不覆白色粉霜；雌性足无扩展，翅痣灰黑色，腹部前半部黑斑十分浓重。","habitat_notes":"见于北京低海拔山区溪流、河流、池塘，以及城区的一些湖泊。圆明园、颐和园、神堂峪、汉石桥、北京植物园、奥林匹克森林公园等地都有大量。","seasonality_notes":"5–9 月可见成虫。","cover_image_url":"/insects/images/platycnemis-phyllopoda-1.jpg","is_active":true},{"slug":"copera-tokyoensis","common_name":"黑狭扇蟌","scientific_name":"Copera tokyoensis","aliases":["东京狭扇蟌"],"taxon_group":"蜻蜓目 扇蟌科","identification_notes":"体长 45–48 mm。中型但纤细，较大的扇蟌。足上没有叶状扩展但足极长（后足胫节强烈弯曲）。雄性黑白二色，中后足胫节基半部与肛附器必为纯白色。","habitat_notes":"常见于北京平原水草丰茂的湖泊与池塘（如圆明园、北京植物园、南海子公园、野鸭湖等静水水域），深山未见。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/copera-tokyoensis-1.jpg","is_active":true},{"slug":"ischnura-asiatica","common_name":"东亚异痣蟌","scientific_name":"Ischnura asiatica","aliases":["琉璃鼠儿"],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 27–29 mm。常见小型。雄性复眼与合胸为绿色（绝不为蓝色），腹末仅第 9 节为全蓝色，第 10 节下半部分为蓝色；雌性合胸侧面无任何黑纹，未熟时橘红成熟淡绿。","habitat_notes":"见于北京平原水草丰茂的湖泊与池塘，相当常见。奥林匹克森林公园、圆明园、北京植物园、南海子公园、野鸭湖等地均多见。","seasonality_notes":"4–9 月可见成虫。","cover_image_url":"/insects/images/ischnura-asiatica-1.jpg","is_active":true},{"slug":"ischnura-elegans","common_name":"长叶异痣蟌","scientific_name":"Ischnura elegans","aliases":["琉璃鼠儿"],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 30–35 mm。最常见小型蟌之一，明显比东亚异痣蟌大。雄性蓝色，腹末仅第 8 节全蓝色，第 7、9、10 节下半部分蓝色；雌性多型，或与雄性同色，或第 8 节黑纹突变淡。","habitat_notes":"北京最常见蜻蜓之一。在平原地区水草丰茂的湖泊与池塘（任何公园甚至高校）有大量生存；在拒马河、永定河等山区大河流域也很多。","seasonality_notes":"4–10 月可见成虫。","cover_image_url":"/insects/images/ischnura-elegans-1.jpg","is_active":true},{"slug":"paracercion-calamorum","common_name":"蓝纹尾蟌","scientific_name":"Paracercion calamorum","aliases":["苇尾蟌","琉璃鼠儿"],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 26–32 mm。最常见小型蟌之一。雄性蓝灰色，越成熟身体前半部越密被粉霜而显‘脏兮兮’的苍白，腹第 8–10 节蓝色；雌性淡绿与黑相间，仅头顶靠眼处具蓝斑。","habitat_notes":"北京最常见的尾蟌。在城区的任何水域遍布且经常数量极大；山区流速缓慢的水域中也有分布。","seasonality_notes":"4–9 月可见成虫。","cover_image_url":"/insects/images/paracercion-calamorum-1.jpg","is_active":true},{"slug":"paracercion-v-nigrum","common_name":"捷尾蟌","scientific_name":"Paracercion v-nigrum","aliases":["琉璃鼠儿"],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 34–38 mm。最常见小型蟌之一。雄性蓝色，腹部第 4–7 节黑斑渐变式递增，第 8 节末端常具向前侵入连成‘V’形的黑斑（亦可无）；雌性多型（蓝色型、绿色型均黑纹纵贯到末端）。","habitat_notes":"平原地区第二常见、山区最常见的尾蟌。城区的许多公园可见，在拒马河、永定河、潮白河流域及松山、碓臼峪、虎峪、北京植物园等湖泊、池塘、水库、大河、溪流均极多。","seasonality_notes":"5–9 月可见成虫。","cover_image_url":"/insects/images/paracercion-v-nigrum-1.jpg","is_active":true},{"slug":"paracercion-hieroglyphicum","common_name":"隼尾蟌","scientific_name":"Paracercion hieroglyphicum","aliases":["琉璃鼠儿"],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 25–28 mm。体小。雄性蓝色或蓝绿色，第 3–6 节蓝色部分大小近似不递减，第 8、9 节纯蓝；头顶复眼间一对蓝斑微小但不成细长条；雌性中部几节背面发黄。","habitat_notes":"在北京广泛分布但不如蓝纹尾蟌与捷尾蟌多。城区与山区都有记录，如圆明园、碓臼峪、阳台山。","seasonality_notes":"5–9 月可见成虫。","cover_image_url":"/insects/images/paracercion-hieroglyphicum-1.jpg","is_active":true},{"slug":"paracercion-melanotum","common_name":"黑背尾蟌","scientific_name":"Paracercion melanotum","aliases":["琉璃鼠儿"],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 32–36 mm。本种头顶一对蓝斑通常非常窄长（水滴形绝不圆大）。雄性腹部第 3–7 节黑占绝对大部，第 8、9 节纯蓝色几乎永无黑斑；雌性合胸黑纹细弱甚至全无。","habitat_notes":"分布广泛但在北京数量不多。近年才确认在北京的分布，在圆明园、北京植物园、上庄水库等地有发现。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/paracercion-melanotum-1.jpg","is_active":true},{"slug":"paracercion-plagiosum","common_name":"七条尾蟌","scientific_name":"Paracercion plagiosum","aliases":[],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 39–49 mm。中型，明显大于北京的其他蟌科。特征极鲜明：合胸前方有多达 7 条完整的黑色细纹，头部花纹丰富令人眼花缭乱。头顶近复眼的一对斑纹大，近三角形。","habitat_notes":"数量不多，但在北京平原地带水草丰茂的湿地环境中广泛分布。圆明园、北京植物园、上庄水库、野鸭湖、房山青龙湖、北京大学、北京农学院等地都有发现。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/paracercion-plagiosum-1.jpg","is_active":true},{"slug":"enallagma-cyathigerum","common_name":"心斑绿蟌","scientific_name":"Enallagma cyathigerum","aliases":[],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 29–36 mm。比捷尾蟌更粗壮。雄性合胸蓝色面积更大、更纯粹，腹第 8 节背面无黑斑；雌性腹部第 3–7 节背面黑纹前端都收狭变尖揳入彩色区，腹第 8 节腹面端部具一刺状物。","habitat_notes":"在官厅水库和昌平老峪沟有种群，在其他一些地点也曾零星发现过（如碓臼峪、松山）。曾被发现在百花山顶峰（北京记录海拔最高的蜻蜓），其繁殖地尚不明确。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/enallagma-cyathigerum-1.jpg","is_active":true},{"slug":"ceriagrion-nipponicum","common_name":"赤黄蟌","scientific_name":"Ceriagrion nipponicum","aliases":["日本黄蟌","日本橘黄蟌"],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 29–33 mm。除翅透明、足基部淡黄白色外，几乎全身纯色：雄性为橘红色；雌性为黄褐色至橘黄色。2006 年突然被发现并呈爆发式广布。","habitat_notes":"平原地区水草丰茂的湖泊、池塘遍布（如北京植物园、圆明园、上庄水库、沙河水库等），在山区也有分布（如怀沙河流域、永定河流域）。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/ceriagrion-nipponicum-1.jpg","is_active":true},{"slug":"ceriagrion-auranticum-ryukyuanum","common_name":"翠胸黄蟌","scientific_name":"Ceriagrion auranticum ryukyuanum","aliases":["琉球黄蟌"],"taxon_group":"蜻蜓目 蟌科","identification_notes":"体长 33–41 mm。2016 年新记录物种。比赤黄蟌体形更长。复眼翠绿色，合胸透出黄绿色，六足基部黄色明显。雌性腹部第 8–10 节背面具有黑斑。","habitat_notes":"目前仅在北京发现于朝阳公园内，有小种群。随着气候变暖，本种或日渐北扩。","seasonality_notes":"发现于 8 月（朝阳公园记录）。","cover_image_url":"/insects/images/ceriagrion-auranticum-ryukyuanum-1.jpg","is_active":true},{"slug":"lestes-sponsa","common_name":"桨尾丝蟌","scientific_name":"Lestes sponsa","aliases":["绿尾丝蟌"],"taxon_group":"蜻蜓目 丝蟌科","identification_notes":"体长 36–41 mm。中型。停落时四翅错落地半平放如蜻（在蟌中独一无二）。雄性暗金属绿色，成熟个体合胸下半部、翅基和腹末密被白霜；雌性为淡黄绿与金属色相间。","habitat_notes":"北京较少见的蜻蜓种类。多见于北京北部，如延庆区的松山、妫水河流域、世园会展区和密云的白河上游等地。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/lestes-sponsa-1.jpg","is_active":true},{"slug":"sympecma-paedisca","common_name":"三叶黄丝蟌","scientific_name":"Sympecma paedisca","aliases":[],"taxon_group":"蜻蜓目 丝蟌科","identification_notes":"体长 31–34 mm。体形小且看似最为柔弱。除翅透明外，全身淡黄褐色，头、胸、腹背面具一些深色斑纹。雌雄高度相似。为北京唯一能以成虫越冬的蜻蜓。","habitat_notes":"多见于北京北部，在延庆区的松山、后河、古崖居、世园会展区等地均有发现。冬季停止活动不飞行、不易发现。","seasonality_notes":"因成虫越冬可能全年可见，当年羽化成虫 7 月始见存活至次年 5 月，每年 6 月也许为唯一不可见月份。","cover_image_url":"/insects/images/sympecma-paedisca-1.jpg","is_active":true},{"slug":"acrida-cinerea","common_name":"中华剑角蝗","scientific_name":"Acrida cinerea","aliases":["呱嗒扁儿","扁担","尖头蚂蚱"],"taxon_group":"直翅目 蝗科","identification_notes":"体长 36–48 mm(♂)；51–85 mm(♀)。头尖长并上翘。体色多变（绿、灰褐等），翅下腹部背面为紫红色。触角宽扁、端尖。后足极细长。雌体极大，雄虫远小。","habitat_notes":"北京最常见的蚂蚱之一。遍布北京，在野草野蛮生长的地带（野地、荒地）最为多见。雄性有较强飞行能力，飞行时噼啪作响。","seasonality_notes":"8–10 月可见成虫。","cover_image_url":"/insects/images/acrida-cinerea-1.jpg","is_active":true},{"slug":"atractomorpha-sinensis","common_name":"短额负蝗","scientific_name":"Atractomorpha sinensis","aliases":["扁担钩儿","小扁担钩儿","尖头蚂蚱"],"taxon_group":"直翅目 锥头蝗科/蝗科","identification_notes":"体长 19–23 mm(♂)；28–35 mm(♀)。体小型，头尖、短胖。体色多变（最常为绿色），体表有密集小颗粒。后翅基半部为红色。头超出复眼前的部分极短。","habitat_notes":"北京最常见的蚂蚱之一。几乎出现在任何野地杂草丛中，田间地头、农村房前院后十分常见。","seasonality_notes":"6–10 月可见成虫。","cover_image_url":"/insects/images/atractomorpha-sinensis-1.jpg","is_active":true},{"slug":"atractomorpha-lata","common_name":"长额负蝗","scientific_name":"Atractomorpha lata","aliases":["扁担钩儿","小扁担钩儿","尖头蚂蚱"],"taxon_group":"直翅目 锥头蝗科/蝗科","identification_notes":"体长 19–22 mm(♂)；28–34 mm(♀)。体小型，头尖短胖。与短额负蝗极似，但本种后翅接近透明无大面积红色；头超出复眼前方的部分明显更长（1.5–1.8 倍）。","habitat_notes":"北京常见物种。分布广泛，在野草野蛮生长的地带最易见。","seasonality_notes":"6–10 月可见成虫。","cover_image_url":"/insects/images/atractomorpha-lata-1.jpg","is_active":true},{"slug":"chondracris-rosea","common_name":"棉蝗","scientific_name":"Chondracris rosea","aliases":["蹬倒山"],"taxon_group":"直翅目 斑腿蝗科/蝗科","identification_notes":"体长 43–59 mm(♂)；65–85 mm(♀)。非常壮硕，以雌性而言是北京最大的蝗虫之一。体鲜绿色带黄，各足胫节紫红色具有 2 排强大的白色尖长刺。后足力量极大。","habitat_notes":"北京秋季常见物种。分布广泛，在植被比较稀疏的山区最常见，平原没有。若捕捉不得其法，会被其后足刺蹬踹得皮开肉绽。","seasonality_notes":"8–10 月可见成虫。","cover_image_url":"/insects/images/chondracris-rosea-1.jpg","is_active":true},{"slug":"oxya-chinensis","common_name":"中华稻蝗","scientific_name":"Oxya chinensis","aliases":[],"taxon_group":"直翅目 斑腿蝗科/蝗科","identification_notes":"体长 22–29 mm(♂)；27–41 mm(♀)。体中小型。身体下半部分为翠绿色，头上部、前胸背板及中后胸侧面具明黄与黑褐色条纹。触角红褐色。喜绕茎躲藏。","habitat_notes":"北京常见蝗虫。分布广泛，但在玉米、高粱等农田中最常见，在缺乏管理的作物上有时数量非常密集。","seasonality_notes":"7–10 月可见成虫。","cover_image_url":"/insects/images/oxya-chinensis-1.jpg","is_active":true},{"slug":"ognevia-longipennis","common_name":"长翅幽蝗","scientific_name":"Ognevia longipennis","aliases":[],"taxon_group":"直翅目 斑腿蝗科/蝗科","identification_notes":"体长 21–24 mm(♂)；27–31 mm(♀)。体中小型，体翠绿色。与中华稻蝗有些像但体形更瘦长，头顶不强烈向前倾斜，头与前胸上只有黑纹无黄纹。曾称长翅燕蝗。","habitat_notes":"北京常见蝗虫，但仅见于山区。在中等海拔高度的山谷中较容易见到。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/ognevia-longipennis-1.jpg","is_active":true},{"slug":"xenocatantops-brachycerus","common_name":"短角异斑腿蝗","scientific_name":"Xenocatantops brachycerus","aliases":["土蚂蚱"],"taxon_group":"直翅目 斑腿蝗科/蝗科","identification_notes":"体长 15–22 mm(♂)；24–29 mm(♀)。体中小型，土黄色。自复眼后到后胸侧面具连贯浅色斜纹，后足腿节黑浅相间、胫节淡红色。可以成虫越冬。","habitat_notes":"见于中、低海拔山区，在山区到处都有分布。不像多数蝗虫喜趴在地表，本种常在植物上抱茎。","seasonality_notes":"因其可以成虫越冬，故而可能全年可见，属于全年最早见到的蝗虫。","cover_image_url":"/insects/images/xenocatantops-brachycerus-1.jpg","is_active":true},{"slug":"gastrimargus-marmoratus","common_name":"云斑车蝗","scientific_name":"Gastrimargus marmoratus","aliases":["大土蚂蚱(褐色型)","方头绿蚂蚱(绿色型)"],"taxon_group":"直翅目 斑翅蝗科/蝗科","identification_notes":"体长 26–33 mm(♂)；36–51 mm(♀)。体中大型，体形健壮显大。最常见为褐色、翠绿色夹杂褐色条纹两型。前翅黑褐色杂浅褐竖条。前胸背板强烈隆拱隆起一弧状脊。","habitat_notes":"见于低海拔山区，数量不多。有很强的飞行能力，须小心接近才能仔细观察。","seasonality_notes":"8–9 月可见成虫。","cover_image_url":"/insects/images/gastrimargus-marmoratus-1.jpg","is_active":true},{"slug":"oedaleus-infernalis","common_name":"黄胫小车蝗","scientific_name":"Oedaleus infernalis","aliases":["土蚂蚱"],"taxon_group":"直翅目 斑翅蝗科/蝗科","identification_notes":"体长 23–27 mm(♂)；30–39 mm(♀)。中型。几乎全为土褐色具深浅不一麻纹。前胸背板具‘〉〈’形斑纹但对比度不高，且斑纹后端最外端比前端更靠外。雄后足胫节红、雌为黄。","habitat_notes":"北京最常见的蚂蚱（典型‘土蚂蚱’）之一。几乎遍布北京各处，以平原和低海拔山区的荒地最为常见。","seasonality_notes":"6–11 月可见成虫。","cover_image_url":"/insects/images/oedaleus-infernalis-1.jpg","is_active":true},{"slug":"oedaleus-asiaticus","common_name":"亚洲小车蝗","scientific_name":"Oedaleus asiaticus","aliases":["方头绿蚂蚱(绿色型)","土蚂蚱(褐色型)"],"taxon_group":"直翅目 斑翅蝗科/蝗科","identification_notes":"体长 21–25 mm(♂)；31–37 mm(♀)。中型。与黄胫小车蝗极似，但本种多为绿色与土褐色相间，前胸背板的‘〉〈’形斑纹对比度极高边缘清晰，两端最外端靠外程度近等。后足胫节红。","habitat_notes":"在本市平原和低海拔山区的荒地最为常见。","seasonality_notes":"7–11 月可见成虫。","cover_image_url":"/insects/images/oedaleus-asiaticus-1.jpg","is_active":true},{"slug":"sphingonotus-mongolicus","common_name":"蒙古束颈蝗","scientific_name":"Sphingonotus mongolicus","aliases":[],"taxon_group":"直翅目 斑翅蝗科/蝗科","identification_notes":"体长 18–23 mm(♂)；27–30 mm(♀)。中型偏小。前胸背板前半部分极度缢缩形成‘颈部’。体色多变（常见石头灰保护色）。前翅有 2 处大深色斑，后翅为电蓝色具黑色宽纹。","habitat_notes":"栖息于多石砾的荒地、河滩环境，在石头遍布的干枯河道、砂石路边多见。","seasonality_notes":"7–10 月可见成虫。","cover_image_url":"/insects/images/sphingonotus-mongolicus-1.jpg","is_active":true},{"slug":"trilophidia-annulata","common_name":"疣蝗","scientific_name":"Trilophidia annulata","aliases":["土蚂蚱"],"taxon_group":"直翅目 斑翅蝗科/蝗科","identification_notes":"体长 14.5–18 mm(♂)；22–24 mm(♀)。小型。前胸背板具强烈疣突（侧面观如齿状）。全身斑驳土褐色，后足腿节内侧有 2–3 个大黑斑，胫节黑白相间（如道口撂杆配色）。","habitat_notes":"极常见物种。在平原和山区都相当常见，有很好的保护色。通常在走路蹚草时其跳跃起来才被发现。目前在城区由于绿化改造比过去少见。","seasonality_notes":"8–11 月可见成虫。","cover_image_url":"/insects/images/trilophidia-annulata-1.jpg","is_active":true},{"slug":"haplotropis-brunneriana","common_name":"笨蝗","scientific_name":"Haplotropis brunneriana","aliases":["土墩儿"],"taxon_group":"直翅目 癞蝗科","identification_notes":"体长 28–40 mm(♂)；34–49 mm(♀)。中型偏大。体形相当粗壮、体表粗糙。成虫翅极度退化呈短小翅芽状。体色斑驳土褐色，前胸背板具最浓重的黑白斑并有白镶边。行动笨拙。","habitat_notes":"山区常见物种。在干燥土壤地带尤其常见，但植被茂密的高山草甸上也有分布。","seasonality_notes":"5–7 月可见成虫。","cover_image_url":"/insects/images/haplotropis-brunneriana-1.jpg","is_active":true},{"slug":"tetrix-japonica","common_name":"日本蚱","scientific_name":"Tetrix japonica","aliases":["土墩儿","小土墩儿"],"taxon_group":"直翅目 蚱科","identification_notes":"体长 8–9.5 mm(♂)；9–13 mm(♀)。体小型，短粗。前胸背板菱形盾牌状，向后延伸盖住大部分腹部。体色花样百出非常多变（最常为通体土褐色）。跳跃能力很强。","habitat_notes":"极常见物种。在平原和山区都相当常见，由于城市绿化改变目前在城区变得不如以前多见。","seasonality_notes":"5 月始见成虫。","cover_image_url":"/insects/images/tetrix-japonica-1.jpg","is_active":true},{"slug":"velarifictorus-micado","common_name":"中华斗蟋","scientific_name":"Velarifictorus micado","aliases":["迷卡斗蟋","蛐蛐","三尾儿(♀)","二尾儿(♂)","飞禽(长翅个体)"],"taxon_group":"直翅目 蟋蟀科","identification_notes":"体长 14–18 mm。头圆饱满，上颚强壮。体黑褐色，足淡黄色，头后方与前胸背板遍布麻纹。雄前翅不达腹末，雌前翅更短。雌产卵器长枪状。民间以雄虫互搏为乐。","habitat_notes":"北京最常见的蟋蟀。在平原和山区都相当常见。在杂草丛生特别是腐草堆积的野地具有相当数量。也多见于墙脚、砖缝、墙缝中。","seasonality_notes":"7–10 月可见成虫，夏末始闻虫鸣。","cover_image_url":"/insects/images/velarifictorus-micado-1.jpg","is_active":true},{"slug":"velarifictorus-aspersus","common_name":"长颚斗蟋","scientific_name":"Velarifictorus aspersus","aliases":["劳咪","老米嘴儿","劳咪子"],"taxon_group":"直翅目 蟋蟀科","identification_notes":"体长 13–19 mm。体黑褐色与中华斗蟋极似，但本种上颚延长（发达者向斜前呈铲状），尤以大型个体的‘鞋拔子脸’最为明显。雌产卵器长度不超过尾须。对战时互相铲击。","habitat_notes":"极常见。在平原和山区都相当常见，多于庭前院后、杂草丛生或腐草堆积野地、墙脚、砖缝中生存。过去常被捉蛐蛐者嫌弃。","seasonality_notes":"7–10 月可见成虫。","cover_image_url":"/insects/images/velarifictorus-aspersus-1.jpg","is_active":true},{"slug":"loxoblemmus-doenitzi","common_name":"多伊棺头蟋","scientific_name":"Loxoblemmus doenitzi","aliases":["棺材板儿"],"taxon_group":"直翅目 蟋蟀科","identification_notes":"体长 16–20 mm。体黑褐色，头后方与前胸背板遍布麻纹，头顶前端具一黄纹。雄性头部复眼间及下方强烈延伸，状如老式棺材截面；雌头平截。对战时互相顶撞。","habitat_notes":"极常见。在平原和山区都相当常见，遍布于庭前院后、腐草野地、墙脚砖缝中。过去常被捕捉者嫌弃。","seasonality_notes":"7–10 月可见成虫。","cover_image_url":"/insects/images/loxoblemmus-doenitzi-1.jpg","is_active":true},{"slug":"teleogryllus-emma","common_name":"黄脸油葫芦","scientific_name":"Teleogryllus emma","aliases":["油葫芦"],"taxon_group":"直翅目 蟋蟀科","identification_notes":"体长 20–27 mm。体较大、肥硕。体背黑褐色，足黄褐色。头顶黑亮，颜面为黄色，黑黄二色在头部的分界线恰似‘m’形发际线。鸣声婉转悠长，广被赏玩。","habitat_notes":"极常见。在平原和山区都相当常见，田间地头很多。在杂草丛生、腐草堆积野地、墙脚、砖缝中数量较多。","seasonality_notes":"8–10 月可见成虫。","cover_image_url":"/insects/images/teleogryllus-emma-1.jpg","is_active":true},{"slug":"meloimorpha-japonica","common_name":"日本钟蟋","scientific_name":"Meloimorpha japonica","aliases":["金钟儿","马铃儿"],"taxon_group":"直翅目 蛛蟋科","identification_notes":"体长 12–15 mm。体黑色，尾须、触角基部大半、足大部黄白色。头很小，体梨形。雄前翅极宽大，雌前翅革质如枣核形。雄虫鸣声极为动听（如金铃）。","habitat_notes":"在部分低海拔山区相当常见，平原地区稀见。多见于环境较好的村落边、香山、黑山寨、云蒙三峪等地。","seasonality_notes":"8–10 月可见成虫。","cover_image_url":"/insects/images/meloimorpha-japonica-1.jpg","is_active":true},{"slug":"gampsocleis-gratiosa","common_name":"优雅蝈螽","scientific_name":"Gampsocleis gratiosa","aliases":["蝈蝈","哑巴蝈蝈(无声雌虫)"],"taxon_group":"直翅目 螽斯科","identification_notes":"体长 31–55 mm。体粗大，大腹便便。后足为极长跳跃足。翅极短（雄前翅仅长之半，雌更短呈翅芽状）。体色常为翠绿色。雌产卵器砍刀状。鸣声清脆热闹。","habitat_notes":"山区常见物种。在盛夏到秋季在低海拔山区有相当数量（漫山遍野），在荆条灌丛中尤为多。以前平原农田常见现在城区已难见到。","seasonality_notes":"7–11 月可见成虫。","cover_image_url":"/insects/images/gampsocleis-gratiosa-1.jpg","is_active":true},{"slug":"gampsocleis-sedakovii-obscura","common_name":"暗褐蝈螽","scientific_name":"Gampsocleis sedakovii obscura","aliases":["吱啦子"],"taxon_group":"直翅目 螽斯科","identification_notes":"体长 35–40 mm。体粗大。无论雌雄前翅都接近或超过腹末，前翅侧面为绿色与褐色相间。雄性发音区较低平。雌产卵器比优雅蝈螽短。因叫声不悦耳俗称‘吱啦子’。","habitat_notes":"山区常见物种。于盛夏到秋季在山区广布，其分布海拔上限比优雅蝈螽高，可见于北京的高山草甸。常被奸商剪短翅膀冒充蝈蝈。","seasonality_notes":"7–10 月可见成虫。","cover_image_url":"/insects/images/gampsocleis-sedakovii-obscura-1.jpg","is_active":true},{"slug":"ducetia-japonica","common_name":"日本条螽","scientific_name":"Ducetia japonica","aliases":[],"taxon_group":"直翅目 螽斯科/露螽科","identification_notes":"体长 33–46 mm(含翅)。体较长、侧扁，体翠绿色似树叶。后翅超出前翅长度不及前翅长的 1/3；触角极长每隔一段有一个黑斑；前翅侧面翅脉细密。雌产卵器镰刀状。","habitat_notes":"山区常见物种（体似树叶）。在北京平原及山区都有分布，栖息于植被茂盛处。常举腹模拟树叶，但因六足伸展而不难识破。","seasonality_notes":"8–10 月可见成虫。","cover_image_url":"/insects/images/ducetia-japonica-1.jpg","is_active":true},{"slug":"elimaea-fallax","common_name":"秋掩耳螽","scientific_name":"Elimaea fallax","aliases":[],"taxon_group":"直翅目 螽斯科/露螽科","identification_notes":"体长 38–41 mm(含翅)。体较长、侧扁，翠绿到黄绿似叶。后翅超出前翅长不及前翅 1/5；触角每隔一段有一白斑；前翅侧面具红褐色或黄褐色粗大网格状翅脉。","habitat_notes":"山区常见物种（体似树叶）。栖息于植被茂盛处，常举腹模拟树叶。通过六足伸展特征可识破。","seasonality_notes":"8–10 月可见成虫。","cover_image_url":"/insects/images/elimaea-fallax-1.jpg","is_active":true},{"slug":"phaneroptera-falcata","common_name":"镰尾露螽","scientific_name":"Phaneroptera falcata","aliases":[],"taxon_group":"直翅目 螽斯科/露螽科","identification_notes":"体长 36–41 mm(含翅)。体较长、侧扁，翠绿到黄绿似叶。其后翅超出前翅甚多（达 1/3 甚至 1/2）；触角无斑纹；前翅侧面翅脉为绿色，无粗大红褐网格脉。","habitat_notes":"广布种（体似树叶）。栖息于植被茂盛处，拟态极为逼真。雾灵山、百花山、喇叭沟门等地都有分布。","seasonality_notes":"7–9 月可见成虫。","cover_image_url":"/insects/images/phaneroptera-falcata-1.jpg","is_active":true},{"slug":"kuwayamaea-brachyptera","common_name":"短翅桑螽","scientific_name":"Kuwayamaea brachyptera","aliases":[],"taxon_group":"直翅目 螽斯科/露螽科","identification_notes":"体长 27–32 mm(含翅)。体形短而扁，体翠绿色似叶。雄性翅背褐色，前胸背板背带黄。翅短，前翅刚超腹末，后翅更短明显不及前翅长。曾被错误鉴定为中华桑螽。","habitat_notes":"在北京多见于百花山，无已知平原分布。在百花山数量不少。","seasonality_notes":"8–9 月可见成虫。","cover_image_url":"/insects/images/kuwayamaea-brachyptera-1.jpg","is_active":true},{"slug":"megaconema-geniculata","common_name":"黑膝大蛩螽","scientific_name":"Megaconema geniculata","aliases":[],"taxon_group":"直翅目 螽斯科/蛩螽科","identification_notes":"体长 23–26 mm(含翅)。体翠绿色，体背褐色。后足有标志性的‘黑膝’（后足腿节端部和胫节基部为黑色）。前翅具白网格状脉。触角极长。曾称黑膝剑螽、黑膝畸螽。","habitat_notes":"山区常见小型螽斯。见于茂密的山林中，百花山、小龙门、喇叭沟门等地常见。","seasonality_notes":"8–10 月可见成虫。","cover_image_url":"/insects/images/megaconema-geniculata-1.jpg","is_active":true},{"slug":"ruspolia-dubius","common_name":"疑钩顶螽","scientific_name":"Ruspolia dubius","aliases":["疑钩额螽"],"taxon_group":"直翅目 螽斯科/草螽科","identification_notes":"体长 48–55 mm(含翅)。体大型，头尖锥状，颜面强烈倾斜。体色多为翠绿或黄褐。翅明显超腹末。雌产卵器剑状超翅端。鸣声极其聒噪、单调、刺耳，音量极大。","habitat_notes":"分布广泛。城区野地和低、中海拔山区都有分布，常隐藏在草丛中。","seasonality_notes":"8–9 月可见成虫，可循其电音般的长鸣音寻找。","cover_image_url":"/insects/images/ruspolia-dubius-1.jpg","is_active":true},{"slug":"hexacentrus-japonicus","common_name":"日本似织螽","scientific_name":"Hexacentrus japonicus","aliases":[],"taxon_group":"直翅目 螽斯科/草螽科","identification_notes":"体长 36–42 mm(含翅)。体中型。体色翠绿色，前胸背板与头顶为褐色，各足跗节第 2–4 节黑褐色。前翅长接近腹长一半，中部较宽翅形似芒果核形（独一无二）。","habitat_notes":"2011 年新记录属种。在北京数量稀少，目前仅发现于密云区云蒙三峪（牛盆峪）。","seasonality_notes":"8–9 月可见成虫。","cover_image_url":"/insects/images/hexacentrus-japonicus-1.jpg","is_active":true},{"slug":"diestrammena-unicolor","common_name":"素色芒灶螽","scientific_name":"Diestrammena unicolor","aliases":["灶马","灶火马子","灶了马子","罗锅儿"],"taxon_group":"直翅目 驼螽科","identification_notes":"体长 14–21.5 mm。无翅，体背强烈驼拱。体背黄褐色，触角极长，后足极发达。区别于其他灶螽的宏观特征为通体褐色，无任何斑驳的花斑。雌产卵器镰刀状。","habitat_notes":"由于常出没于老式平房院落而被熟知。在山区的老式平房院落内极常见，夜晚常出没于厨房、储物间和阴暗潮湿的角落。现代化城区目前已难见到。","seasonality_notes":"无固定发生期，只要气温不极低即可见其活动。","cover_image_url":"/insects/images/diestrammena-unicolor-1.jpg","is_active":true},{"slug":"tachycines-asynamorus","common_name":"庭疾灶螽","scientific_name":"Tachycines asynamorus","aliases":["灶马","灶火马子","灶了马子","罗锅儿"],"taxon_group":"直翅目 驼螽科","identification_notes":"体长 11–18 mm。无翅，体背强烈驼拱。体背黄褐色至灰褐色，其区别于素色芒灶螽的特征是通体具有斑驳的花斑。触角极长，后足极发达。","habitat_notes":"常出没于老式平房院落。在山区的老式平房院落内极常见，夜晚常出没于厨房、储物间和阴暗潮湿的角落。","seasonality_notes":"无固定发生期，只要气温不极低即可见其活动。","cover_image_url":"/insects/images/tachycines-asynamorus-1.jpg","is_active":true},{"slug":"polyphaga-plancyi","common_name":"冀地鳖","scientific_name":"Polyphaga plancyi","aliases":["宽缘地鳖","土鳖(♀)","飞土鳖(♂)"],"taxon_group":"蜚蠊目 鳖蠊科","identification_notes":"体长 19–22 mm(♂)；30–36 mm(♀)。雌性肥厚、无翅、黑色、体周缘具橙黄斑，体背光裸无毛。雄成虫长椭圆形、甚扁、具完整翅、体背黑色、前胸背板前缘具弧形透明纹。","habitat_notes":"北京最常见的原生蜚蠊。旧时凡阴暗潮湿处的地砖之下遍布。在平房院落日渐稀少的今天，在城区仍较常见。常在民宅胡同、墙根旮旯、地砖下隐藏。","seasonality_notes":"成虫可越冬，因此任何季节都有。雄成虫宜在夏季以灯诱法寻获。","cover_image_url":"/insects/images/polyphaga-plancyi-1.jpg","is_active":true},{"slug":"eupolyphaga-sinensis","common_name":"中华真地鳖","scientific_name":"Eupolyphaga sinensis","aliases":["土鳖(♀)","飞土鳖(♂)"],"taxon_group":"蜚蠊目 鳖蠊科","identification_notes":"体长 17–22 mm(♂)；22–32 mm(♀)。与冀地鳖相似，但雌性体被棕红色微毛（常沾满土粒），体色为深方棕色。雄成虫体背为深褐色与浅褐色混杂的细碎斑驳色。","habitat_notes":"北京常见的原生蜚蠊。随城市化进程在城区越来越难见到但在郊区还十分常见。多见于门头沟近山与低山地带，在平房、村落附近翻起砖石即易见到。","seasonality_notes":"成虫可越冬，任何季节都有，寒冷时藏匿。雄成虫宜在夏季以灯诱法寻获。","cover_image_url":"/insects/images/eupolyphaga-sinensis-1.jpg","is_active":true},{"slug":"hierodula-patellifera","common_name":"广斧螳","scientific_name":"Hierodula patellifera","aliases":[],"taxon_group":"螳螂目 螳科","identification_notes":"体长 42–61 mm(♂)；43–71 mm(♀)。体形在北方最显短粗，雌虫最具‘大腹便便’感。前翅具有一个明显的黄白色翅痣。体色多变（最常为翠绿色，亦有褐色、黄色等）。","habitat_notes":"北京常见螳螂之一且为城区最常见种。街边树上、小区绿化带里、或山林草丛中皆有分布。在棕色树干上有时可寻得棕色个体。","seasonality_notes":"成虫 8 月下旬始见，可存活至 11 月入冬前夕。","cover_image_url":"/insects/images/hierodula-patellifera-1.jpg","is_active":true},{"slug":"tenodera-sinensis","common_name":"中华大刀螳","scientific_name":"Tenodera sinensis","aliases":[],"taxon_group":"螳螂目 螳科","identification_notes":"体长 68–87 mm(♂)；74–110 mm以上(♀)。体形最长、最大，雌性极其强壮。体狭长，前胸背板前方约 1/3 明显膨大。前胸背板腹面于前足基部中间均有大黄斑。分绿型与褐型。","habitat_notes":"北京常见螳螂之一。遍布北京各地，无论城区或山林、草丛或树上，皆有分布。","seasonality_notes":"成虫 8 月下旬始见，可存活至 11 月入冬前夕。","cover_image_url":"/insects/images/tenodera-sinensis-1.jpg","is_active":true},{"slug":"tenodera-angustipennis","common_name":"狭翅大刀螳","scientific_name":"Tenodera angustipennis","aliases":[],"taxon_group":"螳螂目 螳科","identification_notes":"体长 60–82 mm。体狭长。与中华大刀螳雄性略似但羸弱得多。前胸背板几乎不膨扩（两侧几乎平行）。前胸背板腹面于前足基部中间均有橘黄色大斑，后翅较透明无黑色大斑。","habitat_notes":"不是北京的优势种，数量较少。广布但少见，常被误认为是中华大刀螳雄性，须查看后翅特征。","seasonality_notes":"成虫 8 月下旬始见，可存活至 11 月入冬前夕。","cover_image_url":"/insects/images/tenodera-angustipennis-1.jpg","is_active":true},{"slug":"mantis-religiosa","common_name":"薄翅螳","scientific_name":"Mantis religiosa","aliases":[],"taxon_group":"螳螂目 螳科","identification_notes":"体长 47–65 mm。体狭长，前胸背板前方约 1/3 膨扩呈菱形。翅较软、薄，后翅折叠部分透明。前足基节具有椭圆形大黑斑（或斑中心有白斑）。受威胁时腹与后翅摩擦会发沙沙声。","habitat_notes":"不是北京的优势种，数量较少。广布于草丛和低矮灌木中。","seasonality_notes":"成虫 8 月下旬始见，可存活至 11 月入冬前夕。","cover_image_url":"/insects/images/mantis-religiosa-1.jpg","is_active":true},{"slug":"statilia-maculata","common_name":"棕静螳","scientific_name":"Statilia maculata","aliases":["小刀螂","绿静螳"],"taxon_group":"螳螂目 螳科","intelligence_notes":"体长 39–58 mm。体形最为小巧轻盈。前胸背板前方约 1/3 膨扩，翅较软不很透明。体色多变（翠绿色或深棕色）。前足基节具黑长条斑，腿节具黑、白、粉色斑块。","habitat_notes":"北京常见螳螂之一。遍布北京各地，在城市绿地和野地中蹚草所蹿出的善飞的小型螳螂，大多即为本种。体色分绿色型与棕色型且后代色型具有可变性。","seasonality_notes":"成虫 8 月下旬始见，可存活至 11 月入冬前夕。","cover_image_url":"/insects/images/statilia-maculata-1.jpg","is_active":true},{"slug":"labidura-riparia","common_name":"蠼螋","scientific_name":"Labidura riparia","aliases":["火夹子"],"taxon_group":"革翅目 蠼螋科","identification_notes":"体长 17–34 mm。体狭长，体背黑褐色，头与尾夹红褐色，足与腹边淡黄。腹末具有尾须特化成的发达尾夹（雄性尾夹极发达常与腹露出的部分近等，雌性弱小）。前翅短小革质。","habitat_notes":"北京最常见的一种蠼螋。遍布北京各地，土壤较潮湿的平原野地里最多，有时进入平房室内。翻起野地或绿地中的砖头、稍大石块有可能发现本种。具夜行性。","seasonality_notes":"6–10 月成虫最易见。但由于成虫可越冬，实际上通过翻石头等方法全年都可找到。","cover_image_url":"/insects/images/labidura-riparia-1.jpg","is_active":true},{"slug":"forficula-davidi","common_name":"达球螋","scientific_name":"Forficula davidi","aliases":[],"taxon_group":"革翅目 球螋科","identification_notes":"体长 13–33 mm。体狭长，体背黑褐色，头、前翅、后翅露出部分为暗红色。雄性尾夹极长，最长者的长度与腹长近等；雌性尾夹较弱小。前翅短小革质。","habitat_notes":"山区常见种。在北京中海拔山区分布广泛，松山、小龙门、百花山、雾灵山都易见。常在夜间活动，可灯诱。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/forficula-davidi-1.jpg","is_active":true},{"slug":"forficula-vicaria","common_name":"迭球螋","scientific_name":"Forficula vicaria","aliases":[],"taxon_group":"革翅目 球螋科","identification_notes":"体长 13–16 mm。体狭长，头、腹大部为暗红褐色；革翅、六足、触角黄褐色。雄性尾夹基部内缘扁扩并呈明黄色、向内扩展，后面大部尖狭且黝黑，最大长约合腹露出部一半。","habitat_notes":"北京山区栖息的球螋之一。在北京较高海拔高度的山区分布较广，东灵山、小龙门、雾灵山都有记录。可灯诱。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/forficula-vicaria-1.jpg","is_active":true},{"slug":"forficula-tomis","common_name":"托球螋","scientific_name":"Forficula tomis","aliases":[],"taxon_group":"革翅目 球螋科","identification_notes":"体长 19–35 mm。体狭长，头、腹大部、尾夹基半部外侧为暗红色；前胸背板、革翅、尾夹端半部黑色。雄性尾夹基部宽厚呈赤红色，端部突向外歪呈黝黑牛角状，长者与腹露部近等。","habitat_notes":"北京山区栖息的球螋之一。在北京西部深山有发现，东灵山、小龙门、百花山可见。可灯诱。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/forficula-tomis-1.jpg","is_active":true},{"slug":"forficula-macrobasis","common_name":"大基铗球螋","scientific_name":"Forficula macrobasis","aliases":[],"taxon_group":"革翅目 球螋科","identification_notes":"体长 12–17 mm。体狭长，头、胸背大部、腹、尾夹都为黑褐色；革翅、六足黄色，但各足腿节端部和胫节基部明显变暗。雄尾夹短但基甚宽厚呈牛角歪曲，转折处具一向后显著圆形齿突。","habitat_notes":"北京山区栖息的球螋之一。与托球螋短夹个体类似但细节有别。在北京于门头沟、东灵山、小龙门、百花山都有发现。可灯诱。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/forficula-macrobasis-1.jpg","is_active":true},{"slug":"allodahlia-scabriuscula","common_name":"异螋","scientific_name":"Allodahlia scabriuscula","aliases":[],"taxon_group":"革翅目 球螋科","identification_notes":"体长 19–29 mm。体相对不很狭长、略宽扁，体壁极坚硬，全身黑褐色，触角第 11、12 节黄色。雄性尾夹形状极端夸张，自基部向外强弯后转直、端再急向内弯，长可明显超腹长。","habitat_notes":"北京山区栖息的球螋之一，为北京所有蠼螋当中尾夹最大者。在日本、南方、热带常见，北京于怀柔、密云山区最常见，云蒙山、百泉山等地数量较大。可灯诱。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/allodahlia-scabriuscula-1.jpg","is_active":true},{"slug":"cryptotympana-atrata","common_name":"黑蚱蝉","scientific_name":"Cryptotympana atrata","aliases":["唧鸟儿","唧鸟猴儿(幼虫)"],"taxon_group":"半翅目 蝉科","identification_notes":"体长 67–72 mm(含翅)。体大、纯黑色，体表有许多金黄色倒伏毛（具金色光泽）；翅基部具有大面积黑斑但基半部翅脉橘黄色。六足上有橘黄色斑纹。雄虫以不变的音调长鸣。","habitat_notes":"北京城区最常见的蝉。在本市平原地区和低、中海拔山地遍布，城区极为多见（如杨、柳树下、公园树林）。夜间进行羽化。","seasonality_notes":"5 月中旬始见，6–7 月为本种成虫高峰期，至 9 月已少见。","cover_image_url":"/insects/images/cryptotympana-atrata-1.jpg","is_active":true},{"slug":"meimuna-mongolica","common_name":"蒙古寒蝉","scientific_name":"Meimuna mongolica","aliases":["伏天儿"],"taxon_group":"半翅目 蝉科","identification_notes":"体长 35–49 mm(含翅)。体中型，较瘦长。体色斑驳（黑、白、褐、绿交杂远观显灰绿），腹部末端具白色粉霜；翅基无黑斑、端半部有黑小斑。发出类似‘伏天儿—’叫声。雌腹末尖长。","habitat_notes":"北京城区第二常见的蝉。在平原地区和低海拔山地遍布。在黑蚱蝉少的地方本种常更多，有时聚成大群在树上高歌。","seasonality_notes":"6 月始见，7–8 月为本种成虫高峰期（三伏天前后最盛），至 9 月已少见。","cover_image_url":"/insects/images/meimuna-mongolica-1.jpg","is_active":true},{"slug":"hyalessa-maculaticollis","common_name":"鸣鸣蝉","scientific_name":"Hyalessa maculaticollis","aliases":["乌英哇","斑透翅蝉"],"taxon_group":"半翅目 蝉科","identification_notes":"体长 56–63 mm(含翅)。体较大。体色斑驳（黑白墨绿草绿交杂），中胸背板后缘和腹前半部常密被白粉霜。翅基无黑斑、端半部有黑小斑。雄虫发音为重复多次‘乌英乌英’后接长降调‘哇—’。","habitat_notes":"山区从夏末到秋季最常见的蝉。在平原地区很少见，近山和山区极常见（高发于山区乔木林）。常被鸣鸣蝉寄蛾寄生。","seasonality_notes":"7 月始见，8–9 月为本种成虫高峰期，10 月仍有活动。","cover_image_url":"/insects/images/hyalessa-maculaticollis-1.jpg","is_active":true},{"slug":"platypleura-kaempferi","common_name":"蟪蛄","scientific_name":"Platypleura kaempferi","aliases":["小热儿热儿"],"taxon_group":"半翅目 蝉科","identification_notes":"体长 22–29 mm(含翅)。体宽短，在北京四大常见蝉中体形最小。体色极斑驳灰褐色，前翅全为花斑不透明，后翅除边缘外为黑声。具极强保护色。雄虫不断重复着急促单调叫声。","habitat_notes":"北京山区夏季最常见的蝉。常见于低、中海拔山区中，但因保护色极佳不易被发现。更常见于山桃、山杏等中型乔木的横枝与斜枝上。","seasonality_notes":"6–8 月为本种成虫高峰期（盛夏最常见）。","cover_image_url":"/insects/images/platypleura-kaempferi-1.jpg","is_active":true},{"slug":"lycorma-delicatula","common_name":"斑衣蜡蝉","scientific_name":"Lycorma delicatula","aliases":["花蹦蹦儿"],"taxon_group":"半翅目 蜡蝉科","identification_notes":"体长 17–22 mm。近三角形。前翅灰粉色，基部和中部有黑点、端部黑色；后翅基半部鲜红色杂以黑点、端部黑色、中部具一白或略发蓝大斑。幼虫 1–3 龄黑杂白点，4 龄变鲜红杂黑白斑。","habitat_notes":"极常见昆虫。于平原和山区都有，于城区更是极为常见。专性以臭椿树为主要寄主，只要有臭椿树几乎就能看到。有时也见于葡萄、香椿的枝干上。常被斑衣蜡蝉螯蜂寄生。","seasonality_notes":"6 月始见成虫，可存活至 11 月下旬。","cover_image_url":"/insects/images/lycorma-delicatula-1.jpg","is_active":true},{"slug":"zoraida-hubeiensis","common_name":"湖北长袖蜡蝉","scientific_name":"Zoraida hubeiensis","aliases":[],"taxon_group":"半翅目 袖蜡蝉科","identification_notes":"体长 14–17 mm(含翅)。体短小但前翅极长。前翅数倍于体长，于体背向两侧竖立呈直角夹角（状如回旋镖或隐形战机）。体淡色，前翅前缘黑声，翅脉乳白。长期被误定为甘蔗长袖蜡蝉。","habitat_notes":"本种于山区广布但数量不多。有时在桑树等阔叶树上密集发生。北京植物园、云蒙山、雾灵山、玉渡山等地有记录。","seasonality_notes":"7–8 月可见成虫。","cover_image_url":"/insects/images/zoraida-hubeiensis-1.jpg","is_active":true},{"slug":"euricania-clara","common_name":"透明疏广蜡蝉","scientific_name":"Euricania clara","aliases":[],"taxon_group":"半翅目 广翅蜡蝉科","identification_notes":"体长 10–12 mm(含翅)。体短小，翅极宽大近三角形。前翅大部区域透明，翅前缘则为黑褐色、其中具黄斑，翅脉以黑褐色为主。","habitat_notes":"北京最常见的广翅蜡蝉。于山区广布且常见，近山城区一些地点（如北京植物园、北京大学校园等）也有相当数量。","seasonality_notes":"7–9 月可见成虫。","cover_image_url":"/insects/images/euricania-clara-1.jpg","is_active":true},{"slug":"machaerotypus-sp","common_name":"红脊角蝉","scientific_name":"Machaerotypus sp.","aliases":[],"taxon_group":"半翅目 角蝉科","identification_notes":"体长 7–7.5 mm。体小型。前胸背板上肩角呈弧形阶状且红色、向后延长呈尖长脊状（均为红色）。复眼红色，身体其余部分均为黑色。北京常见种过去一直被错误鉴定为苹果红脊角蝉。","habitat_notes":"北京最漂亮的角蝉之一。于山区广布但数量不多，松山、百花山、小龙门等林区及低山地带有多见记录。","seasonality_notes":"5–11 月可见成虫。","cover_image_url":"/insects/images/machaerotypus-sp-1.jpg","is_active":true},{"slug":"erthesina-fullo","common_name":"麻皮蝽","scientific_name":"Erthesina fullo","aliases":["臭大姐","臭板子"],"taxon_group":"半翅目 蝽科","identification_notes":"体长 21–24.5 mm。较大的蝽，头十分尖长。全身黑色遍布淡黄色麻点，远观显灰褐色；从头顶到前胸中央被一条淡黄色细线纵贯。触角末节和足具有淡黄斑。臭液味足量大。","habitat_notes":"北京人最熟知的‘臭大姐’。到处遍布，在深秋时常成群聚集在居民房民宅的窗前、纱窗上、院角等温暖避风处寻找越冬地。","seasonality_notes":"越冬成虫 3 月可见出没，9–10 月为当年新羽化活动高峰，至 11 月基本潜藏。暖气室内个体冬季亦可爬出活动。","cover_image_url":"/insects/images/erthesina-fullo-1.jpg","is_active":true},{"slug":"halyomorpha-picus","common_name":"茶翅蝽","scientific_name":"Halyomorpha picus","aliases":["臭大姐","臭板子"],"taxon_group":"半翅目 蝽科","identification_notes":"体长 12–16 mm。体色全身茶褐色，具斑驳细密麻纹，前翅革质部可带紫红。与麻皮蝽混称但体形至多仅为其 2/3、头不尖长、无遍布黄色麻点。触角末节和次末节均有黄斑。","habitat_notes":"最常见的蝽之一。到处遍布，深秋时常与麻皮蝽一同聚集在窗前或院角墙缝里越冬。","seasonality_notes":"越冬成虫 5 月出没，8–9 月为当年新羽化高峰，11 月躲藏。暖气室内个体冬季亦可活动。","cover_image_url":"/insects/images/halyomorpha-picus-1.jpg","is_active":true},{"slug":"dolycoris-baccarum","common_name":"斑须蝽","scientific_name":"Dolycoris baccarum","aliases":["臭大姐","臭板子"],"taxon_group":"半翅目 蝽科","identification_notes":"体长 8–13.5 mm。体色多变（茶褐或紫红）。小盾片茶褐色，端部常为亮黄色。其区别于茶翅蝽、东亚果蝽的特征是触角各节均具有淡黄色斑纹，且体形明显瘦小。","habitat_notes":"最常见的蝽之一。从城区到山区遍布，相当常见，多见于各种作物与野地杂草上。因体形较小一般不引起注意。","seasonality_notes":"越冬成虫 4 月可见，夏季最常见，至 10 月基本不活动。","cover_image_url":"/insects/images/dolycoris-baccarum-1.jpg","is_active":true},{"slug":"carpocoris-seidenstueckeri","common_name":"东亚果蝽","scientific_name":"Carpocoris seidenstueckeri","aliases":["臭大姐","臭板子"],"taxon_group":"半翅目 蝽科","identification_notes":"体长 12–13 mm。体色多变（茶褐或前翅革质部紫红）。触角全黑色，任何一节上都不具有淡黄色斑纹。小盾片茶褐色且具有一对左右对称的弧形凹印（可与上述种相区别）。","habitat_notes":"常见椿象之一。山区与平原都有，见于各种作物与杂草上，因体形较小通常不被注意。","seasonality_notes":"越冬成虫 4 月可见出没，夏季最常见，至 10 月基本不可见。","cover_image_url":"/insects/images/carpocoris-seidenstueckeri-1.jpg","is_active":true},{"slug":"graphosoma-rubrolineatum","common_name":"赤条蝽","scientific_name":"Graphosoma rubrolineatum","aliases":[],"taxon_group":"半翅目 蝽科","identification_notes":"体长 9–11.5 mm。高颜值。小盾片极发达覆盖大部分腹部，仅两侧露出腹缘。体背橙黑相间，头、前胸、小盾片上为连贯的橙黑纵条，腹外缘也呈橙黑辐射状。触角与足全黑色。常被误认为盾蝽。","habitat_notes":"常见种类。强烈嗜好访问伞形科的花，在花期的胡萝卜地里极易遇到，在山区也可在独活、蛇床、防风等野花上寻找。","seasonality_notes":"5–9 月可见成虫。","cover_image_url":"/insects/images/graphosoma-rubrolineatum-1.jpg","is_active":true},{"slug":"palomena-viridissima","common_name":"宽碧蝽","scientific_name":"Palomena viridissima","aliases":[],"taxon_group":"半翅目 蝽科","identification_notes":"体长 12–13.5 mm。体较宽，全身鲜绿色。其区别于珀蝽的特征是：触角末端 2 节及各足跗节为橘色，前翅革质部完全为绿色，膜质部茶褐色。","habitat_notes":"相当常见的鲜绿色椿象。在农作物与杂草上均常见，但因保护色良好及体形原因不易被一般人注意。","seasonality_notes":"5–9 月可见成虫。","cover_image_url":"/insects/images/palomena-viridissima-1.jpg","is_active":true},{"slug":"plautia-fimbriata","common_name":"珀蝽","scientific_name":"Plautia fimbriata","aliases":[],"taxon_group":"半翅目 蝽科","identification_notes":"体长 8.5–11 mm。体较宽，鲜绿色。其区别于宽碧蝽的特征是：前翅革质部为琥珀色至茶褐色，触角第 3–5 节都为黄色且其中具有一个明显的黑色环纹（显黑黄相间）。","habitat_notes":"相当常见的鲜绿色椿象。在作物与杂草上均常见，但因体形小、保护色好而不易引起注意。","seasonality_notes":"5–9 月可见成虫。","cover_image_url":"/insects/images/plautia-fimbriata-1.jpg","is_active":true},{"slug":"zicrona-caerulea","common_name":"蓝蝽","scientific_name":"Zicrona caerulea","aliases":[],"taxon_group":"半翅目 蝽科","identification_notes":"体长 6–9 mm。体小型，全身为纯蓝色并具有强烈的金属光泽。虽然体形很小，但捕食许多蝶、蛾幼虫，对农业有益；但也吸食多种作物，属于捕食与吸食兼具的种类。","habitat_notes":"数量不多，主要见于农田、田间和野地杂草上。因为体色极其靓丽，在绿色草丛中容易引起注意。","seasonality_notes":"5–10 月可见成虫。","cover_image_url":"/insects/images/zicrona-caerulea-1.jpg","is_active":true},{"slug":"eurydema-dominulus","common_name":"菜蝽","scientific_name":"Eurydema dominulus","aliases":[],"taxon_group":"半翅目 蝽科","identification_notes":"体长 6–9.5 mm。体小型。具有脸谱般花哨的外观，全身具有红黑相间的大斑块，极具辨识度。同一种群中常有黄色、橙色、红色的个体变异发生。","habitat_notes":"常见椿象。数量极大。在十字花科作物（白菜、萝卜、油菜等农田或菜地）上有很大概率密集见到本种。","seasonality_notes":"4–10 月可见成虫。","cover_image_url":"/insects/images/eurydema-dominulus-1.jpg","is_active":true},{"slug":"eurydema-gebleri","common_name":"横纹菜蝽","scientific_name":"Eurydema gebleri","aliases":[],"taxon_group":"半翅目 蝽科","identification_notes":"体长 5.5–8.5mm。体小型。全身具有黑色、白色与彩色相间的大斑块（彩色在不同个体间可为橘或红）。与菜蝽极似且多混生，但本种翅与小盾片上黑色面积多得多不显艳丽。","habitat_notes":"极常见。数量极大甚至常达泛滥程度。在十字花科作物（白菜、萝卜、油菜等菜地里）有很大概率密集遇到。","seasonality_notes":"4–10 月可见成虫。","cover_image_url":"/insects/images/eurydema-gebleri-1.jpg","is_active":true},{"slug":"poecilocoris-lewisi","common_name":"金绿宽盾蝽","scientific_name":"Poecilocoris lewisi","aliases":[],"taxon_group":"半翅目 盾蝽科","identification_notes":"体长 15–17 mm。中型。体背绿色（具荧光感），前胸背板、小盾片上具数条粉色条带，色彩极其靓丽。小盾片很大覆盖全部腹部。幼虫近半球形、黑白相间（类似熊猫配色）。","habitat_notes":"可能为北京最漂亮的椿象。广泛见于低山地带，在侧柏林中特别常见，百望山、香山、八大处、妙峰山等浅山区即非常多见。","seasonality_notes":"4–11 月可见成虫。","cover_image_url":"/insects/images/poecilocoris-lewisi-1.jpg","is_active":true},{"slug":"cnizocoris-sinensis","common_name":"中国螳瘤蝽","scientific_name":"Cnizocoris sinensis","aliases":[],"taxon_group":"半翅目 猎蝽科","identification_notes":"体长 9–10.5 mm。体小型，前足特化为极具特色的螳螂状捕捉足。肩角尖刺状，腹中部向两扁扩。雌性腹部肥大、且六足、腹面与腹边呈芥末绿色；雄性狭小呈灰白色具黑斑。","habitat_notes":"人气种类。在陆生蝽类中唯一具典型捕捉足。广泛见于山区，攀附在各种杂草与低矮植物上伺机捕猎，浅山区（百望山、香山等）多见。","seasonality_notes":"7–10 月可见成虫。","cover_image_url":"/insects/images/cnizocoris-sinensis-1.jpg","is_active":true},{"slug":"aquarius-paludum","common_name":"圆臀大黾蝽","scientific_name":"Aquarius paludum","aliases":["卖油郎","卖油的","卖香油的","卖酱油的"],"taxon_group":"半翅目 黾蝽科","identification_notes":"体长 11.5–16.5 mm。体暗浅褐色，具不明显灰白缘。躯干狭长梭状。中后足极为细长。腹第 7 节两端具尖刺超腹末。成虫翅分长、短两型。能完美漂浮并快速滑行于水面。","habitat_notes":"最容易引起注意的黾蝽。遍布一切较为平静、开阔的水域，在城区及郊区公园的池塘、湖泊、河流静水处极为常见。","seasonality_notes":"6–11 月可见成虫。","cover_image_url":"/insects/images/aquarius-paludum-1.jpg","is_active":true},{"slug":"protohermes-xanthodes","common_name":"炎黄星齿蛉","scientific_name":"Protohermes xanthodes","aliases":[],"taxon_group":"广翅目 齿蛉科","identification_notes":"体长 46–64 mm(含翅)。体中型。躯体金角黄色，具一列黑斑；翅较宽大、呈屋脊状，前翅透明，翅面上具有一系列星点状黄白色斑纹（斑纹区内翅脉变淡黄，远观似星点）。","habitat_notes":"三大广翅目中最常见者。专性在水质较好的山地溪流和河流中生存，是环境原生态未受污染的优秀指示物种。白天藏匿，夜间强烈趋光。","seasonality_notes":"5–8 月可见成虫，夜间通过灯诱方式可轻易见到，或趋光飞入山区民居院落。","cover_image_url":"/insects/images/protohermes-xanthodes-1.jpg","is_active":true},{"slug":"acanthacorydalis-orientalis","common_name":"东方巨齿蛉","scientific_name":"Acanthacorydalis orientalis","aliases":[],"taxon_group":"广翅目 齿蛉科","identification_notes":"体长 93–137 mm(含翅)。体大型至巨大型，本市少有的巨大型昆虫。躯体橘黄与黑密集交杂，翅烟褐色具黑褐斑纹。雄性上颚极度发达、长度可超头胸之和（呈强大锹甲状大颚）。","habitat_notes":"著名观赏昆虫，三大广翅目中最大者。为要求严苛的‘环境指示性物种’，仅见于少数水质极好、未受任何污染的山地大河与溪流。白天潜藏。","seasonality_notes":"6–7 月可见成虫。夜间具有强烈趋光性，可通过灯诱方式轻易见到。","cover_image_url":"/insects/images/acanthacorydalis-orientalis-1.jpg","is_active":true},{"slug":"neochauliodes-rotundatus","common_name":"圆端斑鱼蛉","scientific_name":"Neochauliodes rotundatus","aliases":[],"taxon_group":"广翅目 齿蛉科","identification_notes":"体長 43–55 mm(含翅)。体中型偏小。头前胸较细。躯体橘黄色，具一列黑褐斑纹；翅宽大呈屋脊状，透明且具有大小不一的黑斑。触角略呈栉状（可与其他两种齿蛉区别）。","habitat_notes":"三大广翅目中最少见者。过去广布目前因水质污染和断流仅在少数环境极好、水质洁净的山地溪流和河流中有少量残存。环境指示物种。","seasonality_notes":"6–8 月可见成虫。具有趋光性，夜间可通过灯诱法寻获。","cover_image_url":"/insects/images/neochauliodes-rotundatus-1.jpg","is_active":true},{"slug":"eumantispa-harmandi","common_name":"汉优螳蛉","scientific_name":"Eumantispa harmandi","aliases":[],"taxon_group":"脉翅目 螳蛉科","identification_notes":"体长 20–33 mm(含翅)。外形神似迷你螳螂（趋同进化代表），前足特化为典型的捕捉足。体色鲜黄色极美丽，腹部具有黑褐色条纹，翅透明，具黄褐色翅痣。有趋光性。","habitat_notes":"脉翅目高人气类群。广布于本市中等海拔高度的山区阔叶林或混交林中。白天不易见，夜间可灯诱。","seasonality_notes":"7–9 月可见成虫，多见于东灵山、百花山、小龙门、松山、雾灵山等地的灯诱活动中。","cover_image_url":"/insects/images/eumantispa-harmandi-1.jpg","is_active":true},{"slug":"libelloides-sibiricus","common_name":"黄花蝶角蛉","scientific_name":"Libelloides sibiricus","aliases":[],"taxon_group":"脉翅目 蚁蛉科/蝶角蛉科","identification_notes":"体长 23–36 mm(含翅)。体中型。触角很长、端部膨大呈球棍状（似蝴蝶触角）。躯体黑色，具一些鲜黄色小斑；翅大面积鲜黄色杂以黑纹，极其艳丽。头前及下部具发达毛簇。","habitat_notes":"本市最美的脉翅目昆虫。常见于低山灌丛地带，飞行时常被不懂的人误认为是蜻蜓或某种蝴蝶。","seasonality_notes":"5–6 月可见成虫。","cover_image_url":"/insects/images/libelloides-sibiricus-1.jpg","is_active":true},{"slug":"nothochrysa-sinica","common_name":"中华幻草蛉","scientific_name":"Nothochrysa sinica","aliases":[],"taxon_group":"脉翅目 草蛉科","identification_notes":"体长 22–25 mm(含翅)。体中型，触角约为前翅长 2/3。不同于一般绿草蛉，本种身躯呈少见的鲜黄色，且具有一系列紫褐色斑纹。翅透明，横脉大部黑色、纵脉多白色。","habitat_notes":"在北京很罕见的高颜值暖色系草蛉。栖息于中、高海拔高度的山区森林中，在北京地区目前仅在雾灵山被发现过少量。","seasonality_notes":"6–7 月可见成虫。","cover_image_url":"/insects/images/nothochrysa-sinica-1.jpg","is_active":true},{"slug":"tenomerga-anguliscutis","common_name":"普通叉长扁甲","scientific_name":"Tenomerga anguliscutis","aliases":[],"taxon_group":"鞘翅目 长扁甲科","identification_notes":"体长 10–17 mm。体小型，狭长又极端扁平。触角扁阔，长约为体长 2/3。通体褐色至灰褐色，鞘翅上有深褐色纵条。分类地位极古老，属古老的原鞘亚目现生代表。","habitat_notes":"原论坛时代的‘北京神物’之一。虽然名字带普通但极稀少，除老一辈学者有学校墙壁聚集记录外，近年仅极少数爱好者各偶遇 1 只。已知的发现地有香山、百望山、中国农大校园（西区）。","seasonality_notes":"6–7 月可见成虫，目前没有已知有效的主动找寻法，纯属偶遇型。","cover_image_url":"/insects/images/tenomerga-anguliscutis-1.jpg","is_active":true},{"slug":"cicindela-gemmata","common_name":"芽斑虎甲","scientific_name":"Cicindela gemmata","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 16–19 mm。体色多变，本市所见几乎都为锈色。鞘翅具 4 组淡黄白花斑，且前端的一对点斑中部靠近中缝处具有一对明显的黑色小凹坑。飞行敏捷，具典型的‘追逃游戏’行为。","habitat_notes":"常见种。最常成群出现于沙地上，尤其是山区溪流与河流岸边的沙地与河滩上，常有极高的大概率寻见且数量很多。","seasonality_notes":"4–6 月可见成虫。","cover_image_url":"/insects/images/cicindela-gemmata-1.jpg","is_active":true},{"slug":"cicindela-sachalinensis","common_name":"萨哈林虎甲","scientific_name":"Cicindela sachalinensis","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 15–20 mm。体色多变，北京所产暗蓝色个体较多。与芽斑虎甲很像，但本种鞘翅上仅 3 组淡黄白斑（末端无弧纹镶边），中缝附近也没有黑色小凹坑。","habitat_notes":"相对于沙地本种更喜栖息在山区林下環境。常在林间小道、枯枝落叶层和森林中的大石头上单独出现，属零星遇见型，不密集。","seasonality_notes":"5–8 月可见成虫。","cover_image_url":"/insects/images/cicindela-sachalinensis-1.jpg","is_active":true},{"slug":"cicindela-coerulea-nitida","common_name":"多型虎甲","scientific_name":"Cicindela coerulea nitida","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 15.5–17.5 mm。特征明显极艳丽：头、前胸、足都为金属深绿色（或杂以红）；鞘翅为鲜艳的紫红色，具 3 组淡黄白色花斑。北京及周边常见者为红翅亚种 nitida。","habitat_notes":"少见。本种有强烈的生态特异性，仅专性喜好非水边的干燥旱地、沙地或沙质荒地，其他环境中极罕见。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/cicindela-coerulea-nitida-1.jpg","is_active":true},{"slug":"carabus-smaragdinus","common_name":"绿步甲","scientific_name":"Carabus smaragdinus","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 29–47 mm。大型。体色为干涉色。最常见个体为头与前胸暗紫红色、鞘翅翠绿色（亦有全绿或全红个体）。足触角黑。鞘翅上具一列大而不一的黑色光滑瘤突。嗜食蜗牛。","habitat_notes":"大步甲属（移动宝石）代表，北京 3 种最常见大步甲之一。分布极广，城区与山区都极多。山区可翻大石发现；城区常见于附近有野地的胡同、公园墙根或马路牙子边（夜间活动）。","seasonality_notes":"5–9 月可见成虫，夜晚极活跃，可在蜗牛多的地方捕获。","cover_image_url":"/insects/images/carabus-smaragdinus-1.jpg","is_active":true},{"slug":"carabus-brandti","common_name":"麻步甲","scientific_name":"Carabus brandti","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 24–34 mm。体全纯黑色。头极其宽大，前胸背板后部和鞘翅基部显著收狭使整体呈独特的葫芦形。鞘翅上密布一系列大小均一且密集的黑色光滑小瘤突。直接咬碎蜗牛壳取食。","habitat_notes":"北京 3 种最常见大步甲之一。分布极其广泛，城区与山区都很常见。生境与绿步甲类似，在夜间常见于山区石下、平原近野地的墙根、路边等处。","seasonality_notes":"4–10 月可见成虫，夜行性强。","cover_image_url":"/insects/images/carabus-brandti-1.jpg","is_active":true},{"slug":"carabus-manifestus","common_name":"罕丽步甲","scientific_name":"Carabus manifestus","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 19–23 mm。体形相对短圆。体色极其多变（红铜、金绿、深蓝、黑等，红铜最常见，蓝色千中无一）。鞘翅上间断的粗短瘤突与三行一组的细直脊交错整齐排列。常被爱好者吐槽不‘罕’。","habitat_notes":"北京 3 种最常见大步甲之一。在山区林区分布极广泛，松山、雾灵山、东灵山、喇叭沟门都非常多，常两三只集群在石下，白天也可见在地表游荡。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/carabus-manifestus-1.jpg","is_active":true},{"slug":"carabus-crassesculptus","common_name":"碎纹粗皱步甲","scientific_name":"Carabus crassesculptus","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 20–30 mm。体背具漂亮的闪蓝色或深蓝色金属光泽（‘蓝色控’福利）。足与触角全黑色。鞘翅上密布细碎的横褶皱，与整齐的断线状纵脊杂糅在一起呈特殊混合纹理。","habitat_notes":"北京 11 种大步甲中最靓丽者。虽然广布于山区但数量不多。在东灵山、小龙门、松山、百花山等阔叶林或混交林中有分布。多藏在林下、林缘的较大石块下。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/carabus-crassesculptus-1.jpg","is_active":true},{"slug":"carabus-vladimirskyi","common_name":"长叶步甲","scientific_name":"Carabus vladimirskyi","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 23–28 mm。体全黑色，反光强。其最特殊特征是前胸背板两侧具有强烈上翘的侧叶（‘长叶’）并朝后角方向显著延长。鞘翅上仅细微刻点列无显著瘤突。绝无近似种。","habitat_notes":"特色鲜明。在山区林区分布广泛，东灵山、小龙门、喇叭沟门、松山等地的林下、林缘、落叶层中常见，多翻起石头寻找。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/carabus-vladimirskyi-1.jpg","is_active":true},{"slug":"carabus-granulatus","common_name":"粒步甲","scientific_name":"Carabus granulatus","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 16–30 mm。体较扁平，鞘翅末端略尖不圆。体色一般黑色（偶带暗蓝光）。鞘翅纹理特殊：断点状长圆瘤突纵列与粗直的无断点隆脊交替相间排列，如明显的轮胎印，无近似种。","habitat_notes":"中等海拔高度的山区分布广泛，尤以雾灵山、云蒙山、水头等景区的林下、林缘地带较为易见。多藏在潮湿石块下或朽木附近。","seasonality_notes":"7–9 月可见成虫。","cover_image_url":"/insects/images/carabus-granulatus-1.jpg","is_active":true},{"slug":"carabus-canaliculatus","common_name":"沟步甲","scientific_name":"Carabus canaliculatus","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 21–35 mm。体黑色，较扁。特色极其鲜明：每片鞘翅上具有 3 条隆起的宽大强脊，配合中缝与翅缘的强化隆起，整个体背呈现极其雄壮的‘七道棱’结构，脊间似凹沟。无近似种。","habitat_notes":"形象独特。在山区中等海拔高度的针阔混交林或落叶阔叶林中栖息，雾灵山、百花山等地较为易见。多在林下或林缘翻石头寻找。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/carabus-canaliculatus-1.jpg","is_active":true},{"slug":"carabus-sculptipennis","common_name":"刻翅步甲","scientific_name":"Carabus sculptipennis","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 21–25 mm。体黑色，较短圆，体表金属光泽极弱。鞘翅上密布极其平缓低矮的瘤突，既无任何深沟也无明显强脊，‘没有特色就是最大特色’。触角第 5–11 节被棕色微毛。","habitat_notes":"在 11 种大步甲中形象最平淡无奇，最不受爱好者青睐。栖息于中、高海拔高度的山地灌丛或草甸边缘，小龙门、百花山、东灵山、海坨山等地易见，翻石可得。","seasonality_notes":"4–9 月可见成虫。","cover_image_url":"/insects/images/carabus-sculptipennis-1.jpg","is_active":true},{"slug":"carabus-hummeli","common_name":"肩步甲","scientific_name":"Carabus hummeli","aliases":[],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 20–30 mm。体型在本地种类中最为瘦狭。色彩多变（本市所产多为黑色或蓝紫色）。鞘翅表面平滑度低，由长短不一的细密隆线组成极其密集的条纹纵列。","habitat_notes":"北京 11 种大步甲中最晚被发现的一种（2008 年首次报道）。在较高海拔高度的林下、原始针叶林或高山草甸边缘栖息，百花山、海坨山等地有发现，可翻石寻找。","seasonality_notes":"6–9 月可见成虫。","cover_image_url":"/insects/images/carabus-hummeli-1.jpg","is_active":true},{"slug":"platyrhopalus-paussoides","common_name":"五斑棒角甲","scientific_name":"Platyrhopalus paussoides","aliases":["五星棒角甲"],"taxon_group":"鞘翅目 步甲科","identification_notes":"体长 6–8 mm。体小型，体暗红色，鞘翅上有 5 个深褐色大斑纹。触角构造极端异形（仅 2 节，第 2 节膨大为巨大浑厚的圆饼状）。各足腿节与胫节也都特化膨大为宽扁片状。专性嗜蚁。","habitat_notes":"传统的‘北京神物’之一，分布虽广但极稀少，多年来仅见零星记录。产地从海拔 100m 远郊河滩到百花山 1200m 都有，隐藏于特定蚂蚁巢穴中。只能像大海捞针般地翻石头查看蚁巢。","seasonality_notes":"已知仅在 6–7 月有极少发现记录。","cover_image_url":"/insects/images/platyrhopalus-paussoides-1.jpg","is_active":true},{"slug":"oxyporus-rufus","common_name":"朱红斧须隐翅虫","scientific_name":"Oxyporus rufus","aliases":[],"taxon_group":"鞘翅目 隐翅虫科","identification_notes":"体长 5–8 mm。头黑色，前胸背板橙红色，鞘翅黑色具暗红肩斑，腹大部橙红、腹末黑色，足触角橙黄。体形明显比一般隐翅虫宽粗，具强大的镰刀状上颚。本种发现在本地为新记录。","habitat_notes":"隐翅虫中高人气‘高颜值’类群。为专性菌食性捕食者，潜伏在大型伞菌（野生蘑菇）的菌褶内，捕食其中滋生的其他昆虫幼虫。常见于东灵山、百花山等中海拔山林林下。","seasonality_notes":"6–9 月间可在略微腐烂的大型野生伞菌下寻得。","cover_image_url":"/insects/images/oxyporus-rufus-1.jpg","is_active":true},{"slug":"oxyporus-japonicus","common_name":"日本斧须隐翅虫","scientific_name":"Oxyporus japonicus","aliases":[],"taxon_group":"鞘翅目 隐翅虫科","identification_notes":"体长 6–10 mm。头黑色，前胸背板黑色；其区别于朱红斧须隐翅虫的特征是：鞘翅背面除后角附近黑色外，大部全为黄褐色；腹部全黑色（无黄斑）；触角棕黑色。足黄褐色基部黑。","habitat_notes":"最常见的斧须隐翅虫。为专性菌食性捕食者，栖息于中海拔山林、林缘下略微腐烂的大型伞菌（蘑菇）菌褶内，东灵山、百花山、小龙门一带较易寻获。","seasonality_notes":"6–9 月伴随野生多汁伞菌的发生而多见。","cover_image_url":"/insects/images/oxyporus-japonicus-1.jpg","is_active":true},{"slug":"oxyporus-maculiventris","common_name":"斑腹斧须隐翅虫","scientific_name":"Oxyporus maculiventris","aliases":[],"taxon_group":"鞘翅目 隐翅虫科","identification_notes":"体长 8–11 mm。头与前胸黑色，鞘翅除后角附近黑色外大部全为黄褐色。其与日本斧须隐翅虫极似，但本种触角为淡黄色，且腹部黑色但第 3–5 节侧缘呈明显的淡黄色。足黄褐基部黑。","habitat_notes":"专性菌食性捕食者。栖息于中海拔高度山林的隐蔽林下，在略微腐烂的大型野生伞菌的菌褶内隐藏，东灵山、百花山、小龙门一带常有记录。","seasonality_notes":"6–9 月可在有大量野生多汁蘑菇的环境中寻得。","cover_image_url":"/insects/images/oxyporus-maculiventris-1.jpg","is_active":true},{"slug":"creophilus-maxillosus","common_name":"大隐翅虫","scientific_name":"Creophilus maxillosus","aliases":[],"taxon_group":"鞘翅目 隐翅虫科","identification_notes":"体长 16–23 mm。大型隐翅虫。头与前胸黑色、极光亮；其最大特征是鞘翅与腹部具有由灰白色或灰黄色微毛组成的极明显的斑驳状被毛。上颚镰刀状，极长且发达（雄虫头宽颚更长）。","habitat_notes":"世界性广布。具有较强的腐食和捕食习性，最常见在各种野外的腐败物（如死鱼、动物尸体、腐肉）周围出没，在落叶层中也常有分布。有趋光性。","seasonality_notes":"4–10 月可见成虫，夜晚可进行灯诱。","cover_image_url":"/insects/images/creophilus-maxillosus-1.jpg","is_active":true},{"slug":"hololepta-amurensis","common_name":"黑龙江扁阎甲","scientific_name":"Hololepta amurensis","aliases":[],"taxon_group":"鞘翅目 阎甲科","identification_notes":"体长 9–11 mm。本市最大的阎甲之一，形态极端奇特。全身黑色光亮，体长方形，极度宽扁（如同纸片）但极为坚硬。上颚极其发达显长（超头长）。触角膝状，可缩入特化槽内。","habitat_notes":"难得一见的奇特树皮下类群。极高度特化，专性藏匿和生存在山区朽木、半死树木或刚死树木的开裂树皮缝隙深处的狭小一线空间中。小龙门、雾灵山等地有极少量记录。","seasonality_notes":"由于生境稳定且可成虫越冬，事实上通过扒剥朽木树皮的方法，全年都可找到。","cover_image_url":"/insects/images/hololepta-amurensis-1.jpg","is_active":true},{"slug":"prosopocoilus-astacoides","common_name":"两点锯锹","scientific_name":"Prosopocoilus astacoides","aliases":["褐黄前锹甲"],"taxon_group":"鞘翅目 锹甲科","identification_notes":"体长 32–68 mm(♂)；26–31 mm(♀)。醒目的橙黄色甲虫。雄性个体差异极端巨大，大型个体上颚极发达（大颚长度达所有锹甲之最）；前胸背板两侧各具一显著黑色斑点。雌性中型偏小。","habitat_notes":"本市最常见也最具超高人气的明星锹甲，孩子们玩虫的终极目标。遍布各地低山地带（如百望山、妙峰山等），喜好吸食发酵树汁，常多只聚集在流汁的榆树、柳树、油松树干上。","seasonality_notes":"成虫于 6 月始见，7–8 月为出现的最巅峰与盛发期，至 9 月中旬随着气温降低而基本绝迹。灯诱与震树法极有效。","cover_image_url":"/insects/images/prosopocoilus-astacoides-1.jpg","is_active":true},{"slug":"prismognathus-davidis","common_name":"大卫鬼锹","scientific_name":"Prismognathus davidis","aliases":["齿棱颚锹甲"],"taxon_group":"鞘翅目 锹甲科","identification_notes":"体长 22–36.7 mm(♂)；18–24 mm(♀)。小至中型。通体黑褐色，足大部内侧为暗红色。雄虫大型个体的大颚超过前胸长度，且强烈向上翻折、扭曲，俯视呈‘老虎钳’状（绝不混淆）。","habitat_notes":"本市中、高海拔林区（阔叶林、混交林）中最常见的锹甲种类。广泛分布于中高山，通常在海拔 1000m 以上多壳斗科植物的林缘及树冠层大量栖息。强烈趋光。","seasonality_notes":"7–8 月为主要活跃期，夜间灯诱具有极高的捕获率与遇见率。","cover_image_url":"/insects/images/prismognathus-davidis-1.jpg","is_active":true},{"slug":"dorcus-davidis","common_name":"大卫大锹","scientific_name":"Dorcus davidis","aliases":[],"taxon_group":"鞘翅目 锹甲科","identification_notes":"体长 19–32 mm(♂)；20–26 mm(♀)。通体黑色，体表反光较弱略显晦暗。体宽阔、矮壮敦实。无论雄虫大小，其上颚仅与头长近等，且结构简单、仅具有一个内齿。头部前胸背板刻点粗大。","habitat_notes":"传统‘大锹’范畴，颇受虫友喜爱。在北京山区分布广泛，从低海拔浅山到高海拔林区皆有分布（分布海拔在 200–1700m 间）。有趋光性，亦见于树皮裂缝或流汁处。","seasonality_notes":"6–8 月活跃易见，海拔较低（如浅山区）的成虫在 9 月有时仍有记录。","cover_image_url":"/insects/images/dorcus-davidis-1.jpg","is_active":true},{"slug":"dorcus-rubrofemoratus","common_name":"红腿刀锹","scientific_name":"Dorcus rubrofemoratus","aliases":[],"taxon_group":"鞘翅目 锹甲科","identification_notes":"体长 20–43 mm(♂)；24–30 mm(♀)。通体黑色，前胸与鞘翅具强烈反光。最鲜明特征是各足腿节大部、后胸腹板均为醒目的暗红色。雄虫无论大小，上颚内侧均至少有一强壮的独立内齿。","habitat_notes":"为本市极易见到的第三种常见锹甲。通常在海拔 800m 以上、植被极好的针阔混交林或茂密山林中大范围分布。具有极强的趋光性，夜间常直接飞向灯火。","seasonality_notes":"主要发生期与活跃期集中在盛夏的 7–8 月，是灯诱的常客。","cover_image_url":"/insects/images/dorcus-rubrofemoratus-1.jpg","is_active":true},{"slug":"falcicornis-tenuecostatus","common_name":"皮氏小刀锹","scientific_name":"Falcicornis tenuecostatus","aliases":["望月大锹"],"taxon_group":"鞘翅目 锹甲科","identification_notes":"体长 20–34 mm(♂)；16.5–20 mm(♀)。通体黑色光亮。虽然颜色红红腿红腹板（中黑旁红）与红腿刀锹极似，但本种雄虫大型个体大颚极为细窄长，且上颚总是一排共基的密小齿，绝无独立大内齿。","habitat_notes":"原论坛时代的‘传说级神物’锹甲，极其罕见。仅在喇叭沟门、上方山、雾灵山等原始林貌保持极佳的个别针阔混交林区有极零星偶见记录。有趋光性。","seasonality_notes":"发生期极其短暂，仅见于 7–8 月间，极难被灯诱捕获。","cover_image_url":"/insects/images/falcicornis-tenuecostatus-1.jpg","is_active":true},{"slug":"dorcus-tenuihirsutus","common_name":"北方锈刀锹","scientific_name":"Dorcus tenuihirsutus","aliases":[],"taxon_group":"鞘翅目 锹甲科","identification_notes":"体长 17.5–20 mm(♂)；18–19 mm(♀)。体形短小。通体暗黄褐色或暗褐色，晦暗无光泽。最大特征是前胸背板与鞘翅上粗大刻点夹杂明显的锈色毛簇（常沾满泥土）。雌雄外观形似，雄上颚极短小。","habitat_notes":"2010 年发表新物种，代表该类群的分布北限。为本市锹甲中分布海拔下限最低的一种，昌平、平谷等低海拔（100m）果园或浅山杂木林即可见，在门头沟高山洪水口也有。算不上多见。","seasonality_notes":"发生和活跃期在 6–8 月，有一定趋光性，可灯诱。","cover_image_url":"/insects/images/dorcus-tenuihirsutus-1.jpg","is_active":true},{"slug":"serrognathus-consentaneus","common_name":"尖腹扁锹","scientific_name":"Serrognathus consentaneus","aliases":["细齿扁锹"],"taxon_group":"鞘翅目 锹甲科","identification_notes":"体长 29–56 mm(♂)；19–27 mm(♀)。体大型，宽扁而沉稳坚硬。通体纯黑色。其显著特征是触角末端显棕红色，雄虫前足胫节端部内侧密生棕红色刚毛、且前足胫节内缘强烈向内弯曲。","habitat_notes":"本市最难找到的‘神物级’珍稀锹甲之一，多年来仅偶见个别记录。目前北京的零星确凿记录仅见于门头沟区的妙峰山、双塘涧等少数近山混交林边缘。","seasonality_notes":"极为短暂的成虫活动期，所有发现年份的目击记录皆在 7 月份。","cover_image_url":"/insects/images/serrognathus-consentaneus-1.jpg","is_active":true},{"slug":"lucanus-dybowski","common_name":"斑股深山锹","scientific_name":"Lucanus dybowski","aliases":[],"taxon_group":"鞘翅目 锹甲科","identification_notes":"体长 39–63 mm(♂)；34–36 mm(♀)。雄虫大型个体头后侧向后大幅延伸呈高台状冠突，大颚具鹿角状强齿、端部呈叉状。通体深褐色密被金黄绒毛。最显著特征是各足腿节具有大块橙色斑。","habitat_notes":"虽在东北极其常见但在本市属于罕见至极的‘终极神物’。数量极端稀少，多年来仅偶见个别标本。已知在北京的记录产地仅怀柔喇叭沟门、密云云蒙山等极少数高山原始林中。","seasonality_notes":"仅在 7–8 月盛夏发生，具有夜行性与趋光性，需依靠极好运气的灯诱捕获。","cover_image_url":"/insects/images/lucanus-dybowski-1.jpg","is_active":true},{"slug":"hoplia-davidis","common_name":"戴单爪鳃金龟","scientific_name":"Hoplia davidis","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 12.6–14 mm。体圆胖。少有的色彩极其鲜艳的鳃金龟，其体背密被高反光的鳞片（鳞片颜色或为漂亮的水青色，或为鲜黄色）。其后足极大，仅存一爪且强发达成弯钩状。足无鳞显黑褐。","habitat_notes":"山区常见白天访花种类。强烈喜好在某些开花的丁香属植物等野花上集群出现，东灵山、小龙门、百花山等高海拔山林一带数量很多。","seasonality_notes":"成虫盛发于 6–8 月（初夏到盛夏）。","cover_image_url":"/insects/images/hoplia-davidis-1.jpg","is_active":true},{"slug":"hoplia-aureola","common_name":"斑单爪鳃金龟","scientific_name":"Hoplia aureola","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 6.5–7.5 mm。体明显比戴单爪鳃金龟小。体背同样密被水青色或鲜黄色鳞片，但本种独特特征是鞘翅上具有一系列由黑色鳞片形成的明显的黑色椭圆斑（斑纹不会磨损）。后足单爪呈弯钩状。","habitat_notes":"高海拔山区访花金龟。常在针阔混交林边缘、山顶草甸的丁香属、银露梅等植物的花朵上集群发生，东灵山、小龙门、百花山一带数量巨大。","seasonality_notes":"成虫盛发于 6–8 月间。","cover_image_url":"/insects/images/hoplia-aureola-1.jpg","is_active":true},{"slug":"phyllopertha-sp","common_name":"发丽金龟","scientific_name":"Phyllopertha sp.","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 8.5–11 mm。头与前胸背板暗绿色，具强金属光泽。鞘翅有两型：棕色与独特的藏蓝色。除足跗节外通体密被长直立毛（体背为黑毛，腹面毛密为黄白）。触角鳃叶黑色。长年被错误鉴定。","habitat_notes":"几乎为北京山区白天最容易见到的最常见的丽金龟。食性极其庞杂，在各种豆科野草及多种蔷薇科果树上都极常见并呈高度聚群，在中、高海拔山区更为普遍密集。","seasonality_notes":"6–7 月成虫数量极多（仲夏最盛）。","cover_image_url":"/insects/images/phyllopertha-sp-1.jpg","is_active":true},{"slug":"popillia-mutans","common_name":"棉花弧丽金龟","scientific_name":"Popillia mutans","aliases":["无斑弧丽金龟"],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 9–14 mm。为本地体型最大的一种弧丽金龟。体形极其圆胖呈扁卵圆形。全身通体为亮眼的深蓝色（或藏蓝色），具有极强烈的宝石般金属光泽。后足极为粗壮（而使体形显得更胖）。","habitat_notes":"常见且极美观。食性主要为访花，在城区及低山地带的草地上都能不时遇到，有时在人工种植的锦葵花、菜园豆角花上集群取食花瓣。","seasonality_notes":"6–8 月可见成虫。","cover_image_url":"/insects/images/popillia-mutans-1.jpg","is_active":true},{"slug":"protaetia-brevitarsis","common_name":"白星花金龟","scientific_name":"Protaetia brevitarsis","aliases":["铜壳郎"],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 18–22 mm。体极为扁平坚硬。通体呈暗古铜色（或铜绿色），具金属光泽。体背面（尤其是鞘翅上）具有一系列不规则的、可磨损的波纹状与星点状淡黄白色斑纹（左右并不完全对称）。","habitat_notes":"北京平原及城区里最常见的花金龟。主要聚集在带有发酵树液、流汁的榆树、柳树、栎树干上吮吸汁液，也极常见于果园的烂西瓜皮、各种腐烂水果堆上。极其坚硬。","seasonality_notes":"6–10 月可见成虫（夏秋季极多）。","cover_image_url":"/insects/images/protaetia-brevitarsis-1.jpg","is_active":true},{"slug":"oxycetonia-jucunda","common_name":"小青花金龟","scientific_name":"Oxycetonia jucunda","aliases":["斑青花金龟(红斑变异型)"],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 12–17 mm。体色变化极多（几乎能凑出‘赤橙黄绿青蓝紫’）：最常见深绿色，尚有红、紫、军绿、蓝黑等个体，少数个体鞘翅中部具一显眼大红斑。无论何色型，鞘翅皆具一列可磨损白斑。","habitat_notes":"北京山区最常见的花金龟，城区也有零星。主要在林缘或山坡的各种野花（如野菊、绣线菊等）上大范围栖息，积极进行访花取食花粉。","seasonality_notes":"4–10 月可见成虫，分布期极长（春夏秋季皆多）。","cover_image_url":"/insects/images/oxycetonia-jucunda-1.jpg","is_active":true},{"slug":"dicronocephalus-wallichii-bowringi","common_name":"黄粉鹿花金龟","scientific_name":"Dicronocephalus wallichii bowringi","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 19–25 mm(不含角)。雄虫唇基两侧朝前延伸成极其发达的暗红色鹿角状角突，前足极度延长且跗节呈黑黄交替蜂纹；体背覆有厚重黄色粉末，前胸具‘U’形光裸无粉黑色区。雌无角、足短黑色。","habitat_notes":"极其帅气的高人气观赏花金龟。在本市整体属于数量较少的少见种，但在平谷区部分低山栎林中相对稳定常见。成虫强烈嗜好吸食或访问栎属树木（麻栎、栓皮栎等）的花与树汁。","seasonality_notes":"成虫出现非常早且集中，仅在春末夏初的 5–6 月可见活动。","cover_image_url":"/insects/images/dicronocephalus-wallichii-bowringi-1.jpg","is_active":true},{"slug":"dicronocephalus-adamsi","common_name":"宽带鹿花金龟","scientific_name":"Dicronocephalus adamsi","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 21–27 mm(不含角)。体明显比黄粉鹿花金龟更粗大。雄虫体背被厚重灰白色粉末（非黄色），前胸背板具有两条纵向宽带状的平行光裸黑色无粉区，唇基前具红色鹿角状突。雌虫全身无粉纯黑色无光泽。","habitat_notes":"本市山区体型最大的一种鹿花金龟。在本市平谷区的一些栎林及杂木林中具有可观数量，其他区多为零星偶见。成虫嗜好访栎属植物的花。雄前足极长。","seasonality_notes":"发生期略晚于黄粉鹿花金龟，在 5–7 月间可见成虫活动。","cover_image_url":"/insects/images/dicronocephalus-adamsi-1.jpg","is_active":true},{"slug":"clinterocera-mandarina","common_name":"白斑跗花金龟","scientific_name":"Clinterocera mandarina","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 12.2–13.5 mm。体扁平。全身纯黑色、反光好，体背具粗大刻点。最独特特征是触角柄节特化如‘官帽两耳’可加护缩回的触角；且各足跗节极度短小紧凑且仅 4 节（在金龟中罕见）。鞘翅具一对白斑。","habitat_notes":"特殊的专性嗜蚁性（蚁客）花金龟。为了防御蚂蚁攻击进化出极端加护和紧凑结构。遍布中、低海拔山区，常见在路边、岩石上爬行，可在石块下的蚂蚁巢穴中直接寻获。","seasonality_notes":"成虫主要在春季到初夏的 4–7 月活跃。","cover_image_url":"/insects/images/clinterocera-mandarina-1.jpg","is_active":true},{"slug":"campsiura-mirabilis","common_name":"赭翅臀花金龟","scientific_name":"Campsiura mirabilis","aliases":["奇弯腹花金龟"],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 18–22 mm。高颜值。头前缘、前胸背板侧缘为对比鲜明的乳白色；鞘翅具有大面积明亮的赭黄色（或棕色）大斑块、几乎占据整个翅面，仅外周边缘为黑色。飞翔能力极强，常可做空中悬停。","habitat_notes":"少见的肉食性/捕食性花金龟。专性嗜食植物嫩芽上滋生的各种蚜虫，成虫常抱在草茎上成片地大口啃食蚜虫群。在山区野地、农田边缘的杂草上非常常见。","seasonality_notes":"5–9 月可见成虫，夏季高温晴天时在空中飞行的相遇率极高。飞行时会发出类似胡蜂的轰鸣声。","cover_image_url":"/insects/images/campsiura-mirabilis-1.jpg","is_active":true},{"slug":"lasiotrichius-succinctus","common_name":"短毛斑金龟","scientific_name":"Lasiotrichius succinctus","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 9–11 mm。体小。体黑色，鞘翅上具有非常独特的由黄白色纵斑与横带组合成的‘ ‡ ’形或‘王’字形褐色斑纹。体表面（特别是前胸与足）密被发达的黄色或褐色直立长毛（形似熊蜂）。","habitat_notes":"为本市山区白天最常见的一种斑金龟，也是山区野地数量最大的金龟子。具有极强的访花习性，在山坡、林缘的各种伞形科、蔷薇科野花（如绣线菊）上随处可见密集取食。","seasonality_notes":"5–8 月为成虫主要活跃期。","cover_image_url":"/insects/images/lasiotrichius-succinctus-1.jpg","is_active":true},{"slug":"gnorimus-subopacus","common_name":"褐翅格斑金龟","scientific_name":"Gnorimus subopacus","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 15–19 mm。体较宽胖（鞘翅与腹部显著宽于前胸）。为本地唯一具有干涉金属光泽的斑金龟。体色多变（红铜、暗绿、红绿杂糅等）。鞘翅上有一系列可磨损的细小白斑点，体腹面具密黄白毛。","habitat_notes":"不常见的山区珍稀斑金龟。在全市大部山区很罕见且难得一见，但在门头沟东灵山海拔 1000m 以上的混交林缘或山顶灌丛中，只要去对了时节可以见到可观数量。雾灵山、小龙门有零星记录。","seasonality_notes":"成虫集中活跃在盛夏的 6–7 月份，多采用白天的访花观察或夜间灯诱。","cover_image_url":"/insects/images/gnorimus-subopacus-1.jpg","is_active":true},{"slug":"osmoderma-barnabita","common_name":"凹背臭斑金龟","scientific_name":"Osmoderma barnabita","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 24–30 mm。体宽厚、硕大肥胖。本地唯一一种大型斑金龟。通体全黑色或黑褐色，体表反光极微弱。前胸背板正中央具纵向中凹（雄虫深、雌虫浅）。被惊扰时雄虫可释放出皮革厂般的怪异浓烈臭味。","habitat_notes":"原论坛时代的‘北京神物’级珍稀金龟。在全市数量稀少、很难见到。成虫完全隐蔽生活，白天几乎终生躲藏在古老栎树、榆树的树洞、树缝或树皮裂缝深处。具有夜行性并趋光。偶有取食树汁行为。","seasonality_notes":"成虫主要在 6–8 月盛夏发生。东灵山、小龙门、松山、海坨山等地偶见灯诱记录。","cover_image_url":"/insects/images/osmoderma-barnabita-1.jpg","is_active":true},{"slug":"eophileurus-chinensis","common_name":"华晓扁犀金龟","scientific_name":"Eophileurus chinensis","aliases":[],"taxon_group":"鞘翅目 金龟科","identification_notes":"体长 18–28.5 mm。体长方形且较厚。通体为纯黑色，光泽微弱。前胸背板中央具有一个明显的圆凹坑（雄大雌小）。雄虫具有一个微小且退化的头角（基部尖突状），雌虫角极小裸眼难察。大颚不外露。","habitat_notes":"为本市体型最大、也是最常见的一种犀金龟（独角仙亚科）。从低山、近山山区（如西山、香山、百望山等）到平原村落周围普遍不难见到。成虫与幼虫专性生存在各种落叶阔叶树的朽木树洞中。","seasonality_notes":"5–8 月可见成虫。春末夏初可剖开含有黑土的空洞树根周围碎屑寻找刚羽化成虫。夏夜具有强趋光性，常在夜间路灯下或路面上乱爬。","cover_image_url":"/insects/images/eophileurus-chinensis-1.jpg","is_active":true},{"slug":"pyrocoelia-pectoralis","common_name":"胸窗萤","scientific_name":"Pyrocoelia pectoralis","aliases":[],"taxon_group":"鞘翅目 萤科","identification_notes":"体长 15–19 mm(♂)；雌虫无翅形似幼虫大于雄性可达 25 mm。雄虫体黑色较软，最显著特征是前胸背板为半圆盾片状、且为亮丽的橘红色、背板前端具一对透明无色区（观察窗）。雄虫发光强，能活跃高飞。","habitat_notes":"本市最常见、也是体型最大的一种萤火虫。在生态环境极佳、林下湿度高、靠近山间水源溪流的茂密森林中几乎都有分布，在香山、潭柘寺、十三陵、碓臼峪等极多，夜间能集大群发出绿油油光迹。","seasonality_notes":"成虫在夏末秋初的 8–9 月为最主要的发生高峰期与活跃期。","cover_image_url":"/insects/images/pyrocoelia-pectoralis-1.jpg","is_active":true},{"slug":"helota-fulviventris","common_name":"黄腹蜡斑甲","scientific_name":"Helota fulviventris","aliases":[],"taxon_group":"鞘翅目 蜡斑甲科","identification_notes":"体长 8.7–12.1 mm。体型狭长而扁，古铜色极闪亮。前胸背板与鞘翅上具有多条平行的光滑纵向瘤突。最大特征是每片鞘翅上各具有 2 个明显的黄色透明点状斑（如滴了蜡一样）。腹部腹面呈鲜艳橘黄色。","habitat_notes":"形态特异精致的珍稀甲虫（本地唯一的蜡斑甲）。属于树汁系昆虫中的高人气类群。在山区偶见，专性在榆树、栎树等流出树汁、发酵并有白沫覆盖的部位多只聚集吸食树汁。","seasonality_notes":"5–8 月可见成虫。","cover_image_url":"/insects/images/helota-fulviventris-1.jpg","is_active":true},{"slug":"cucujus-haematodes","common_name":"血红扁甲","scientific_name":"Cucujus haematodes","aliases":[],"taxon_group":"鞘翅目 扁甲科","identification_notes":"体长 12–15 mm。体型极度扁平。头、前胸、鞘翅为明亮的血红色；复眼、触角与足全黑色。头很宽阔，后角向后延伸；上颚极发达明显外露。鞘翅呈扁舌状且具陡峭断崖式缘折（完美折成盖状）。","habitat_notes":"2005–2011 年间轰动一时的著名‘北京神物’。具有极强的猎奇人气。属于专性生活在各种刚死或死后不久的榆树、杨树朽木死树皮下的狭小裂缝缝隙深处的特化类群。目前已知喇叭沟门数量最多。","seasonality_notes":"由于生境稳定且其完全以成虫方式进行越冬，事实上一年四季全年都可剖树皮找到成虫。","cover_image_url":"/insects/images/cucujus-haematodes-1.jpg","is_active":true},{"slug":"coccinella-septempunctata","common_name":"七星瓢虫","scientific_name":"Coccinella septempunctata","aliases":["花大姐儿"],"taxon_group":"鞘翅目 瓢虫科","identification_notes":"体长 5.2–7.2 mm。体接近半球形，光亮。头与前胸黑色，具一对明显的标志性白斑；两片橘红色的鞘翅上总共精确定位分布着 7 个黑色圆斑，且翅基部中央还有一对合并的白斑。专食蚜虫。","habitat_notes":"最著名、最常见的益虫。无论城区、公园绿地、郊区农田还是深山中，任何生长有野草杂草的开阔或半开阔生境上都有高大概率撞见，在有大量蚜虫危害的杂草上尤其密集。","seasonality_notes":"4–11 月可见成虫活跃。其中 6–8 月因具有明显的迁飞行为而可能导致部分地点数量变化，在迁飞路径上的地带可见其惊人密集。","cover_image_url":"/insects/images/coccinella-septempunctata-1.jpg","is_active":true},{"slug":"harmonia-axyridis","common_name":"异色瓢虫","scientific_name":"Harmonia axyridis","aliases":[],"taxon_group":"鞘翅目 瓢虫科","identification_notes":"体长 5.4–8 mm。体呈半球形。世界著名的多型性（多色型）昆虫。鞘翅图案色型多达数百种，北京最常见三类：①黑具 2 或 4 个红斑；②橘红具多黑斑；③橘红无黑斑。前胸两侧白斑通常圆大。专食蚜虫。","habitat_notes":"本市数量最大、也最常见的瓢虫。广布于城区杨树林、各公园绿地、农田、荒地及山区任何植被上。深秋时具有极度壮观的集群寻找越冬地行为（常遮天蔽日飞向墙面），冬季常上千只密集抱团在石缝或室内冬眠。","seasonality_notes":"3–11 月可见成虫活动，其中 9–10 月为其秋季集群大迁飞的奇观发生期。","cover_image_url":"/insects/images/harmonia-axyridis-1.jpg","is_active":true},{"slug":"aiolocaria-hexaspilota","common_name":"六斑异瓢虫","scientific_name":"Aiolocaria hexaspilota","aliases":["奇变瓢虫"],"taxon_group":"鞘翅目 瓢虫科","identification_notes":"体长 9.5–10.5 mm。体呈半球形，光亮。最大特征是体长达 1 cm 左右，为本市最大的、也是唯一‘巨型’的瓢虫种类。前胸背板两侧具白斑；橘红色的鞘翅上具有类似于青铜器饕餮花纹形状的标志性红色黑框粗纹。","habitat_notes":"体型巨大的观赏瓢虫。在平原稀见，但在本市中等海拔高度、环境极佳的多汁密林山区（如松山、雾灵山、百花山林下）广泛分布，属零星遇见型。贸然抓在手里会由关节射出大量浓黑红色的刺激性防卫液。","seasonality_notes":"成虫活跃在 5–7 月份（初夏到仲夏）。","cover_image_url":"/insects/images/aiolocaria-hexaspilota-1.jpg","is_active":true},{"slug":"anoplophora-chinensis","common_name":"星天牛","scientific_name":"Anoplophora chinensis","aliases":["铡草牛儿"],"taxon_group":"鞘翅目 天牛科","identification_notes":"体长 21–37 mm。体厚实坚硬，前胸两侧具向外尖刺。全身黑色，足呈蓝灰色；其区别于光肩星天牛的特征是：其鞘翅肩部密布大量显著粗糙颗粒，且翅上的星点状白斑在多数个体上排列成整齐的一行行。","habitat_notes":"黑白相间俗称‘铡草牛儿’的代表种类。在本市比光肩星天牛数量少。属于害虫，主要成虫与幼虫多见于山区及郊区的各种杨树、柳树、柑橘类树木粗大树干上，有抱茎习性。","seasonality_notes":"5–8 月可见成虫。","cover_image_url":"/insects/images/anoplophora-chinensis-1.jpg","is_active":true},{"slug":"anoplophora-glabripennis","common_name":"光肩星天牛","scientific_name":"Anoplophora glabripennis","aliases":["铡草牛儿","黄斑星天牛(黄斑变异型)"],"taxon_group":"鞘翅目 天牛科","identification_notes":"体长 17–39 mm。与星天牛极相似。显著区别是：本种的鞘翅肩部‘光亮且光滑’、完全没有大量粗糙颗粒，且两片鞘翅上的白斑（本市偶见黄色）大小差异极大、且绝对不排列成整齐的横行（随机分布）。","habitat_notes":"过去在本市城区柳树上数量最庞大、危害极严重的著名害虫。曾经每棵柳树都满是其蛀孔，经绿化治理现城区有所减少但依然多见。主要栖息在各种柳树、杨树的高处、树冠层或树枝上。","seasonality_notes":"5–9 月可见成虫，盛夏最常见。雄性触角长度远超身体数倍。","cover_image_url":"/insects/images/anoplophora-glabripennis-1.jpg","is_active":true},{"slug":"aegosoma-sinica","common_name":"中华薄翅天牛","scientific_name":"Aegosoma sinica","aliases":["薄翅天牛","薄翅锯天牛"],"taxon_group":"鞘翅目 天牛科","identification_notes":"体长 30–52 mm。体呈长梭形、较扁。体背前端非常坚硬但鞘翅和腹部极薄、软且脆弱（故名薄翅）。全身为均一的深褐色或红褐色。触角第 3 节极为粗壮且长。曾归于 Megopis 属。","habitat_notes":"曾经是本地城区第二常见、严重危害柳树的害虫。经城市绿化树种更替和治理现城区难以见到。目前主要广泛分布在远郊及山区受保护的各种古老柳树上，与其光肩星天牛混生，但本种常见于柳树最下方的树干基部。","seasonality_notes":"成虫主要集中在 6–8 月盛夏夜间活动，具有极强的趋光性，可用灯诱法捕获。","cover_image_url":"/insects/images/aegosoma-sinica-1.jpg","is_active":true},{"slug":"aromia-bungii","common_name":"桃红颈天牛","scientific_name":"Aromia bungii","aliases":[],"taxon_group":"鞘翅目 天牛科","identification_notes":"体长 26–37 mm。体狭长。体色全身为乌黑色，唯独前胸背板（‘颈部’）正中央具有一大块极其醒目且反光好的橘红色（或桃红色）大斑块。前胸背板两侧具有尖锐刺突。后足胫节显著向内弧弯。有强烈异香。","habitat_notes":"著名的果树害虫。在近山和低山地带人工种植的各种桃树、杏树、李树林中有极高的遇见率，若发现桃树干基部有大量大量木屑状虫粪排出多为其幼虫危害。受到惊扰可由前胸喷射出可达两米远的防卫白汁。","seasonality_notes":"6–9 月可见成虫（夏秋季极多）。","cover_image_url":"/insects/images/aromia-bungii-1.jpg","is_active":true},{"slug":"rosalia-coelestis","common_name":"蓝丽天牛","scientific_name":"Rosalia coelestis","aliases":[],"taxon_group":"鞘翅目 天牛科","identification_notes":"体长 18–29 mm。体瘦长。特征极其明显高颜值：体全黑色但体表被覆有大面积由极其细密绒毛组成的、极其迷人的湖蓝色斑纹和宽带（蓝黑相间天鹅绒质感）。触角第 3–6 节具有黑色的密集毛簇（如节结状）。","habitat_notes":"本市最漂亮、也是最珍贵的明星天牛种类，属于世界著名的 Rosalia（玫瑰丽天牛）属观赏类群。在本市数量极稀少。在东灵山、小龙门一带有少量的稍高遇见率，主要在有大片原始阔叶林及死木的倒木上爬行。","seasonality_notes":"成虫发生于 6–9 月间（盛夏最常见）。","cover_image_url":"/insects/images/rosalia-coelestis-1.jpg","is_active":true},{"slug":"chrysochus-chinensis","common_name":"中华萝藦肖叶甲","scientific_name":"Chrysochus chinensis","aliases":[],"taxon_group":"鞘翅目 肖叶甲科","identification_notes":"体长 7.2–13.5 mm。体形圆滚滚卵圆形，身体结构紧凑而坚硬，头部半缩在前胸中。全身包括鞘翅和足均为亮闪闪的、光泽度极高的宝石蓝色、蓝绿色或蓝紫色。触角端半部黑色无光泽。","habitat_notes":"本市城区及野地最容易注意到的肖叶甲。食性高度专一，成虫和幼虫专性集群取食藤本植物萝藦、鹅绒藤等常见萝藦科野草的嫩叶。城中心公园及老小区的绿地只要生长有该种杂草常有极多数量。","seasonality_notes":"5–8 月可见成虫（夏初到夏末）。","cover_image_url":"/insects/images/chrysochus-chinensis-1.jpg","is_active":true},{"slug":"eocyphogenia-rugipennis","common_name":"齿砚甲","scientific_name":"Eocyphogenia rugipennis","aliases":[],"taxon_group":"鞘翅目 拟步甲科","identification_notes":"体长 17.5–23 mm。体色通体全纯黑色，几乎毫无反光光泽。体形极为方正、棱角明显分明。头前胸极端扁平，前胸两侧具有叶状侧缘折；鞘翅两侧具锐利分界脊，呈垂直下折。整体外观活像个长方形老式砚台。","habitat_notes":"本地拟步甲中相当独特的种类（部分胡同居民的童年记忆）。不同于一般野生甲虫，本种反而具有极强的向人居环境聚集习性，最常见于北京城区老式四合院建筑、老旧胡同平房的阴暗砖石墙根、墙缝处。","seasonality_notes":"6–10 月可见成虫活动（夏秋季）。","cover_image_url":"/insects/images/eocyphogenia-rugipennis-1.jpg","is_active":true},{"slug":"synchroa-melanotoides","common_name":"黑暗甲","scientific_name":"Synchroa melanotoides","aliases":[],"taxon_group":"鞘翅目 暗甲科","identification_notes":"体长 8.2–12 mm。体呈尖瘦的纺锤形梭形。通体为均一的黑褐色或接近黑色，有光泽；足和触角为暗红色。前胸背板与鞘翅末端具有一些不明显的黄褐色倒伏短微毛。小盾片极小。长相形似叩甲或长朽木甲，是个四不像。","habitat_notes":"全世界仅 3 属 9 种的珍稀小科代表（曾被错误叫作齿胫甲科）。幼虫和成虫属于专性朽木寄生类群。在北京山区偶有记录（如小龙门、雾灵山），可在林下阴暗处通过剖碎某些特定阔叶树朽木的手段来主动寻找。","seasonality_notes":"6–9 月间可见成虫活动。","cover_image_url":"/insects/images/synchroa-melanotoides-1.jpg","is_active":true},{"slug":"eucryptorrhynchus-brandti","common_name":"臭椿沟眶象","scientific_name":"Eucryptorrhynchus brandti","aliases":["白胡子老头儿","木猴儿","树猴儿"],"taxon_group":"鞘翅目 象甲科","identification_notes":"体长 9–11.5 mm。体体短而浑厚，体壁异常坚硬。长有典型的延长管状象鼻。体色布局似鸟粪，身躯两端（头前胸及腹末）密被白色鳞片、中间（鞘翅大部）黑色夹杂细碎白斑及少量锈红花纹。受惊具有长达几十分钟的绝技假死行为。","habitat_notes":"本地人最熟悉的‘树猴儿’。属于著名的树木害虫，食性极专一：只危害并取食臭椿树。在平原城区和山区都极其普遍常见，在缺乏干预的地方几乎每棵较大的老臭椿树干上都能随时拍到多只。","seasonality_notes":"4–9 月可见成虫活动（分布期极长）。与斑衣蜡蝉、沟眶象并称臭椿树三大金刚。","cover_image_url":"/insects/images/eucryptorrhynchus-brandti-1.jpg","is_active":true},{"slug":"eucryptorrhynchus-scrobiculatus","common_name":"沟眶象","scientific_name":"Eucryptorrhynchus scrobiculatus","aliases":["白胡子老头儿","木猴儿","树猴儿"],"taxon_group":"鞘翅目 象甲科","identification_notes":"体长 15–18.5 mm。长相及色彩布局与臭椿沟眶象极度相似、且常多只混生，但本种最核心区别特征是：其成虫体型显著粗大得多（约是其 1.5 倍大），且体表面覆盖了明显多得多的、对比鲜明的鲜艳锈红色或橙黄色鳞片花纹。","habitat_notes":"与臭椿沟眶象共享俗名的‘大树猴儿’。也是严重的臭椿树害虫，专性以臭椿为寄主。在平原城区及低山山区的各种大臭椿树干上常见，但其总体数量比臭椿沟眶象要少一些。","seasonality_notes":"5–9 月可见成虫活动。","cover_image_url":"/insects/images/eucryptorrhynchus-scrobiculatus-1.jpg","is_active":true},{"slug":"papilio-xuthus","common_name":"花椒凤蝶","scientific_name":"Papilio xuthus","aliases":["柑橘凤蝶"],"taxon_group":"鳞翅目 凤蝶科","identification_notes":"翅展 61–95 mm。本市最常见大型蝴蝶。翅面浅黄色、翅脉黑色。最核心识别特征是：其前翅正面基部的上半部分分布着多条清晰的黑黄相间的横向长条纹。后翅亚缘具深蓝斑，臀角有一橘红斑。尾突发达。幼虫鸟粪状或绿毛虫状。","habitat_notes":"广布种。在城区和山区都广泛遍布（山区更为密集）。寄主高度专一于各种芸香科植物，如野生的黄檗、或人类广泛人工种植的花椒树林。在农户房前屋后的花椒树上极容易找到其各龄期幼虫与蛹。","seasonality_notes":"4–9 月可见成虫飞舞，有强烈的访花和吸水习性。","cover_image_url":"/insects/images/papilio-xuthus-1.jpg","is_active":true},{"slug":"papilio-machaon","common_name":"金凤蝶","scientific_name":"Papilio machaon","aliases":[],"taxon_group":"鳞翅目 凤蝶科","identification_notes":"翅展 74–95 mm。与花椒凤蝶极其相似，但本种翅色明显‘更显金黄’。最核心识别要点是：其前翅正面的整个翅基部为一大片均匀混合的、黑黄鳞片组成的纯黑色或灰黑色暗色区，绝对没有黑黄间隔的长横条纹。末龄幼虫鲜黄绿布满红点黑斑。","habitat_notes":"大型高颜值凤蝶，但全市总体数量远少于花椒凤蝶。其寄主专一于伞形科植物（如溪流边的水芹、独活、防风等）。成虫在山区较为多见，亦高发于郊区人工种植的胡萝卜菜地、茴香菜园里。成虫强烈访花。","seasonality_notes":"4–10 月可见成虫活动。","cover_image_url":"/insects/images/papilio-machaon-1.jpg","is_active":true},{"slug":"papilio-maackii","common_name":"绿带翠凤蝶","scientific_name":"Papilio maackii","aliases":[],"taxon_group":"鳞翅目 凤蝶科","identification_notes":"翅展 75–123 mm。大型巨美。远观呈大黑蝴蝶，但近看全身密布漂亮的绿色或天蓝色金属荧光鳞片。最核心识别要点是：前、后翅的端半部拥有一条极明亮且连贯的荧光色带（随光角呈现绿蓝变化）。后翅臀角具一红弧斑。雄前翅具黑色绒毛性标。","habitat_notes":"明星凤蝶。主要分布在本市植被保存完好的各大深山峡谷中（如小龙门、雾灵山、喇叭沟门等），寄主为野生黄檗。成虫有极强烈的吸水习性，晴天中午在山区清澈溪流附近的潮湿沙滩、泥地上常群聚停落。","seasonality_notes":"4–8 月可见成虫，多见于初夏至盛夏。","cover_image_url":"/insects/images/papilio-maackii-1.jpg","is_active":true},{"slug":"sericinus-montelus","common_name":"丝带凤蝶","scientific_name":"Sericinus montelus","aliases":["马兜铃凤蝶"],"taxon_group":"鳞翅目 凤蝶科","identification_notes":"翅展 75–123 mm(夏型)。体纤弱翅柔软。雌雄异色极端明显：雄性大部为白色、具少量黑斑；雌性为暗淡黄色与黑色混杂的网状密斑（虎纹状）。无论雌雄，后翅背面均具一列显著的粉红色弧斑及蓝斑。夏型尾突极其尖长如丝带（超体长）。幼虫海参状。","habitat_notes":"古典‘梁祝化蝶’的热门传说原型。本市低、中海拔山区最常见的经典蝴蝶，低山浅山更常见。食性极专一，其幼虫专性寄生并唯一取食珍稀中草药马兜铃的叶片。成虫常在长有马兜铃的灌丛、沿溪谷缓慢无力地盘旋。","seasonality_notes":"4–8 月可见成虫。春季羽化者（春型）体型较小且尾突明显短小，夏型最具观赏性。","cover_image_url":"/insects/images/sericinus-montelus-1.jpg","is_active":true},{"slug":"parnassius-bremeri","common_name":"红珠绢蝶","scientific_name":"Parnassius bremeri","aliases":["布氏绢蝶"],"taxon_group":"鳞翅目 绢蝶科","identification_notes":"翅展 54–63 mm。体色似古典高雅的水墨丹青。翅薄如半透明白色绢布，翅脉及边缘为微晕染感的黑灰色。最核心特征是前、后翅正面点缀着数个零星分布的亮红色圆珠状斑点。雌雄差异明显：雌性翅色更黑，红珠斑明显硕大且多。","habitat_notes":"著名的古北区冰川期残存遗留‘高山明星’。性喜极度高寒，生境破碎化。在北京仅极为脆弱地残存分布于少数几个海拔极高、未受人类开发的高山草甸山顶上（如雾灵山、百花山、东灵山顶峰）。只在草甸上低空贴地飞行。","seasonality_notes":"成虫发生期极为短暂，仅见于 6–8 月盛夏高山草盛开时，建议仅拍照观赏，绝对不予以捕捉破坏。","cover_image_url":"/insects/images/parnassius-bremeri-1.jpg","is_active":true},{"slug":"parnassius-nomion","common_name":"小红珠绢蝶","scientific_name":"Parnassius nomion","aliases":[],"taxon_group":"鳞翅目 绢蝶科","identification_notes":"翅展 58–88 mm。体型明显比红珠绢蝶大而粗壮，具有类似水墨丹青黑白晕染的薄绢状翅。其与红珠绢蝶的最核心区别在于：无论雌雄，其前后翅正面的亮红色‘红珠斑’的数量明显要多得多、且红斑轮廓极为圆大、内有白心，翅缘具整齐黑白相间方格纹。","habitat_notes":"珍稀高山特有绢蝶。性喜高寒。在本市其分布海拔下限比红珠绢蝶略低一些，但已知仅见于海拔 1600m 以上的高山顶部草甸或高寒荒地环境（如东灵山、松山、海坨山顶峰、以及延庆闫家坪）。因种群孤立破碎极为濒危。","seasonality_notes":"成虫集中在 7–8 月盛夏发生。建议严加保护其脆弱栖息地。","cover_image_url":"/insects/images/parnassius-nomion-1.jpg","is_active":true},{"slug":"parnassius-citrinarius","common_name":"冰清绢蝶","scientific_name":"Parnassius citrinarius","aliases":[],"taxon_group":"鳞翅目 绢蝶科","identification_notes":"翅展 63–72 mm。体色素雅无任何红珠斑。两翅整体呈非常干净的乳白色半透明绢布状，翅上具有淡淡的半透明烟灰色暗斑，翅脉黑褐色。最核心识别特征是：其颈部、前胸前端、腹部中部下侧密被一圈极其鲜艳的、对比强烈的柠檬黄色长毛。雌色略深。","habitat_notes":"极为特殊的‘低海拔’绢蝶成员。与本地另外两种高山绢蝶不同，本种栖息的海拔仅在 800m 上下的温和山林林缘或灌丛中。目前在北京已知仅有密云雾灵山一带有可靠的稳定种群发现记录。近年数量有持续剧减之势。","seasonality_notes":"发生期很早，成虫集中在春末夏初的 5–6 月间出现，飞翔时姿态极其轻盈飘逸。","cover_image_url":"/insects/images/parnassius-citrinarius-1.jpg","is_active":true},{"slug":"aporia-crataegi","common_name":"绢粉蝶","scientific_name":"Aporia crataegi","aliases":[],"taxon_group":"鳞翅目 粉蝶科","identification_notes":"翅展 62–78 mm。外观极其形似白色无斑的绢蝶（故名绢粉蝶）。前翅端缘较平直，全身翅大部为纯白色，翅脉为极清晰的对比黑褐色（脉端具有黑色三角形发散状镶边）。触角较长，端部具明显白色或淡色小锤。翅反面基部全白色无任何黄斑。中室内无黑‘Y’纹。","habitat_notes":"山区极其常见、且极具代表性的丰产品种。从低山浅山一直到高海拔山顶均大范围有其种群栖息，成虫具有强烈的集群吸水、集群吸食发酵汁液或集群访花习性，常数十只抱团在一处泥地上。","seasonality_notes":"成虫盛发于 5–7 月间（初夏）。","cover_image_url":"/insects/images/aporia-crataegi-1.jpg","is_active":true},{"slug":"aporia-hippia-crataegioides","common_name":"小檗绢粉蝶","scientific_name":"Aporia hippia crataegioides","aliases":[],"taxon_group":"鳞翅目 粉蝶科","identification_notes":"翅展 56–74 mm。前翅端缘较圆弧，翅白色脉黑色。它与极其常见的绢粉蝶很相似，但最核心的识别要点是：其前翅正面的中室端部、围绕着翅脉明显扩展出一大块晕染状的独立黑色大斑块，且翅膀反面（尤其是后翅反面）的翅基部呈鲜艳的亮黄色。北京产者为华北亚种。","habitat_notes":"数量远少于绢粉蝶的山区特有种。其幼虫食性极其严苛，仅专性以野生的小檗科植物（如大叶小檗等）为寄主。因而其种群高度局限在拥有该植物的中、高海拔山林或林缘中。东灵山、百花山、雾灵山、干沟门有记录。","seasonality_notes":"成虫活跃在 5–7 月间。","cover_image_url":"/insects/images/aporia-hippia-crataegioides-1.jpg","is_active":true},{"slug":"pieris-napi-dulcinea","common_name":"暗脉粉蝶","scientific_name":"Pieris napi dulcinea","aliases":["褐脉菜粉蝶"],"taxon_group":"鳞翅目 粉蝶科","identification_notes":"翅展 40–50 mm。体型明显小于上述两种绢粉蝶，略似白粉蝶。翅白色，但最独特特征是：其翅膀反面（尤其是后翅反面）的大部分纵向翅脉的两侧，都强烈地向外扩展出大面积的、墨绿色或褐黑色粗肥大条纹（显得脉络极其暗黑粗重）。后翅反面基部具一黄斑。","habitat_notes":"山区常见粉蝶（华北产者为 dulcinea 亚种）。其主要分布在本市中、高海拔的山区中（如东灵山、百花山等），在山顶开阔的草甸、野地杂草中极多，非常喜欢访问各种十字花科或蔷薇科的野花。","seasonality_notes":"成虫盛发于 5–7 月份间。","cover_image_url":"/insects/images/pieris-napi-dulcinea-1.jpg","is_active":true},{"slug":"pieris-rapae","common_name":"菜粉蝶","scientific_name":"Pieris rapae","aliases":["白粉蝶"],"taxon_group":"鳞翅目 粉蝶科","identification_notes":"翅展 42–54 mm。最典型、最常见的小白蝴蝶。翅纯白色。前翅正面顶角（前缘角）区域具有一个清晰的三角形黑色斑块（反面则为纯白色）；前翅正面和反面通常具有 1–2 个明显的独立黑圆点斑；后翅前缘正面具 1 黑斑。有些个体后翅反面带淡淡的粉黄色。","habitat_notes":"全民皆知的最著名普产品种。生态适应力极端强大，无论在繁华的平原城市中心、公园绿地、郊区大规模农田菜地、还是深山峡谷及高山顶峰，几乎任何有植物生长和有花盛开的地方都有其极大量的个体活动。对十字花科蔬菜（如油菜、白菜）有一定危害。","seasonality_notes":"成虫见于 3–10 月（春季到秋季几乎天天可见）。常群聚飞舞，可利用其恋爱习性进行经典的‘遛蝴蝶’民俗游戏。","cover_image_url":"/insects/images/pieris-rapae-1.jpg","is_active":true},{"slug":"pontia-daplidice","common_name":"云粉蝶","scientific_name":"Pontia daplidice","aliases":["花粉蝶","云斑粉蝶"],"taxon_group":"鳞翅目 粉蝶科","identification_notes":"翅展 35–55 mm。体型较小。翅白色。前翅正面顶角附近和中室端部具有由于黑色鳞片形成的、破碎断裂的黑褐色大斑块（云斑状）；其最大特征是翅膀反面（尤其是后翅反面）密布着大面积由黄绿色或褐绿色鳞片形成的细碎大斑块，和白色区域形成斑驳绿白迷彩。","habitat_notes":"北京城区第二常见的白色蝴蝶（数量仅次于白粉蝶）。虽然数量极多，但成虫极度喜好合拢双翅进行休息或访花，故日常多以其反面的黄绿色迷彩斑示人。广泛分布于平原城区的野地、荒地、大规模农田、校园以及各级山区中。","seasonality_notes":"成虫活跃期为 4–10 月间（春夏秋季随处可见）。","cover_image_url":"/insects/images/pontia-daplidice-1.jpg","is_active":true},{"slug":"polygonia-c-aureum","common_name":"黄钩蛱蝶","scientific_name":"Polygonia c-aureum","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 48–57 mm。中型。特征极其明显：前、后翅的端外缘均呈现极强烈、且十分尖锐的波浪状大锯齿形（如倒钩状）；翅正面为非常艳丽的落日橙黄色或橘黄色，上面散布着大小不一的豹纹状黑色圆斑。翅反面完全为枯褐色或黑褐色细密麻纹，极似一片干枯的树皮。","habitat_notes":"本市最常见蝴蝶之一（常见程度高居前三位）。生态习性广泛，平原城市公园、高层社区附近、农村院落及山区皆多。成虫有强烈的吸食树汁和腐果习性，酷爱聚集在柳树、榆树的流汁处、或各类夏秋季垃圾堆的烂西瓜皮、腐烂水果堆上，和白星花金龟经常混生。也极喜在晴天停落在马路、石块上晒太阳。","seasonality_notes":"3–10 月可见成虫活动，具有独特的以成虫方式进行冬眠越冬的习性（早春和深秋极活跃）。","cover_image_url":"/insects/images/polygonia-c-aureum-1.jpg","is_active":true},{"slug":"polygonia-c-album","common_name":"白钩蛱蝶","scientific_name":"Polygonia c-album","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 49–54 mm。与黄钩蛱蝶极其相似且数量同样较多，但最核心的识别区别要点是：其前后翅端外缘的波浪状大锯齿显得‘明显要圆钝很多’、绝对不十分尖锐外突；且其前翅正面的翅基部暗色区的外侧边缘、明显‘完全缺乏’黄钩蛱蝶所拥有的那一对黑圆点（故翅面黑斑总数明显少一个）。反面呈枯叶状，具一小白‘C’字纹。","habitat_notes":"山区及近山地区常见种。其生态适应力略偏向野外，在近山城区公园、以及山区各林缘、溪谷、山路边不难见到。成虫极喜在晴天中午停落在暴露的尘土道路、或大溪流边的石块上张翅晒太阳。","seasonality_notes":"3–10 月可见成虫活动，同样属于以成虫方式冬眠越冬的蛱蝶成员。","cover_image_url":"/insects/images/polygonia-c-album-1.jpg","is_active":true},{"slug":"dilipa-fenestra","common_name":"明窗蛱蝶","scientific_name":"Dilipa fenestra","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 60–70 mm。中型。自然展翅静伏时前翅十分低垂整体呈独特的菱形。翅正面为极度艳丽的、反光反色极强的金灿灿的橘黄色（阳光照射具明显的荧光感）。前翅近顶角处具有 2 个上下整齐排列的、无鳞片的透明‘明窗斑’。雌雄差异明显：雌性翅色较暗黑、窗斑明显硕大。","habitat_notes":"高人气、高颜值的早春山地特色靓丽蝴蝶。飞行速度快如闪电，极度迅猛。主要栖息在较低及中等海拔高度的山区溪谷、有清澈溪流流经的乱石滩周围（如鹫峰、虎峪、碓臼峪、松山、雾灵山等）。","seasonality_notes":"发生期极早且短暂，成虫仅集中在早春的 4–5 月间可见（春游时最易相遇），是春季山林中亮丽的风景。","cover_image_url":"/insects/images/dilipa-fenestra-1.jpg","is_active":true},{"slug":"fabriciana-adippe-vorax","common_name":"捷灿福蛱蝶","scientific_name":"Fabriciana adippe vorax","aliases":["捷豹蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 65–70 mm。中型。翅正面为明亮橙黄色，具布满翅面的典型豹纹状黑色点斑；后翅反面密布大面积黄褐色、并缀有大量极闪亮的、水银滴状的银白色或白色大斑点。前翅外缘的一列黑线，在翅的中下部弯曲连成一排明显的朝向基部的‘›’形弧斑（波浪线），可与其他豹蛱蝶区分。雄具 2 条性标。华北产者为 vorax 亚种。","habitat_notes":"本市最常见、分布最广泛的一种豹蛱蝶（旧版名录多叫捷豹蛱蝶）。其生态海拔跨度极大，从海淀近山平原、各浅山山谷、一直到海拔 2000m 以上的高山顶部草甸（如东灵山顶峰）均可见到成虫在草丛上快速低空飞舞。强烈访花。","seasonality_notes":"成虫见于 5–8 月份间（初夏到盛夏）。","cover_image_url":"/insects/images/fabriciana-adippe-vorax-1.jpg","is_active":true},{"slug":"speyeria-aglaja-graeseri","common_name":"银斑豹蛱蝶","scientific_name":"Speyeria aglaja graeseri","aliases":["福豹蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 62–65 mm。翅正面橙黄色、布满典型豹纹状黑斑；后翅反面基半部及大部表现为极显眼的、深重的暗绿褐色（或青绿色），上面密布一列列整齐的银白色或纯白色圆大斑点。前翅外缘的一列黑线全由连续的‘›’形黑斑组成。雄虫完全没有性标。华北产者为 graeseri 亚种，曾被错误叫作福豹蛱蝶。","habitat_notes":"典型的高山草甸特有常见豹蛱蝶。主要集中分布在本市较高海拔的山顶或山脊开阔草甸环境中（如门头沟东灵山、百花山、延庆海坨山等顶峰），在海拔 700m 的低山有时也有少量记录。极度喜好访问草甸上的大蓟、狼毒等各种野花。","seasonality_notes":"成虫盛发于 6–8 月盛夏高山花季。","cover_image_url":"/insects/images/speyeria-aglaja-graeseri-1.jpg","is_active":true},{"slug":"argynnis-zenobia","common_name":"曲纹银豹蛱蝶","scientific_name":"Argynnis zenobia","aliases":["银豹蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 78–90 mm。大型。雌雄异色极显著：雄性翅正面橙黄色具黑豹纹（具 3 条性标）；雌性翅色极为深暗，为带有神秘绿灰色、青褐色或墨绿色的暗橙色，黑斑粗大。无论雌雄，后翅反面均为极其独特的暗绿褐色、上面分布着由白色条纹相互交错形成的‘不规则网格状或曲折波线状’白色纹理。前翅外缘内侧具有两列整齐的圆大黑点点列。","habitat_notes":"大形精美、分类曾长期被错定为‘南方种银豹蛱蝶’的山区特色蝴蝶（本地产者属于 penelope 亚种）。广泛分布于本市各大中、低海拔山林、茂密山谷及景区中（如北京植物园樱桃沟、房山十渡、昌平碓臼峪、密云雾灵山等）。成虫喜在林间阳光斑驳的小道上快速高飞，或停落在溪边吸水。","seasonality_notes":"成虫主要在 6–8 月间活跃。","cover_image_url":"/insects/images/argynnis-zenobia-1.jpg","is_active":true},{"slug":"argynnis-paphia","common_name":"绿豹蛱蝶","scientific_name":"Argynnis paphia","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 72–85 mm。大型。雌雄异色极显著：雄性正面橙黄色具黑豹纹，最核心特征是前翅上具有多达 4 条平行的、极其粗黑发达的纵向黑色毛状性标条纹（数量最多）；雌性翅色通体为完全的、极其深暗的‘绿褐色’或墨绿色，且前翅基部的黑横纹数量明显稀少。后翅反面为绿褐色具有几条纵向白色长条纹（非网格状）。","habitat_notes":"高山草甸及深山阔叶林边缘的常见大型豹蛱蝶。主要分布于本市雾灵山、东灵山、百花山、小龙门等林貌完好的中、高海拔山区中，在低海拔的北京植物园樱桃沟、昌平碓臼峪等也有残存种群。成虫飞翔极其强健敏捷。","seasonality_notes":"成虫盛发于 6–8 月间，常访问林缘的大灌木花朵（如接骨木、线菊等）。","cover_image_url":"/insects/images/argynnis-paphia-1.jpg","is_active":true},{"slug":"argynnis-hyperbius","common_name":"斐豹蛱蝶","scientific_name":"Argynnis hyperbius","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 75–80 mm。中大型。全本地最容易、绝对不会认错的豹蛱蝶。雌雄异色异型极端：雌性前翅的端半部完全为极显眼的‘藏蓝色或蓝黑色’、里面横贯着一粗大斜置的白斑块和一列白点，前翅基半部为高对比度的落日橙色至曙红色；雄性翅面大部为普通黑豹纹，但其后翅外缘具有一圈极宽大的纯黑色宽边，黑边里靠近臀角处带有明显的淡蓝色曲折线纹。独立归于单种亚属。","habitat_notes":"高颜值、在平原地区遇见率最高的一种大形豹蛱蝶。属于典型的喜温性低山及平原广布种。在城区各大公园（如奥森、圆明园、植物园、颐和园）、校园绿地、郊区农田、以及本市各低山浅山山谷、路边草丛中极其常见。极度喜好访问各种人工种植的景观花卉（如百日草、孔雀草等）。","seasonality_notes":"成虫活跃期极长，见于 6–10 月间（夏秋季随处可见）。","cover_image_url":"/insects/images/argynnis-hyperbius-1.jpg","is_active":true},{"slug":"brenthis-daphne","common_name":"小豹蛱蝶","scientific_name":"Brenthis daphne","aliases":["桂小豹蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 50–60 mm。体型明显小于上述大形豹蛱蝶类。翅正面与前翅反面均为橙黄色黑豹纹。其与最近似的伊诺小豹蛱蝶的核心区别特征是：本种成虫的躯体及翅基毛羽颜色‘通常非常鲜黄色’；且前翅正面最外缘内侧的一排一列黑圆点斑、彼此之间相互完全独立分隔、绝对不趋于联结成线；后翅反面端部具有 2 条明显的紫褐色晕状横条带。","habitat_notes":"中、高海拔山区草甸或林缘的丰产常见种。主要大范围集中在东灵山、百花山、小龙门、雾灵山等海拔 1000m 以上的区域中。成虫经常成百上千只地密集飞舞在山路两侧的野花丛中，构成壮观画面。","seasonality_notes":"成虫集中盛发于 6–8 月盛夏高山花季。","cover_image_url":"/insects/images/brenthis-daphne-1.jpg","is_active":true},{"slug":"brenthis-ino","common_name":"伊诺小豹蛱蝶","scientific_name":"Brenthis ino","aliases":["纤小豹蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 44–56 mm。本地体型最小的一种豹蛱蝶成员。其与极其相似的小豹蛱蝶的最核心识别区别要点是：本种成虫的整个躯体（头胸腹）及翅基部密被的毛羽颜色‘通常明显发黑、呈黑褐色’，没有任何鲜黄色感；且其前翅正面最外缘内侧的那一列黑圆点斑、彼此之间相互强烈地‘连成了一条黑线’；后翅反面端部具有 1 条宽大的红褐色晕状条带。","habitat_notes":"亚高山草甸或高山冷湿野地的特有常见小型豹蛱蝶。其生境比小豹蛱蝶更偏向于高海拔高寒地带。在本市门头沟东灵山、百花山等海拔 1500m 以上的山顶开阔大草甸上数量极多、密度极大。强烈访花。","seasonality_notes":"成虫集中盛发于 6–8 月间（盛夏最常见）。","cover_image_url":"/insects/images/brenthis-ino-1.jpg","is_active":true},{"slug":"melitaea-arcesia","common_name":"艾网蛱蝶","scientific_name":"Melitaea arcesia","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 36–43 mm。体型较小。翅正面乍看亦为黑黄豹纹，但其纹理与上述豹蛱蝶类截然不同。最核心识别特征是：其后翅反面完全由一列列整齐的、方形或不规则长方形的‘纯白色与淡黄色网格状斑块’交错排列而成，绝无任何水银斑。雌雄差异极端巨大：雄性正面多为纯粹的橙黄色黑网格；雌性翅面大部全被黑色覆盖，网格中彩色斑块多色（橘黄、淡黄、纯白交杂，极多彩）。","habitat_notes":"高山草甸特有的网蛱蝶代表。具有明显的冷凉性。在本市仅稳定分布和多见于门头沟东灵山、百花山等海拔 1200m 以上的高山草甸、高寒灌丛环境中，在上述环境的时节里数量极多，飞行高度极低，几乎贴地草皮上下翻飞。","seasonality_notes":"发生期较为集中，成虫集中在 6–7 月夏初发生。","cover_image_url":"/insects/images/melitaea-arcesia-1.jpg","is_active":true},{"slug":"araschnia-levana","common_name":"蜘蛱蝶","scientific_name":"Araschnia levana","aliases":["花斑蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 38–48 mm。体型较小。翅正面为橙黄色或橘黄色、上面满布着大量不规则断裂的黑色斑块，其中双翅基部附近的黑斑被橙黄色细线条密分割成漂亮的‘蛛网状或细网格状’；前翅靠近端外缘处、具有 3–4 个明显的孤立‘纯白色斑点’（可与网蛱蝶等相区别）。最核心特征是其翅膀反面密布着如同凌乱‘乱蜘蛛网’一样的白色细长线条纹理。","habitat_notes":"山区林缘及溪谷地带的常见小型蛱蝶。主要分布在本市延庆松山、密云雾灵山、怀柔喇叭沟门等大范围山区中。成虫喜低空飞行，喜好停落在林间的低矮草叶上、或在有阳光直射的溪边湿地上群聚吸水或访花。","seasonality_notes":"成虫见于 4–8 月间（春季到盛夏均可见到）。","cover_image_url":"/insects/images/araschnia-levana-1.jpg","is_active":true},{"slug":"limenitis-populi","common_name":"红线蛱蝶","scientific_name":"Limenitis populi","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 68–72 mm。体型较大，翅形方正。翅正面通体为纯黑色，上面饰有一系列对比清晰的纯白色斑点（其中后翅正面的白斑连成一排极其宽大、整齐且贯穿整个翅面的白色宽横带纹）；最核心特征是其前翅的前半部分外缘、以及后翅的整个外缘内侧，都密布着由一列鲜艳的‘红橙色（或红色）月牙状弧斑’组成的显眼虚线长条带，红纹内侧还紧挨着 2 条‘闪蓝色’或天蓝色的亮丽弧形细纹。无近似种。","habitat_notes":"大形精美、极具观赏价值的稀有山地线蛱蝶。其数量通常不多，属于偶见型的大型蛱蝶。主要栖息在本市植被极其茂密、且拥有完好原始阔叶林的中等海拔高度的深山林区中（如门头沟小龙门森林公园、密云雾灵山自然保护区等）。成虫喜在林冠层或高空强健飞行，偶下降到林间溪边小道停落。","seasonality_notes":"成虫发生期较为短暂局限，仅见于 6–7 月夏初时节。","cover_image_url":"/insects/images/limenitis-populi-1.jpg","is_active":true},{"slug":"limenitis-moltrechti","common_name":"横眉线蛱蝶","scientific_name":"Limenitis moltrechti","aliases":["眉线蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 50–55 mm。中型。自然停落姿态时前翅较为向上提取、不低垂（以此体态可与环蛱蝶属相区别）。翅正面黑色，后翅具有一排整齐相连的宽大白色横带纹。最核心的三大组合识别要点是：①前翅正面的最基部区域‘完全缺乏任何白斑或白条纹’；②前翅靠近基部约 1/3 的上方位置、具有一条完全孤立的、白色的‘眉毛状或细长弧形横白纹’（两翅该纹合拢呈横置的‘八字眉’状）；③前翅靠近顶角位置分布着 3 个竖向错位叠放的清晰白色圆斑点。翅端缘完全无红蓝色纹。","habitat_notes":"本地深山区林间最常见的一种线蛱蝶。广泛分布在本市各大中、高海拔的茂密森林、林缘及灌丛小道中（如门头沟小龙门、百花山、密云雾灵山自然保护区等）。成虫领地意识极强，具有强烈的张翅晒太阳习性，极其常见在森林山路、林间暴露的石块上或溪边死木上平展双翅静伏。飞翔强健。","seasonality_notes":"成虫盛发并见于 6–8 月盛夏期间。","cover_image_url":"/insects/images/limenitis-moltrechti-1.jpg","is_active":true},{"slug":"neptis-sappho","common_name":"小环蛱蝶","scientific_name":"Neptis sappho","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 40–50 mm。体型在本地环蛱蝶中明显偏小，自然停落时双翅完全平展身体显得极端横长。翅正面黑色，后翅具有 2 排平行的、由整齐白斑组成的白色横带纹。最核心识别特征是：其前翅正面最靠近外缘的区域、拥有一排由极其整齐的微小白色圆点排布而成的、‘与前翅端缘外轮廓弧度完全平行且连贯’的细白色弧形纹。前翅基部延伸出一细长直角三角形白基条，其端部与另一个相反的白斑底面相对（呈两色对顶）。北京产者为华北亚种。","habitat_notes":"山区夏季极其常见、也是最具代表性的一种环蛱蝶（俗称‘三线蝶’的一种）。大范围广泛分布于平原边缘浅山、以及低、中海拔山区的各种山路边、林缘灌丛、河谷开阔地带。成虫飞翔姿态极其独特优雅，为典型的‘滑翔—振翅—滑翔’交替的波浪状飘飞。常喜欢停在阳光充足的灌木叶片或路边乱石上。十分常见。","seasonality_notes":"成虫活跃期极长，见于 4–9 月间（春季到秋初）。","cover_image_url":"/insects/images/neptis-sappho-1.jpg","is_active":true},{"slug":"neptis-rivularis","common_name":"单环蛱蝶","scientific_name":"Neptis rivularis","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 45–52 mm。体型较小，自然静伏呈平展扁长状。翅正面黑色。最独特也是最核心的识别要点是：其后翅正面‘仅具有一排单一条’、由整齐方形白大斑组成的极宽大白色横带纹（后翅其余位置完全纯黑，绝无第二排白纹，故名单环）。前、后翅中部的这一排粗大白斑，在自然完全展翅静伏姿态时，刚好拼成一个横置的、巨大的、极其清晰相连的‘0’形环状斑纹。前翅基部延伸出的白斑边缘极其清晰锐利，无任何絮毛状不整齐边缘。华北产者为 magnata 亚种。","habitat_notes":"山区夏季极其常见、且特征最显著的环蛱蝶成员。大范围广泛广布于全市中、低海拔山区的各种山坡灌丛、林缘、阔叶林带或林间山路上。成虫飞翔特征与小环蛱蝶一致（滑翔飘飞），常见成群在路边低矮植物叶片上停憩，或在路面、石头上合翅吸食矿物质。","seasonality_notes":"成虫盛发并见于 5–8 月间（初夏到盛夏）。","cover_image_url":"/insects/images/neptis-rivularis-1.jpg","is_active":true},{"slug":"neptis-alwina","common_name":"重环蛱蝶","scientific_name":"Neptis alwina","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 70–77 mm。体型在本地所有的环蛱蝶属成员中明显‘最为硕大粗壮’。翅正面黑色，后翅具有 2 排由整齐方形白斑组成的白色横带纹（前面一排白斑与前翅白斑可连成完整的环纹）。核心组合识别要点是：①其前翅正面的最顶角（前缘角）区域、具有一个极其清晰的‘孤立白色斑点’（本地其余环蛱蝶该处均全黑）；②其前翅从基部向中部外延伸出的那一条最主要的粗白条纹，其端部的上边缘呈现极其松散、不整齐的‘絮毛状或羽毛状’毛糙边缘（非锐利边缘）。","habitat_notes":"山区夏季最常见的一种大型环蛱蝶。大范围广泛分布于本市各中、低海拔山区的森林边缘、灌木丛、阴湿山谷及各种景区中。由于体型硕大，其飞翔能力和滑翔力量明显比小环蛱蝶、单环蛱蝶更强健迅猛。极常见在山林间的小道、暴露的巨大石块上、或水边的潮湿砂石上停歇或飞舞。","seasonality_notes":"成虫集中活跃在 6–8 月盛夏季节。","cover_image_url":"/insects/images/neptis-alwina-1.jpg","is_active":true},{"slug":"neptis-themis","common_name":"黄环蛱蝶","scientific_name":"Neptis themis","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 65–75 mm。中到大型。翅形及斑纹排布与单环蛱蝶等线蛱蝶属环蛱蝶非常相似，但本种最独特、最核心的特征是：其翅膀正面所有的‘斑纹和横带颜色全部为非常明亮的鲜黄色或橙黄色’（绝非白色），前、后翅中部的黄斑在自然展翅静伏姿态时同样连成横置‘0’形黄环。最核心的组合细节识别要点是：①其前翅正面靠近顶角处分布着 3 个明显的黄斑，呈高度错位阶梯状排列，其中最下方的一个黄斑外形呈现规则的‘圆形、且边界极为清晰锐利’，下方绝对没有任何擦痕状或晕染状的拖尾，且它比上面的两个黄斑明显要朝外（朝向翅缘）跨出一大步；②前翅由基部向外延伸的长黄条，其端部距离其外侧的独立黄斑极近，二者之间的黑色分割空隙狭窄得如一条细线。指名亚种。","habitat_notes":"山区夏季极其常见、且配色极为亮丽高颜值的黄斑环蛱蝶。广泛大范围分布于本市各中、低海拔山区的针阔混交林缘、阔叶林、各种杂灌丛生的小道及山坡周围（如门头沟小龙门、百花山、怀柔喇叭沟门、密云雾灵山等）。成虫飞翔姿态飘逸优雅，极喜在有阳光直射的林缘灌木叶片、或山路乱石上平展双翅停落晒太阳。十分常见。","seasonality_notes":"成虫盛发并见于 6–8 月盛夏期间。","cover_image_url":"/insects/images/neptis-themis-1.jpg","is_active":true},{"slug":"neptis-thisbe","common_name":"提环蛱蝶","scientific_name":"Neptis thisbe","aliases":["拟黄环蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 68–81 mm。体型通常比黄环蛱蝶还要略粗大一些。斑纹横带同样全为鲜黄色。其与极其相似的黄环蛱蝶的最核心细节组合识别要点是：①其前翅正面靠近顶角处同样分布着 3 个错位排列的黄斑，但中间的一个黄斑面积往往明显膨大肥硕，且最下方的那个小黄斑形状不圆、呈略微竖长形、且其下方的黑色区域里明显‘拖着一条模糊的、由于黄色鳞片弥散形成的擦痕状或晕染状拖尾黑影’；②其前翅由基部向外延伸的长黄条，其端部与其外侧独立大黄斑之间的黑色分割空隙明显较为开阔，绝对不为细线状（二者距离较远）。即旧版图鉴未定种的‘拟黄环蛱蝶’。","habitat_notes":"山区不常见的一种珍稀黄色环蛱蝶。数量较少，分布范围相对狭窄。以往在本地的历史文献中仅有极零星记录，且长期被误定或未定种，目前已知其仅确凿分布在本市门头沟深山区、以及密云区雾灵山自然保护区的少数中、高海拔阔叶林或混交林边缘。成虫飞翔强健，多在林冠层或高空活动。","seasonality_notes":"成虫活动和发生期在 6–9 月间，夏末较为多见一些。","cover_image_url":"/insects/images/neptis-thisbe-1.jpg","is_active":true},{"slug":"kaniska-canace","common_name":"琉璃蛱蝶","scientific_name":"Kaniska canace","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 53–70 mm。中型。特征极其鲜明显眼：翅正面通体为深沉的黑褐色或纯黑色，上面横贯着一条极其宽大、连续、且光泽度极高的‘亮天蓝色（或闪蓝色）荧光色带纹’（色带从前翅顶角内侧沿翅外缘内方一路连贯、毫无断裂地直接笔直延伸到后翅的整个臀角位置）；翅反面则为由于极其细密的黑褐色麻纹与褶皱斑组成的纯暗枯叶状，具极强伪装保护色。无任何近似种。","habitat_notes":"本市低山地带和近山地带溪流、河谷附近极具人气、极其常见的一种高颜值山地特色蛱蝶。广泛大范围分布于海淀近山公园（如北京植物园樱桃沟、鹫峰、阳台山等）、门头沟低山山谷、房山十渡、昌平碓臼峪、密云雾灵山等地。成虫飞翔极其强健迅猛，警惕性极高极难接近，常在早春阳光充足的乱石滩、路上晒太阳，或在树干流出发酵汁液处聚集吮吸。","seasonality_notes":"由于其完全以成虫方式进行冬眠越冬，成虫发生期极早，在早春的 4–5 月间为最主要的发生高峰期（此时相遇率最高），至盛夏及秋季（ 6–9 月）也有新一代个体活动。","cover_image_url":"/insects/images/kaniska-canace-1.jpg","is_active":true},{"slug":"aglais-urticae","common_name":"荨麻蛱蝶","scientific_name":"Aglais urticae","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 38–48 mm。中型偏小。极为漂亮的暖色系蝴蝶。两翅正面以极其亮丽的、浓郁的‘落日橙色或橙红色’为主色调；前翅前缘非常规则地分布着 3 个大块的方形黑色斑块，翅中部也具有 1 大 2 小的黑圆斑；后翅的整个基半部完全为纯黑色（与外侧的橙色形成强烈黑橙对比），最核心美观特征是其前、后翅的整个端外缘黑色边缘带里，都整齐地镶嵌着一排极其耀眼的、由‘天蓝色（或亮蓝色）月牙状弧斑’组成的彩色珠状虚线。后翅具一极短尖尾突。幼虫专食荨麻。","habitat_notes":"山区常见的高颜值靓丽蛱蝶。具有明显的偏向中、高海拔高寒环境的生态习性。在全市各大植被保存完好的中、高海拔深山区、山顶开阔草甸或林缘灌丛（如门头沟小龙门、百花山、东灵山、密云雾灵山等）数量很多。成虫极其喜好在山坡草地、路边草丛中快速低空飞舞，疯狂访问各类野花。","seasonality_notes":"成虫盛发并多见于 6–8 月盛夏期间，在长有大量刺手荨麻的荒地上极多（因其幼虫专食荨麻）。","cover_image_url":"/insects/images/aglais-urticae-1.jpg","is_active":true},{"slug":"inachis-io","common_name":"孔雀蛱蝶","scientific_name":"Inachis io","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 53–63 mm。两翅正面大部为高雅的铁锈红褐色或深红色。最震撼的特征是：前翅顶角与后翅外侧各精确定位分布着一个硕大无比、极其复杂的‘眼状斑’。其中后翅的眼斑内大部为深蓝色与天蓝色，上方还有一黑色弧纹，如浓眉蓝瞳一般；翅反面为细密的黑卷褐麻纹，具极强保护色。","habitat_notes":"世界著名的美丽蝴蝶。在本市中海拔山区广布，但总体数量不算多，常见于山林、溪谷以及林缘开阔的草地上。","seasonality_notes":"4–9 月可见成虫活动，并以成虫方式进行冬眠越冬。","cover_image_url":"/insects/images/inachis-io-1.jpg","is_active":true},{"slug":"vanessa-indica","common_name":"大红蛱蝶","scientific_name":"Vanessa indica","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 54–70 mm。前翅中部和后翅端缘为橙色（老话常称红色）并具黑斑。前翅顶角内侧近一半区域为纯黑色、内有一系列对比鲜明的白色碎斑。其与小红蛱蝶的最核心区别在于：其前翅下半部分、以及后翅的整个基部到中部的绝对大部区域，完全为没有斑点的、大面积的均一黑褐色或暗褐色。","habitat_notes":"本市常见蝴蝶之一。在山区相当多见，平原也有分布但数量较少。成虫极度喜好前往树干流出发酵汁液处、各种烂水果堆或大片的花丛中取食。","seasonality_notes":"5–10 月可见成虫活动。","cover_image_url":"/insects/images/vanessa-indica-1.jpg","is_active":true},{"slug":"vanessa-cardui","common_name":"小红蛱蝶","scientific_name":"Vanessa cardui","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 47–67 mm。整体色彩略似黑豹纹蛱蝶，但前翅顶角向内近半区域完全为黑色，里面散布着数个纯白色斑点。其与大红蛱蝶的最核心区别在于：本种两翅正面的中间和基部的大部分区域，‘全部布满了’橙色与黑色的交错斑纹，绝对没有大红蛱蝶那般大面积无斑的褐色暗区。","habitat_notes":"本市常见蝴蝶之一。在山区大范围多见，平原也有零星出现。有强烈的访花和吮吸腐果发酵树汁的习性，常在山坡野地、烂水果堆周围出没。","seasonality_notes":"6–10 月可见成虫活动。","cover_image_url":"/insects/images/vanessa-cardui-1.jpg","is_active":true},{"slug":"mimathyma-schrenckii","common_name":"白斑迷蛱蝶","scientific_name":"Mimathyma schrenckii","aliases":["大闪蛱蝶"],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 88–94 mm。大形。旧版名录多称大闪蛱蝶。翅面整体为深黑色。前翅前缘中部有一列整齐竖叠的白色宽斑，中部靠后缘处具有一显著的橙红色（或红色）月牙形弧斑；后翅中部具有硕大的半透明白大斑、且白斑下方托有极其迷人的‘天蓝色或深蓝色’宽边。北京产者为 media 亚种。","habitat_notes":"本市不常见、极具观赏价值的珍稀大型明星蝴蝶。其种群数量有限，一般孤立且零星地见于本市环境极佳的中海拔原始林区或繁茂山谷中。","seasonality_notes":"成虫盛发并见于盛夏的 7–8 月份。","cover_image_url":"/insects/images/mimathyma-schrenckii-1.jpg","is_active":true},{"slug":"sasakia-charonda","common_name":"大紫蛱蝶","scientific_name":"Sasakia charonda","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 80–115 mm。巨大型蛱蝶。雌雄异色极端显著：雄性成虫两翅正面的基半部，长有一大片反光极强的、具有强烈的魔幻蓝紫色或紫蓝色荧光效果的彩色区，翅端半部为纯黑色，满布白色或黄白色圆斑点，后翅靠近臀角处还精细地点缀着两个‘橙红色或小红点’；雌性体型极大但翅面完全没有闪紫色区域。","habitat_notes":"名震昆虫界、极具超高人气与观赏价值的顶级著名大型蝴蝶。在本市整体数量稀少，具有极强的生态特异性，一般仅能零星见于少部分中海拔、混交林保存完好的古老深山林区或山谷中。","seasonality_notes":"成虫发生于盛夏的 7–8 月份间。","cover_image_url":"/insects/images/sasakia-charonda-1.jpg","is_active":true},{"slug":"apatura-ilia","common_name":"柳紫闪蛱蝶","scientific_name":"Apatura ilia","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 55–72 mm。中型。雌雄异色显著：雄性翅正面基部与大部，随着光照与观察角度的变化，能迸射出极强烈的、如大紫蛱蝶般的蓝紫色或闪紫色反光（无特定角度时光泽消失显黑色）。本种最核心的识别要点是：其前、后翅的正面，‘各精确地发育有一个’圆形的、边缘为鲜艳红橙色的、中心有白心的眼状斑。","habitat_notes":"本市山区较常见、且极其美丽的特色闪蛱蝶。主要分布在本市各大中、低海拔山林林缘、山路灌丛或水系溪谷周围（如雾灵山、小龙门等）。成虫飞翔极其迅猛强健，极喜在林区湿地上吸水。","seasonality_notes":"成虫主要在 6–8 月盛夏发生。","cover_image_url":"/insects/images/apatura-ilia-1.jpg","is_active":true},{"slug":"libythea-celtis","common_name":"朴喙蝶","scientific_name":"Libythea celtis","aliases":[],"taxon_group":"鳞翅目 蛱蝶科","identification_notes":"翅展 42–49 mm。中型偏小。长相极其独特、绝不会认错。最显著的特征是：其长有两对极端特化延长、僵直前伸在头顶前方、状如鸟嘴或‘鸟喙状’的下唇须。其触角也单调短小缺乏端锤。前翅端外缘的中部呈现强烈的、向后尖锐倒钩状的特殊突出外形。翅正面黑褐色具一系列不规则橙色斑。","habitat_notes":"山区春季极其常见、长相极奇特的喙蝶代表（喙蝶科现已并入蛱蝶科）。广泛大范围分布于本市所有低山、浅山及中海拔山区中。因其完全以成虫方式进行冬眠越冬，它与朴树等植物共生，在早春阳光刚普照时常漫山遍野群聚飞舞或在路上吸水。","seasonality_notes":"由于越冬习性，其成虫是本地每年‘最早出现和活动’的春季蝴蝶之一，主要活跃期在 4–8 月间。","cover_image_url":"/insects/images/libythea-celtis-1.jpg","is_active":true},{"slug":"melanargia-halimede","common_name":"白眼蝶","scientific_name":"Melanargia halimede","aliases":[],"taxon_group":"鳞翅目 眼蝶科","identification_notes":"翅展 58–62 mm。中型。本种是除绢眼蝶外，北京仅有的以纯白色为主色调的眼蝶，绝无近似种。两翅整体为高对比度的乳白色，翅外缘（端缘）、前翅后缘及前缘脉均分布着由大面积深黑褐色构成的方格状粗网格花纹。头、胸、腹部也全为黑色被有白毛。","habitat_notes":"高山草甸或亚高山草甸环境中最具代表性、数量最大的固有特色眼蝶。其种群高度局限在本地海拔较高的各个山顶高寒草甸及林缘灌丛草地中（如门头沟东灵山、百花山、延庆闫家坪等）。成虫在草尖上成片漫飞，极常见。","seasonality_notes":"成虫发生于 6–8 月盛夏高山花季。","cover_image_url":"/insects/images/melanargia-halimede-1.jpg","is_active":true},{"slug":"lasiommata-deidamia","common_name":"斗毛眼蝶","scientific_name":"Lasiommata deidamia","aliases":[],"taxon_group":"鳞翅目 眼蝶科","identification_notes":"翅展 52–55 mm。中型。体躯、四翅背面和反面全部为高度一致的暗黄褐色或枯树皮褐色。最核心的识别特征是：其前翅正面靠近最顶角的位置，‘精确定位发育有一个’圆形的、深黑色的、且正中心有白亮心的中型眼状斑，且该眼斑的内侧和下侧还紧挨着由一系列乳白色碎鳞形成的碎云状白纹。后翅正面具 2–3 个小眼斑。","habitat_notes":"本市大范围山区森林内部、林下最常见、数量最大的一种固有眼蝶。广泛大范围分布于从低山浅山到高海拔的各种郁闭度高、有深厚枯枝落叶层的落叶阔叶林或针阔混交林下。具有极强的生态保护色，受惊扰常不远飞，仅扇翅几下便立刻自信地再次停落在落叶层上融入背景。","seasonality_notes":"成虫活跃和发生期跨度极长，见于 4–9 月间（春季到秋初均极多）。","cover_image_url":"/insects/images/lasiommata-deidamia-1.jpg","is_active":true},{"slug":"minois-dryas","common_name":"蛇眼蝶","scientific_name":"Minois dryas","aliases":[],"taxon_group":"鳞翅目 眼蝶科","identification_notes":"翅展 52–55 mm。在本市国产眼蝶中属于体型最大、最粗壮的种类之一。体躯与四翅正面均表现为极其浓重的、发黑的、没有任何杂纹的黑褐色或纯墨黑色。最核心组合识别要点是：其前翅正面‘上下整齐垂直排列着两个’圆大的黑色眼状斑，且后翅正面中央偏下‘具有 1 个’较小的黑眼斑，这 3 个眼斑的圆心都精细地缀有纯白色眼瞳点。","habitat_notes":"山区林缘及草丛荒地的大型特色眼蝶。大范围广泛分布于本市所有中、低海拔山区的针阔混交林边缘、灌木边缘、或山路两侧杂草丛生的野地中。飞翔姿态呈眼蝶典型的笨拙跳跃状，常在草尖或林缘灌丛低空飞舞。","seasonality_notes":"成虫盛发并见于盛夏的 7–8 月份。","cover_image_url":"/insects/images/minois-dryas-1.jpg","is_active":true},{"slug":"davidina-armandi","common_name":"绢眼蝶","scientific_name":"Davidina armandi","aliases":["丫纹绢眼蝶"],"taxon_group":"鳞翅目 眼蝶科","identification_notes":"翅展 54–56 mm。中型。为眼蝶中极端异化的另类：翅的两面‘完全没有任何眼状斑点’。其纯白色的翅和黑褐色的清晰翅脉，常使其外观严重被外行误认为是某种绢蝶或绢粉蝶。但其最具决定性的核心特征是：其前翅、后翅的‘中室大格内部’，都横贯着一个由黑褐色线条组成的、极为深重清晰的‘Y’字形（或老话称‘丫’字形）黑纹，且翅端缘各脉间具细黑短纹。","habitat_notes":"形态特异、分类特殊的山地眼蝶（曾单独列属或亚科）。其分布海拔跨度较大，可见于 700–2300m 的各级山区，主要局限在落叶阔叶林林缘、山坡林间小道或高山灌丛边缘，属零星偶见型，一般数量不算多。","seasonality_notes":"成虫活动和发生期集中在 5–7 月间（初夏）。","cover_image_url":"/insects/images/davidina-armandi-1.jpg","is_active":true},{"slug":"everes-argiades","common_name":"蓝灰蝶","scientific_name":"Everes argiades","aliases":["苇尾蟌","琉璃鼠儿"],"taxon_group":"鳞翅目 灰蝶科","identification_notes":"翅展 20–28 mm。体型极端渺小玲珑。后翅端部各长有一根如黑头发丝般‘柔细纤长、长针状的尾突’。雌雄异色极其严重：雄性成虫双翅正面为大面积极其耀眼的、亮闪闪的‘金属天蓝色或宝石蓝色’，仅翅最端外缘有一道细黑边；雌性正面大部完全为暗黑色、无蓝光，仅后翅端部有一列小红斑。翅反面纯白布满黑点和橙红斑。","habitat_notes":"本市最常见、也是数量最大、相遇率最高的一种高颜值小型灰蝶代表（俗称‘小蓝蝴蝶’的代名词）。具有极强的生态适应力，广泛遍布于全市从城中心小区绿地、各公园大片草坪、郊区农田杂草、一直到各大山区和山路两侧的低矮野花上。成虫对各类低矮豆科草本花卉具有强烈的访花和产卵习性。","seasonality_notes":"成虫活跃期极长，从春季一直到秋末的 4–9 月间随处可见（发生世代极多）。","cover_image_url":"/insects/images/everes-argiades-1.jpg","is_active":true},{"slug":"lycaeides-argyrognomon","common_name":"红珠灰蝶","scientific_name":"Lycaeides argyrognomon","aliases":[],"taxon_group":"鳞翅目 灰蝶科","identification_notes":"翅展 30–35 mm。体型通常比蓝灰蝶明显稍粗大一些。其与最易混淆的蓝灰蝶的最核心区别特征是：其后翅最外缘‘完全圆滑、绝对没有任何柔细的丝状长尾突’；且其雄性成虫翅正面的最前缘区域（后翅前缘）、分布着一条极宽大的、明显的深纯黑色带状暗区，而其外缘黑色细边窄到裸眼难察。雌性正面全黑褐色，后翅具一排相连的高对比度月牙形‘红珠斑’（故名红珠灰蝶）。","habitat_notes":"本市山区及郊区野地极常见的一种‘小蓝蝴蝶’成员。主要广泛大范围分布在本市各大中、低海拔山区的山坡杂草丛、林缘野地、或平原郊区的开阔原生态荒草地中。成虫低空飞舞能力强，极度喜好围绕着马根草、苜蓿等野生豆科草本植物进行盘旋和访花。","seasonality_notes":"成虫盛发并见于 4–9 月间（春夏秋季均极多发生）。","cover_image_url":"/insects/images/lycaeides-argyrognomon-1.jpg","is_active":true},{"slug":"epicopeia-mencia","common_name":"榆凤蛾","scientific_name":"Epicopeia mencia","aliases":[],"taxon_group":"鳞翅目 凤蛾科","identification_notes":"翅展 55–91 mm。大形。属于极为罕见的、在‘白天活跃且高飞’的大型飞蛾。其最大特征是拥有极度特化和完美的拟态伪装外形：其整体翅形（尤其是后翅长有一对大而长、平截状的粗尾突）、以及翅的配色（纯黑色翅具一列新月形红色花斑）、甚至连其腹部侧面红黑相间的色彩节，都‘完美模拟了全剧毒的红珠凤蝶或凤蝶’。但其羽状或栉齿状触角、及粗臃肿的身体暴露了蛾的身份。","habitat_notes":"极具趣味性拟态典故的高人气昼行性大型特色蛾类。在本市山区属于偶见种，数量不算很大。其幼虫食性高度单一，专性以各种野生榆树（如裂叶榆、家榆等）的叶片为食。成虫多高飞在榆树林顶端，雌虫常围绕榆树枝叶盘旋进行产卵。","seasonality_notes":"成虫集中在 7–8 月盛夏季节发生与活动。","cover_image_url":"/insects/images/epicopeia-mencia-1.jpg","is_active":true},{"slug":"macroglossum-stellatarum","common_name":"小豆长喙天蛾","scientific_name":"Macroglossum stellatarum","aliases":[],"taxon_group":"鳞翅目 天蛾科","identification_notes":"翅展 48–60 mm。体中型，粗壮肥大。属于最著名的‘昼行性天蛾’代表。其最大特征是长有长达数厘米、可自由卷曲的管状‘长长鸟喙状口器’（长喙）。飞行速度极端恐怖，能做出完美的、高超的空中长时‘定位悬停’吸蜜动作（经常在我国华北被没常识的市民和媒体误当成‘蜂鸟’报道）。体背面灰褐色，腹部末端具黑色、白色长毛簇特化成的扁平流苏状‘尾羽’；最核心识别特征是：其后翅正面以及前、后翅的反面，‘完全为鲜艳统一的纯橙黄色或橙赤色’。","habitat_notes":"本地知名度极高、在平原城区相遇率最高的一种长喙天蛾（蜂鸟鹰蛾）。广泛大范围遍布于全市任何城镇小区的绿化带、大型公园（如景山、玉渊潭、奥森）成片盛开的花丛中、以及郊区农田和山区路边野花上。成虫只在晴天强烈的阳光下疯狂活动，飞速在各个花朵间进行悬停吸蜜。","seasonality_notes":"成虫活跃期漫长，见于 3–10 月间（春夏秋季只要花开晴天皆多）。","cover_image_url":"/insects/images/macroglossum-stellatarum-1.jpg","is_active":true},{"slug":"hemaris-fuciformis","common_name":"黑边天蛾","scientific_name":"Hemaris fuciformis","aliases":[],"taxon_group":"鳞翅目 天蛾科","identification_notes":"翅展 38–45 mm。体中型偏小。属于极具代表性的‘昼行性蜂天蛾’成员。外观长相神似大马蜂或大黄蜂。最核心且惊艳的特征是：其前、后翅的‘正中央全部为没有鳞片的、完全透明无色如玻璃般的明窗区’，翅脉红褐色；翅膀的最外周边缘、布满了一圈颜色深重的、‘相当宽大的红褐色（或褐黑色）边框条带’（故名黑边天蛾）；体表密被橄榄色长毛，腹部中部红褐色、腹末端具黑色毛簇。曾长期被误定为咖啡透翅天蛾。","habitat_notes":"高颜值、擅长高超空中悬停吸蜜的黑边天蛾属模式种。在本市大范围分布但其种群数量和相遇率远不如小豆长喙天蛾多，属于随机偶见型。主要生活在低、中海拔山区的林缘灌丛草地上。只在晴天大太阳下出现，飞速在花间悬停吸蜜。","seasonality_notes":"成虫发生于 5–8 月份间（初夏到盛夏）。","cover_image_url":"/insects/images/hemaris-fuciformis-1.jpg","is_active":true},{"slug":"hemaris-ottonis","common_name":"蓝角黑边天蛾","scientific_name":"Hemaris ottonis","aliases":[],"taxon_group":"鳞翅目 天蛾科","identification_notes":"翅展 37–40 mm。体中型偏小。长相形似大黄蜂。翅正中央完全透明无鳞，翅脉纯黑褐色。其与亲缘极近的黑边天蛾的最核心识别区别特征在于：本种成虫所有的翅外缘边框条带‘为深重的、不带任何红褐色的真黑边或黑褐色边’；且其体表被毛主要为枯黄色或浅橄榄色，腹部侧面有一排黑色斑点（无红褐色带），腹末端具明显的纯黑色长毛簇。触角在强光下近观反射出美丽的‘蓝色金属光泽’（故名蓝角）。","habitat_notes":"本市山区数量最多、也最常见的一种昼行性透翅天蛾。广泛大范围分布于全市中、低海拔山区的山坡灌丛、杂草地及森林边缘。其食性与生态高度偏向野生花卉，每逢春末夏初本市山区野生的红花锦鸡儿、灌木忍冬盛开时，在花丛中具有极其庞大的数量，晴天中午疯狂飞舞悬停吸蜜。","seasonality_notes":"成虫盛发并多见于 4–8 月间。","cover_image_url":"/insects/images/hemaris-ottonis-1.jpg","is_active":true},{"slug":"samia-cynthia","common_name":"樗蚕","scientific_name":"Samia cynthia","aliases":[],"taxon_group":"鳞翅目 大蚕蛾科","identification_notes":"翅展 120–135 mm。属于本市数一数二的‘巨大型飞蛾’。两前翅的顶角外缘极强烈地向外延伸外突，使前翅整体呈尖锐的鹰钩状或镰刀状。翅正面为深黄褐色或橄榄褐色，一条连续的、明显的灰白色斜带纹从前翅前缘中部斜贯到后翅的整个臀角，斜纹外侧具红棕色晕染；每片翅正中央都长有一个清晰透明的、弯月牙状的‘新月弧纹斑’；前翅顶角具一小眼斑。","habitat_notes":"大蚕蛾科的高人气高颜值明星代表（本市唯二最极常见的大蚕蛾之一）。其幼虫食性广泛（如喜食臭椿等）。广泛大范围分布于本市所有中、低海拔山区及山脚平原地带。具有极强的夜行性和强烈的趋光性。夏夜在山区的各种路灯下、景区的大功率探照灯旁、或是山中民居的白墙窗户上具有极高遇见率。","seasonality_notes":"成虫盛发并见于盛夏时节的 6–8 月份，在 7 月份夜间进行灯诱具有极高的捕获概率。","cover_image_url":"/insects/images/samia-cynthia-1.jpg","is_active":true},{"slug":"actias-selene","common_name":"绿尾大蚕蛾","scientific_name":"Actias selene","aliases":["水青蛾"],"taxon_group":"鳞翅目 大蚕蛾科","identification_notes":"翅展 115–140 mm。体巨大型。特征极其优美震撼：其后翅的最下端、特化延长出一对极其漫长、优雅下垂并略带螺旋状旋扭的‘大长飘带状尾突’（尾突长几乎等于后翅翅面大部）；通体四翅为极其淡雅、惊艳的、半透明的‘淡水青色或薄荷绿色’；前翅前缘通体镶有一道粗大的紫红色（或紫褐色）天鹅绒状前缘带，且两翅间的中胸背板前缘也具紫红色毛带连成一体；每翅正中央长有一个弦月状的小眼斑（半黄半暗）。","habitat_notes":"本地极具传奇色彩、人气最高、完全逆袭并改变人们对飞蛾刻板印象的‘最美巨大型飞蛾’（本市唯二最极常见的大蚕蛾之一，俗称水青蛾）。广泛大范围分布于本市所有的低山、浅山、中海拔至高海拔深山区森林中，成虫夜行性极强、且具极强烈趋光性，在山区夏夜灯火下几乎必能相遇。","seasonality_notes":"在本市一年有多个世代活动，成虫主要活跃和见于 4 月、5 月（春季世代）以及 7 月、8 月（盛夏世代）。","cover_image_url":"/insects/images/actias-selene-1.jpg","is_active":true},{"slug":"actias-dubernardi","common_name":"长尾大蚕蛾","scientific_name":"Actias dubernardi","aliases":[],"taxon_group":"鳞翅目 大蚕蛾科","identification_notes":"翅展 80–120 mm。体巨大型。其具有全本地昆虫中‘最长、最大、最夸张的螺旋状超级大长尾突’，尾突长度甚至远超前翅长或头到后翅边缘的总长，飞舞时如长袖舞动。雌雄异色极其明显：雄性翅为亮丽水青色、尾突中部呈粉红色；雌性翅全为黄绿色、整个外缘和漫长尾突全为娇嫩的‘粉红色’。前翅前缘及中胸毛带均为紫红色。前翅眼斑为一个倒置的粉红加黄有黑边的‘逗号状眼斑’。","habitat_notes":"绝对的梦幻珍稀物种，若以形态尾突而论属于全本地最美、最震撼的一种大蚕蛾。在本市极度稀少罕见。具有极强的生态局限性。目前在整个北京行政区划内，已知‘仅仅在密云区雾灵山自然保护区’的少数中、高海拔针阔混交林深处有确凿的极其零星采获记录。夜行性，具有趋光性。","seasonality_notes":"成虫仅在 6–8 月间的盛夏季节有极低概率通过大功率灯诱手段在雾灵山林缘遇到。","cover_image_url":"/insects/images/actias-dubernardi-1.jpg","is_active":true},{"slug":"saturnia-boisduvali","common_name":"合目大蚕蛾","scientific_name":"Saturnia boisduvali","aliases":["蒙蚕蛾"],"taxon_group":"鳞翅目 大蚕蛾科","identification_notes":"翅展 75–107 mm。体大型，极其壮硕多毛。属于极其特殊的‘严寒活跃型大蚕蛾’。中胸及前翅基部中央密被厚重的红褐色或红棕色长毛；翅正面大部为深褐色，部分个体翅色强烈发红；前翅前半部分（前缘区）分布着由灰白色与褐色杂糅而成的特殊粉霜状花纹。每片翅正中央都长有一个大而圆的‘圆形眼斑’（内大部为红褐色，外周有粗黑边环绕，前翅眼斑常晦暗如闭目）。曾归于 Rinaca 或 Caliguna 属。","habitat_notes":"生态习性独特的秋末及初冬大蚕蛾（老文献多称蒙蚕蛾）。其主要局限分布在本市中、高海拔的栎树、栗树等壳斗科植物极其繁茂的深山区中（如门头沟小龙门、百花山、东灵山、密云雾灵山等）。虽然其种群数量在深山很大，但因其在严寒中才出来，极少有一般人能见到它。夜行性，强烈趋光。","seasonality_notes":"发生期极其靠后，成虫专性在深秋到初冬的 9–10 月份（甚至山中下雪结冰时）才大量羽化并活跃，在夜间大功率灯诱下它是绝对的优势种。","cover_image_url":"/insects/images/saturnia-boisduvali-1.jpg","is_active":true},{"slug":"saturnia-thibeta","common_name":"闭目大蚕蛾","scientific_name":"Saturnia thibeta","aliases":["藏蚕蛾","北方藏蚕蛾"],"taxon_group":"鳞翅目 大蚕蛾科","identification_notes":"翅展 100–130 mm。体巨大型，壮硕。翅正面大部全为极其鲜艳明亮的‘鲜黄色或柠檬黄色’，上面满布着一系列由褐色和黑褐色鳞片组成的复杂波状线和网格状花纹。雌雄斑纹有别。最核心识别特征是其雌雄的眼斑具有高对比度恐吓设计：其前翅的眼斑通常淡化、极其晦暗不明显（如同闭着的眼睛，故名闭目）；但其后翅的中央眼斑‘对比度极度强烈、面积巨大、宛如怒目圆睁的巨大眼睛’，眼斑内充斥红褐色花纹。曾归于 Rinaca 或 Caliguna 属。","habitat_notes":"高颜值、体色极其艳丽的秋季特有大型大蚕蛾（旧称藏蚕蛾或北方藏蚕蛾）。主要分布在本市中、高海拔的山区森林、林缘灌丛及景区中，尤以门头沟小龙门林区最为集中和多见。具有极强的夜行性、且具极强烈的趋光性，受惊扰会突然张开前翅亮出后翅的巨大眼斑来惊吓天敌。","seasonality_notes":"发生和活跃期在夏末秋初一直到秋末的 8–10 月份间，秋季在山区进行灯诱具有极高的遇见概率。","cover_image_url":"/insects/images/saturnia-thibeta-1.jpg","is_active":true},{"slug":"saturnia-pyretorum","common_name":"樟蚕","scientific_name":"Saturnia pyretorum","aliases":[],"taxon_group":"鳞翅目 大蚕蛾科","identification_notes":"翅展 100–110 mm。体大型。翅色风格古朴，完全以黑、白、灰色为主，兼有淡淡的紫褐色波状横条纹。中胸背板和前翅基部中央呈对比显著的纯黑色。两翅的最外侧边缘均有一条亮丽的‘亮白色宽边’；每片翅的中部均精确长有一个极其精致的、如同中式古典图案般的‘小圆形眼斑’（由黑、白、蓝、黄 4 种颜色的同心细圆环嵌套而成）。曾归于 Rinaca 属；德国学者近年新独立的名称为 S. cognata，尚存争议。","habitat_notes":"历史地位特殊、但因‘发生期极端另类’而极难被普通人寻见的早春山区大蚕蛾。广泛广布于本市大部山区森林中。由于其成虫在每年的早春冰雪未消、深山景区尚未开放、天气极为寒冷时便完成了羽化和交配，因而常规普查极难记录。具有极强夜行性和趋光性。","seasonality_notes":"成虫发生和活跃期极度局限在冰天雪地的早春 3–4 月份间，必须在寒风中通过灯诱手段才能寻获。","cover_image_url":"/insects/images/saturnia-pyretorum-1.jpg","is_active":true},{"slug":"loepa-wlingana","common_name":"雾灵豹蚕蛾","scientific_name":"Loepa wlingana","aliases":[],"taxon_group":"鳞翅目 大蚕蛾科","identification_notes":"翅展 60–95 mm。体中到大型。为我国已故著名昆虫学家杨集昆先生根据北京标本所正式发表的、‘唯一以雾灵山命名的大蚕蛾’。两翅正面通体为十分优雅柔和的‘淡黄色或乳黄色’，前翅顶角和前缘基部染有大面积的粉褐色或冷紫色。每翅正中央各长有一个精致的、粉红褐色与黑环相间的圆形眼斑；每片翅上均分布着 3 组平行的细波状黑色线条。雌性体型明显大于雄性且腹部节间外露很多绿色。","habitat_notes":"分类地位极端重要、创造了该南方热带属在全世界‘分布最北限记录’的著名山地珍稀大蚕蛾。其数量总体稀少，在本市属于少见种。主要栖息于本市中、高海拔山区的原始林下或密林茂密处（目前已知产地包括密云雾灵山、延庆海坨山、门头沟百花山及小龙门）。具有夜行性和趋光性。","seasonality_notes":"成虫仅在 7–8 月盛夏高山花季发生，夜间大功率灯诱是发现它的主要手段。","cover_image_url":"/insects/images/loepa-wlingana-1.jpg","is_active":true},{"slug":"aglia-tau","common_name":"丁目大蚕蛾","scientific_name":"Aglia tau","aliases":[],"taxon_group":"鳞翅目 大蚕蛾科","identification_notes":"翅展 60–75 mm。体中型。属于大蚕蛾科中极其罕见的、‘专性在白天活跃且飞翔’的特异类群。雄性成虫翅正面为极其鲜艳美丽的‘纯橘黄色’，雌性翅色较浅呈淡黄褐色；翅近端缘都有一条与翅缘轮廓高度平行的黑褐色连续整齐线条（有些雄虫整条线条外侧全部加深为宽黑边）。最核心特征是：每片翅的中部，均精确长有一个深蓝色的眼状斑，且斑正中央横贯着一个白色的‘Τ’字形或‘Υ’字形（希腊字母 Tau 状）白色细纹。","habitat_notes":"生态习性特异、飞舞姿态极度神似蝴蝶的亚高山明星大蚕蛾。广泛广布于本市所有中、高海拔的深山区原始林中（尤其是白桦林、山杨林带），在门头沟小龙门、东灵山、百花山、延庆松山等地的白桦林下，白天常见其雄虫如蝴蝶般在林间阳光斑驳的草地上低空快速飞舞。夜间对灯火也有一定趋光性。","seasonality_notes":"成虫活跃和发生于春末夏初的 5–7 月份间（ 5 月下旬山林间相遇率最高）。","cover_image_url":"/insects/images/aglia-tau-1.jpg","is_active":true},{"slug":"brahmaea-certhia","common_name":"黄褐箩纹蛾","scientific_name":"Brahmaea certhia","aliases":[],"taxon_group":"鳞翅目 箩纹蛾科","identification_notes":"翅展 120–140 mm。体型极为巨大肥硕。通体为均一的、密布特殊纹饰的黑褐色或暗黄褐色。两翅整体最核心、也最震撼的特征是：其四翅的近端外缘的一大片区域，全部由上百条极其细密、整齐平行弯曲、高对比度的‘黑白相间的连续波状细线条’组合而成了巨大的、如同‘箩筐编织纹理或似毒蛇皮斑纹’一样的复杂水波状大面积带纹（即标志性箩纹）。在特定白光或紫外灯照射下，部分特定的前翅翅脉会折射出具有强烈干涉反光感的‘蓝紫色荧光光泽’。","habitat_notes":"人气极高的明星大型黑夜飞蛾（箩纹蛾科的本市典型代表，旧文献常误称为黑褐或紫光箩纹蛾）。主要广泛广布于本市所有的中海拔及低海拔山区森林、景区、农田边缘及灌丛中。其幼虫巨大长有异形长触角状刺。成虫具有极强的夜行性、且具极强烈且持久的趋光性，在山区夏夜常大举飞向灯火。","seasonality_notes":"成虫盛发并多见于春季到仲夏的 4–7 月份间，通过夜间灯诱常有极高的相遇概率。","cover_image_url":"/insects/images/brahmaea-certhia-1.jpg","is_active":true},{"slug":"epipomponia-oncotympana","common_name":"鸣鸣蝉寄蛾","scientific_name":"Epipomponia oncotympana","aliases":[],"taxon_group":"鳞翅目 寄蛾科","identification_notes":"翅展 13–24 mm。体小型，雌性显著比雄性粗大。为我国已故著名昆虫学家杨集昆先生于 1977 年根据本地标本率先正式发表、并引起中国昆虫圈极大关注的‘传奇异形寄生性飞蛾’。雌性成虫两翅为纯黑色，前翅表面密密麻麻地‘布满了如繁星般闪亮耀眼的、蓝绿色或闪蓝色金属光泽的小斑点’；雄性翅呈普通的黑褐色。专性体外寄生在鸣鸣蝉身上。德国学者主张将其作为日本种 E. nawai 的同物异名，因其具雄虫及有性生殖等核心差异，本书暂保留杨先生发表的中文名。","habitat_notes":"在我国昆虫科普史上具有里程碑意义的、生态极端奇特的专性体外寄生性飞蛾（曾入选《中国珍稀昆虫图鉴》）。其幼虫为白色的、大腹便便的毛绒球状，专性寄生在本市山区最常见的鸣鸣蝉工蜂或雌蝉的‘腹部侧面或翅基部下方’，大口吸食蝉的体液。在香山、低山浅山、及各大山区乔木林中只要鸣鸣蝉多见的地方，本种数量往往大到惊人，寄生率极高。","seasonality_notes":"成虫与老熟幼虫发生和活跃期在夏末秋初的 8–9 月份。每逢 8 月中下旬，成千上万的老熟幼虫会纷纷吐丝从高空蝉的身上悬丝垂落到灌木上做成大量带有白色粉被的蛹化蛹，场面极其壮观。","cover_image_url":"/insects/images/epipomponia-oncotympana-1.jpg","is_active":true},{"slug":"dryinus-lycormae","common_name":"斑衣蜡蝉螯蜂","scientific_name":"Dryinus lycormae","aliases":[],"taxon_group":"膜翅目 螯蜂科","identification_notes":"体长 5.7–6.8 mm(♀)；3.2–3.5 mm(♂)。体形极小。为著名昆虫学家杨集昆先生于 1994 年根据本地标本所正式发表的、‘全本地长相最奇特、知名度最高的一种螯蜂’。其雌性成虫最决定性的特征是：其前足的跗节，极度异形特化膨大成了一个结构复杂、能够自由开合的、‘完全似螃蟹大螯或龙虾大钳状的强力控制结构’（故名螯蜂）。前翅具有高对比度的黑白相间大斑块。有学者将其归于布氏螯蜂 D. browni 的异名，因存在核心跗节及触角形态差异，本书维持杨先生的原称。","habitat_notes":"生态极其奇特、雌虫具有强大捕捉螯的专性体外寄生蜂（曾入选《中国珍稀昆虫图鉴》）。其雌虫会用其蟹钳状的前足强行控制猎物，并产卵专性寄生在本地最常见的害虫——斑衣蜡蝉的幼虫（花蹦蹦儿）身上。凡可见到斑衣蜡蝉幼虫翅芽下长有一黑色蜜囊状小突起的、即为被本种寄生的标志。因体型微小，裸眼在野外极难发现成虫，只能通过采集被寄生的斑衣蜡蝉幼虫进行人工饲养观察其羽化。","seasonality_notes":"成虫在春季及初夏的 5–7 月份间从去年的茧中破茧羽化。","cover_image_url":"/insects/images/dryinus-lycormae-1.jpg","is_active":true},{"slug":"tetramorium-caespitum","common_name":"铺道蚁","scientific_name":"Tetramorium caespitum","aliases":[],"taxon_group":"膜翅目 蚁科","identification_notes":"体长 2.6–2.8 mm(工蚁)。体形微小。以裸眼观察时，是全本地最平庸、最毫无特色的一种小黑蚂蚁。但在显微镜下，可见其头、胸部布满了极其细密、微小且成规则纵向排列的粗隆纹线，而使头胸显得极缺乏反光无光泽，仅其圆润的腹部具有明显的亮反光。","habitat_notes":"全北京城区及所有人类居住环境中、数量最大、分布最普遍、‘最常见的第一号小黑蚂蚁’。巢穴普遍挖掘在砖石缝隙、马路牙子砖块下、水泥路面边缘的缝隙中，巢口堆有极其细碎的小土粒。虽然工蚁个体微小且爬行慢，但极具大群社会性，民间俗称的‘蚂蚁搬家’或‘成千上万只大蚂蚁抱团打架’的行为景观，百分之九十以上完全是由本种所创造的。","seasonality_notes":"活跃期极其漫长，从早春到深秋的 2–11 月份间只要地表有温度，皆可见到工蚁密密麻麻地出来活动。","cover_image_url":"/insects/images/tetramorium-caespitum-1.jpg","is_active":true},{"slug":"camponotus-japonicus","common_name":"日本弓背蚁","scientific_name":"Camponotus japonicus","aliases":[],"taxon_group":"膜翅目 蚁科","identification_notes":"体长 9.2–12.9 mm(工蚁)。体型极其粗大，大型工蚁的体长可达 1.3 cm 左右，是本地‘体型最大、最壮硕的大黑蚂蚁’。通体呈高对比度的纯乌黑色，头部圆大饱满且具有较强的反光，最独特的是其粗大的腹部表面密生着一圈圈具有淡黄褐色或金黄色光泽的直立长毛。大型工蚁的上颚极其强壮发达。","habitat_notes":"本市山区及近山野地里最著名的明星大型蚂蚁种类。大范围广泛分布于全市所有的中、低海拔山区林地、山坡干旱草地、荒地以及景区的石块和山路上。其爬行速度极快、力量强，常在山路地表、树干上大摇大摆地单独或三两成群巡逻捕食，极其容易引起注意。","seasonality_notes":"工蚁的野外活动活跃期跨越 2–11 月份（春季到秋末）。","cover_image_url":"/insects/images/camponotus-japonicus-1.jpg","is_active":true},{"slug":"formica-sinae","common_name":"红林蚁","scientific_name":"Formica sinae","aliases":[],"taxon_group":"膜翅目 蚁科","identification_notes":"体长 4.5–8.3 mm(工蚁)。属于典型的小型到中型红黑双色蚂蚁。其头部大部、胸部（合胸）及六足主要呈现非常醒目的、高对比度的‘红褐色、橙红或红黄色’，而其头顶正中央以及整个圆粗的腹部则呈现深黑褐色。体表密被极细密的短绒毛，这赋予其一种极其温润的、在阳光下呈现独特的亚光丝绸般反光效果（尤其是腹部）。性情极敏感且‘神经质’，巢穴惊扰极具爆炸式乱飞奔且会疯狂上爬人身用毒酸主动进行剧烈攻击。与掘穴蚁外形几乎无差，仅可通过显微镜下腹结节顶端具有心形浅凹特征来进行精确定种区分。","habitat_notes":"虽然名为红林蚁但其实本种是在平原地区及城区绿地里分布极普遍、数量极大的本地优势种之一。其巢穴多建立在阳光充足、植被茂盛的平原野地、公园杂草丛、甚至城市的街边绿化带中。常常在草根或土表修筑有由松散土粒构成的小型蚁冢。","seasonality_notes":"工蚁的户外活动和采集活跃期见于每年的 3–10 月份间。","cover_image_url":"/insects/images/formica-sinae-1.jpg","is_active":true},{"slug":"apis-mellifera","common_name":"西方蜜蜂","scientific_name":"Apis mellifera","aliases":["意大利蜜蜂"],"taxon_group":"膜翅目 蜜蜂科","identification_notes":"体长 12–14 mm(工蜂)。体型较粗大。属于养蜂业目前最广泛大规模人工饲养的经典蜜蜂（俗称意蜂）。其最核心、最容易和中华蜜蜂相区分的宏观特征是：本种工蜂腹部的最前段（腹部基部第 1–2 节），‘被大面积、纯粹且极其鲜艳的橙黄色或红黄色所完全占据’（黑条纹极细或甚至全无，故腹部前半部分显得极为蜡黄亮眼）；且其头部的唇基部分完全为纯黑色，绝对没有黄斑。头和胸部黑色，被有极其浓密的褐色直立长毛。","habitat_notes":"本市目前在城区公园、农田作物、近山花丛以及山区最常见的第一号蜜蜂种类。具有极高的经济和生态价值。由于意蜂强烈的野外采集和霸占资源能力，其在各种春夏季人工花卉、野花上可见大量工蜂疯狂采集花粉与花蜜。","seasonality_notes":"工蜂的户外访花采集期非常漫长，见于 2–10 月份间（早春到秋末只要有花开即活动）。","cover_image_url":"/insects/images/apis-mellifera-1.jpg","is_active":true},{"slug":"apis-cerana-cerana","common_name":"中华蜜蜂","scientific_name":"Apis cerana cerana","aliases":["东方蜜蜂中华亚种","中蜂"],"taxon_group":"膜翅目 蜜蜂科","identification_notes":"体长 10–13 mm(工蜂)。整体体型常比西方蜜蜂明显‘略微小一号’且更清瘦。属于我国乃至本市最为珍贵正宗的本土原生蜜蜂（俗称中蜂）。其与西方蜜蜂的最核心、具有决定性区分的宏观三大要点是：①本种工蜂腹部从基部直到腹末，‘黑色与黄色的一条条横向环纹极为均匀、规律且等宽地交替排列’，其腹部基部绝对没有西方蜜蜂那般大面积完全蜡黄橙色的区域（整体观感黑黄相间非常规律）；②其头部的唇基正中央，‘精细长有一个非常显眼的黄白色或明黄色三角形大斑纹’（意蜂该处全黑）；③后翅中脉有分叉特征。","habitat_notes":"极其珍稀的、由于受到外来西方蜜蜂强烈生态竞争而导致野外种群大面积式微的‘本土国宝级蜜蜂’。目前全市仅有极少数山区村落（如房山、门头沟、怀柔深山）有零星人工保育饲养中蜂的蜂场，野外野生中蜂极其罕见难得一见，目前本市多地已开始划定自然保护区重点保护和抢救其中蜂资源。","seasonality_notes":"工蜂访花期在 2–10 月份间，由于其对华北本土气候适应力强，其在早春耐寒性明显好于西方蜜蜂。","cover_image_url":"/insects/images/apis-cerana-cerana-1.jpg","is_active":true},{"slug":"eristalis-tenax","common_name":"长尾管蚜蝇","scientific_name":"Eristalis tenax","aliases":[],"taxon_group":"双翅目 食蚜蝇科","identification_notes":"体长 12–15 mm。体型较大，体大粗壮。属于最著名的‘蜜蜂拟态伪装大师’（属于双翅目仅一对翅触角短，但腹部配色图案跟西方蜜蜂工蜂简直一模一样，常欺骗外行）。最核心且能一眼定种的区别特征是：其透明的前翅正中央、长有一个极明显的‘圆形黑色或黑褐色晕状大斑点’。其腹部黑色，第 2 节具有左右对称的一对非常醒目的橙黄色舌头状大斑块（可扩大使腹部呈‘工’字形黑纹）。中胸背板密被灰褐色短绒毛，但其上有几处明显的、反光的圆形光滑‘秃区’。","habitat_notes":"本市分布极广泛、平原城区数量极其庞大的第一号明星食蚜蝇成员。大范围广泛遍布于全市所有的城市中心绿地、各大公园、植物园、远郊农田及各级山区的花丛中。其高度嗜好和蜜蜂混在一起访问各种花朵吸食花蜜、传播花粉。由于双翅目特征它完全没有蜇刺绝对不会蜇人，性格温顺可直接裸眼近距离观察。","seasonality_notes":"成虫活跃期和访花期极其漫长，贯穿每年的 3–11 月份间（从早春一直到晚秋均随处可见）。","cover_image_url":"/insects/images/eristalis-tenax-1.jpg","is_active":true},{"slug":"eristalis-arbustorum","common_name":"短腹管蚜蝇","scientific_name":"Eristalis arbustorum","aliases":[],"taxon_group":"双翅目 食蚜蝇科","identification_notes":"体长 11–13 mm。体型比长尾管蚜蝇略微清瘦短小一些。同样高超拟态蜜蜂。其与长尾管蚜蝇的最核心三大识别区别要点是：①其前翅完全透明、‘绝对干净、没有任何黑色斑点或任何晕染暗斑’；②其腹部最外侧侧缘所生长的绒毛明显呈现极其‘浓密且发黄的长毛羽状’；③其腹部第 2 节背面长有一对左右对称的、边界极为清晰的‘三角形橙黄色大斑块’，且腹部第 2、3、4 节的端外缘、均具有亮橙色的横线（比长尾管蚜蝇多一节）。","habitat_notes":"山区及郊区较常见的一种访花食蚜蝇。广泛分布于本市所有的低山、近山及中海拔山林林缘的花丛中，在城区大型植物园也时有记录。成虫强烈的访花性，极喜欢围绕各种蔷薇科或菊科的小野花进行频繁盘旋。","seasonality_notes":"成虫发生和活跃期主要集中在春季到盛夏的 4–7 月份间。","cover_image_url":"/insects/images/eristalis-arbustorum-1.jpg","is_active":true},{"slug":"eristalis-cerealis","common_name":"灰带管蚜蝇","scientific_name":"Eristalis cerealis","aliases":[],"taxon_group":"双翅目 食蚜蝇科","identification_notes":"体长 11–13 mm。中型。高度完美拟态蜜蜂。其与长尾管蚜蝇、短腹管蚜蝇在宏观上最决定性、能瞬间一眼定种的核心特征是：其密被灰褐色绒毛的整个中胸背板的正中央，‘极其清晰地横贯着一条（或两条）对比明显的、宽大的浅灰色短绒毛横向条带纹（灰带）’。其腹部第 2 节背面具有一对左右对称的三角形橙色大斑，第 2、3、4 节后缘有极醒目的、反光的亮黄色横线边缘。","habitat_notes":"本市平原及城区里极常见、数量极其庞大的主力食蚜蝇之一。大范围广泛广布于城中心的小区花园、大专院校校园绿地、各大市区公园（如天坛、颐和园）、农田菜地、以及所有山区林缘、山路两侧的花丛中。成虫访花极频繁，常与长尾管蚜蝇混群在各种开花植物上吸蜜。","seasonality_notes":"成虫活跃期跨度极大，见于每年的 3–11 月份间（春夏秋季极常见）。","cover_image_url":"/insects/images/eristalis-cerealis-1.jpg","is_active":true},{"slug":"episyrphus-balteatus","common_name":"黑带蚜蝇","scientific_name":"Episyrphus balteatus","aliases":[],"taxon_group":"双翅目 食蚜蝇科","identification_notes":"体长 6–10 mm。体型明显比管蚜蝇属要细小、清瘦娇小得多。其特征极其鲜明：其窄长且扁平的整个腹部正面呈现极其明亮的、亮闪闪的橙黄色或橘黄色，且腹部的第 2、3、4 节上、‘极其规律且精细地排布着粗细成对、两两一组的横向黑色纹带’（其中第 3、4 节既有粗黑带又有细黑带，故名黑带）。中胸背板具有由锈色与浅色交替构成的纵向条纹。","habitat_notes":"本市从平原到高山数量最庞大、生态无处不在的绝对优势种小型食蚜蝇。具有一种极其独特的、极其好玩的‘人身趋向悬停’行为：成虫在飞行时具有超高超的定点‘静止悬停’技术，极度喜好保持一二十厘米的距离静静地悬停在野外行走的人类的脸前、或裸露的皮肤旁，若人保持完全静止，它会轻柔地直接停落下来用其微小口器吸食人类皮肤表面的汗液矿物质。若被驱赶，也仅飞出一小段距离再次悬停观望，极有意思。广泛出没于全本地任何花丛和林荫道中。","seasonality_notes":"成虫活跃和见于每年的 3–11 月份间，数量大到无法计数。","cover_image_url":"/insects/images/episyrphus-balteatus-1.jpg","is_active":true},{"slug":"volucella-bivitta","common_name":"双带蜂蚜蝇","scientific_name":"Volucella bivitta","aliases":[],"taxon_group":"双翅目 食蚜蝇科","identification_notes":"体长 16–18 mm。体型极其硕大、宽粗健壮，观感极壮硕。属于拟态伪装‘大型胡蜂或大马蜂’的食蚜蝇杰出代表。其色彩和花纹对比极其强烈艳丽：中胸背板为红褐色，上面‘极其特殊地整齐排列着由 5 个黑色竖条纹组成的、形似易经‘☵’（坎卦）形状的特殊黑色花纹’；圆宽的大腹部为高饱和度的橙黄色，第 2、3 节背面长有粗大的双曲状、M形的黑色宽带纹；透明的翅膀前缘呈橘黄色，且近顶角处具有一个显著的黑色晕状大斑块。","habitat_notes":"本地体型最大、也最靓丽的一种蜂蚜蝇成员。具有极明显的偏向中、高海拔针阔混交林缘或高山草原环境的冷凉性生态习性。广泛大范围分布于门头沟东灵山、百花山、小龙门、密云雾灵山等高海拔山区的林缘和亚高山大草甸上。成虫飞翔极其强健有力，强烈嗜好在山顶大草甸的各种野花（如大蓟、狼毒）上大举集群访花吸蜜。","seasonality_notes":"成虫发生和活跃期在盛夏的 6–9 月份，在高山花季相遇率极高。","cover_image_url":"/insects/images/volucella-bivitta-1.jpg","is_active":true},{"slug":"bittacus-planus","common_name":"扁蚊蝎蛉","scientific_name":"Bittacus planus","aliases":[],"taxon_group":"长翅目 蚊蝎蛉科","identification_notes":"体长 21–23 mm(含翅)。六足极其漫长细脚，整体长相神似一只大蚊，但其长着长翅目典型向下垂直延伸的‘马脸状或长蝎子状头喙’。通体黄褐色，复眼黑色。其最核心、最精美的特征是：其狭长的四翅呈均一透明的‘油黄色或淡琥珀色’，且前、后翅的端半部各分布着一组由于颜色明显加深而形成的黑褐色横向翅脉列，当其双翅在背上合拢时，裸眼观之其翅膀上如同长着‘两道黑色的横纹’。具有用长后足在空中悬挂捕食飞虫的奇异习性。","habitat_notes":"经历跨度近 30 年才最终彻底定种、创造了本地‘长翅目（目级）新记录历史’的殿堂级著名珍稀‘山区神物’昆虫。其数量总体稀少，生态特异性极强。目前在整个北京行政区划内，它仅仅极其专性地分布和出没在本市西部及北部少数几处拥有完好、阴暗潮湿、阳光几乎无法直射的原始落叶阔叶林或针阔混交林的最深处林下灌丛中（如门头沟小龙门、百花山、东灵山深处）。成虫在白天极其喜好用两只细长前足牢牢吊挂在林下极低矮的杂草、树枝下方，身体完全垂直下垂，随风摇晃进行潜伏伪装，极难被发现。夜行性，具有一定趋光性。","seasonality_notes":"成虫活动和发生期极其短暂、仅局限在 7–8 月盛夏最湿热的时节，可在极深林下通过地毯式肉眼搜寻或夜间大功率白布灯诱法寻获。","cover_image_url":"/insects/images/bittacus-planus-1.jpg","is_active":true}]$insects$::jsonb) AS item(
    slug TEXT,
    common_name TEXT,
    scientific_name TEXT,
    aliases TEXT[],
    taxon_group TEXT,
    identification_notes TEXT,
    habitat_notes TEXT,
    seasonality_notes TEXT,
    cover_image_url TEXT,
    is_active BOOLEAN
  )
),
sanitized_source AS (
  SELECT
    slug,
    common_name,
    NULLIF(scientific_name, '') AS scientific_name,
    COALESCE(aliases, ARRAY[]::TEXT[]) AS aliases,
    NULLIF(taxon_group, '') AS taxon_group,
    'insects'::TEXT AS nature_topic,
    NULLIF(identification_notes, '') AS identification_notes,
    NULLIF(habitat_notes, '') AS habitat_notes,
    NULLIF(seasonality_notes, '') AS seasonality_notes,
    NULLIF(cover_image_url, '') AS cover_image_url,
    COALESCE(is_active, TRUE) AS is_active
  FROM source
),
updated_species AS (
  UPDATE public.species AS target
     SET common_name = src.common_name,
         scientific_name = src.scientific_name,
         aliases = src.aliases,
         taxon_group = src.taxon_group,
         nature_topic = src.nature_topic,
         identification_notes = src.identification_notes,
         habitat_notes = src.habitat_notes,
         seasonality_notes = src.seasonality_notes,
         cover_image_url = COALESCE(src.cover_image_url, target.cover_image_url),
         is_active = src.is_active,
         updated_at = now()
    FROM sanitized_source AS src
   WHERE target.slug = src.slug
      OR (target.scientific_name IS NOT NULL AND target.scientific_name = src.scientific_name)
  RETURNING target.id
)
INSERT INTO public.species (
  slug,
  common_name,
  scientific_name,
  aliases,
  taxon_group,
  nature_topic,
  identification_notes,
  habitat_notes,
  seasonality_notes,
  cover_image_url,
  is_active
)
SELECT
  src.slug,
  src.common_name,
  src.scientific_name,
  src.aliases,
  src.taxon_group,
  src.nature_topic,
  src.identification_notes,
  src.habitat_notes,
  src.seasonality_notes,
  src.cover_image_url,
  src.is_active
FROM sanitized_source AS src
WHERE NOT EXISTS (
  SELECT 1
  FROM public.species AS target
  WHERE target.slug = src.slug
     OR (target.scientific_name IS NOT NULL AND target.scientific_name = src.scientific_name)
);
